// 바꾸기 전 파일은 .backup-board 폴더에 저장돼요.
const fs = require('fs');
const path = require('path');
const FILES = {
    "components/Boards/AgreementMakeBoard.tsx": "import React, { useState } from 'react';\nimport {\n    View,\n    Text,\n    StyleSheet,\n    SafeAreaView,\n    TouchableOpacity,\n    TextInput,\n    Image,\n    Alert,\n} from 'react-native';\nimport { useAuth } from '@/components/contexts/AuthProvider';\nimport { router } from 'expo-router';\nimport { Ionicons } from '@expo/vector-icons';\nimport AppHeader from '@/components/AppHeader';\n\nconst AgreementMakeBoard = () => {\n    const { currentUser } = useAuth();\n\n    const [nickname] = useState(currentUser?.nickname || '');\n    const [phoneNumber] = useState(currentUser?.phoneNumber || '');\n    const [profileImage] = useState(currentUser?.profileImage || null);\n    const [isLoading, setIsLoading] = useState(false);\n\n    const formattedPhoneNumber = phoneNumber\n        ? `${phoneNumber.slice(0, 3)}-${phoneNumber.slice(3, 7)}-${phoneNumber.slice(7)}`\n        : '전화번호 없음';\n\n    const handleAgree = async () => {\n        setIsLoading(true);\n        try {\n            // \"동의\" 버튼을 누른 후, 바로 'MakeBoard' 화면으로 이동합니다.\n            router.replace('/MakeBoard');\n        } catch (error) {\n            console.error('동의 처리 오류:', error);\n            Alert.alert('오류', '동의 처리 중 문제가 발생했습니다.');\n        } finally {\n            setIsLoading(false);\n        }\n    };\n\n    const handleCancel = () => {\n        router.back();\n    };\n\n    return (\n        <View style={styles.container}>\n            {/* 공통 헤더 */}\n            <AppHeader title=\"게시글 작성 동의\" onBack={() => { if (!isLoading) handleCancel(); }} />\n\n            <View style={styles.content}>\n                <View style={styles.profileContainer}>\n                    {profileImage ? (\n                        <Image source={{ uri: profileImage }} style={styles.profileImage} />\n                    ) : (\n                        <View style={styles.defaultProfileImage}>\n                            <Ionicons name=\"person\" size={40} color=\"#4E7D32\" />\n                        </View>\n                    )}\n                </View>\n\n                <View style={styles.inputContainer}>\n                    <TextInput\n                        style={[styles.textInput, styles.disabledInput]}\n                        value={nickname}\n                        placeholder=\"닉네임\"\n                        placeholderTextColor=\"#A3A794\"\n                        editable={false}\n                    />\n                    <TextInput\n                        style={[styles.textInput, styles.disabledInput]}\n                        value={formattedPhoneNumber}\n                        placeholder=\"전화번호\"\n                        placeholderTextColor=\"#A3A794\"\n                        editable={false}\n                    />\n                </View>\n\n                <Text style={styles.descriptionText}>\n                    게시판에 게시글을 등록하려면{' '}\n                    <Text style={{ fontWeight: 'bold' }}>닉네임과 전화번호 공개에 동의</Text>\n                    해야 합니다.\n                </Text>\n\n                <View style={styles.buttonContainer}>\n                    <TouchableOpacity\n                        style={[styles.button, styles.buttonActive]}\n                        onPress={handleAgree}\n                        disabled={isLoading}\n                    >\n                        <Text style={[styles.buttonText, styles.buttonTextActive]}>\n                            동의\n                        </Text>\n                    </TouchableOpacity>\n                    <TouchableOpacity\n                        style={[styles.button, styles.cancelButton]}\n                        onPress={handleCancel}\n                        disabled={isLoading}\n                    >\n                        <Text style={[styles.buttonText, styles.cancelButtonText]}>\n                            취소\n                        </Text>\n                    </TouchableOpacity>\n                </View>\n            </View>\n        </View>\n    );\n};\n\nconst styles = StyleSheet.create({\n    container: {\n        flex: 1,\n        backgroundColor: '#fff',\n    },\n    header: {\n        flexDirection: 'row',\n        justifyContent: 'space-between',\n        alignItems: 'center',\n        paddingHorizontal: 20,\n        paddingVertical: 15,\n        backgroundColor: '#fff',\n        borderBottomWidth: 1,\n        borderBottomColor: '#EEF0E4',\n    },\n    headerTitle: {\n        fontSize: 20,\n        fontWeight: 'bold',\n        color: '#2E3326',\n    },\n    headerPlaceholder: {\n        width: 24,\n    },\n    content: {\n        flex: 1,\n        alignItems: 'center',\n        paddingHorizontal: 24,\n        paddingTop: 40,\n        paddingBottom: 20,\n    },\n    profileContainer: {\n        alignItems: 'center',\n        marginBottom: 40,\n    },\n    profileImage: {\n        width: 120,\n        height: 120,\n        borderRadius: 60,\n        borderWidth: 2,\n        borderColor: '#000',\n    },\n    defaultProfileImage: {\n        width: 120,\n        height: 120,\n        borderRadius: 60,\n        borderWidth: 2,\n        borderColor: '#000',\n        justifyContent: 'center',\n        alignItems: 'center',\n        backgroundColor: '#EEF0E4',\n    },\n    inputContainer: {\n        width: '100%',\n        marginBottom: 30,\n        gap: 15,\n    },\n    textInput: {\n        width: '100%',\n        height: 50,\n        borderWidth: 1,\n        borderColor: '#000',\n        borderRadius: 8,\n        paddingHorizontal: 15,\n        fontSize: 16,\n    },\n    disabledInput: {\n        backgroundColor: '#EEF0E4',\n        color: '#7C8070',\n    },\n    descriptionText: {\n        fontSize: 14,\n        textAlign: 'center',\n        color: '#7C8070',\n        lineHeight: 22,\n        marginBottom: 40,\n    },\n    buttonContainer: {\n        flexDirection: 'row',\n        width: '100%',\n        justifyContent: 'space-between',\n    },\n    button: {\n        flex: 1,\n        height: 50,\n        borderRadius: 8,\n        justifyContent: 'center',\n        alignItems: 'center',\n        marginHorizontal: 5,\n        borderWidth: 1,\n        borderColor: '#000',\n    },\n    buttonActive: {\n        backgroundColor: '#000',\n    },\n    buttonInactive: {\n        backgroundColor: '#EEF0E4',\n        borderColor: '#DADDCB',\n    },\n    buttonText: {\n        fontSize: 16,\n        fontWeight: 'bold',\n    },\n    buttonTextActive: {\n        color: '#fff',\n    },\n    buttonTextInactive: {\n        color: '#A3A794',\n    },\n    cancelButton: {\n        backgroundColor: '#fff',\n    },\n    cancelButtonText: {\n        color: '#000',\n    },\n});\n\nexport default AgreementMakeBoard;",
    "components/Boards/BoardMain.tsx": "import React, { useState } from 'react';\nimport {\n    View,\n    Text,\n    StyleSheet,\n    ScrollView,\n    TouchableOpacity,\n    TextInput,\n    SafeAreaView,\n    Image,\n} from 'react-native';\nimport { router } from \"expo-router\";\nimport { useBoard, BoardPost } from '@/components/contexts/BoardContext';\nimport { Ionicons } from '@expo/vector-icons';\nimport { THEME } from '@/constants/theme';\nimport { toImageUrl } from '@/config';\n\nconst BoardMain = () => {\n    const { posts } = useBoard();\n    const [selectedCategory, setSelectedCategory] = useState<string>('전체');\n    const [searchText, setSearchText] = useState<string>('');\n\n    const categories = ['전체', '교육', '운동', '활동'];\n\n    const filteredPosts = posts.filter(post => {\n        const matchesCategory = selectedCategory === '전체' || post.category === selectedCategory;\n        const matchesSearch = post.title.toLowerCase().includes(searchText.toLowerCase()) || post.author.toLowerCase().includes(searchText.toLowerCase());\n        return matchesCategory && matchesSearch;\n    });\n\n    const MessageIcon = () => (\n        <View style={styles.messageIcon}>\n            <Text style={styles.messageIconText}>💬</Text>\n        </View>\n    );\n\n    const PostItem = ({ post }: { post: BoardPost }) => (\n        <TouchableOpacity style={styles.postContainer}>\n            <View style={styles.authorSection}>\n                <View style={styles.authorAvatar}>\n                    {/* 게시글 작성자의 프로필 이미지를 렌더링 */}\n                    {post.profileImage ? (\n                        <Image source={{ uri: toImageUrl(post.profileImage) }} style={styles.avatarImage} />\n                    ) : (\n                        <View style={styles.defaultAvatar}>\n                            <Ionicons name=\"person-circle-outline\" size={40} color={THEME.placeholder} />\n                        </View>\n                    )}\n                </View>\n                <Text style={styles.authorName}>{post.author}</Text>\n            </View>\n            <View style={styles.postContent}>\n                <Text style={styles.postTitle}>{post.title}</Text>\n                <View style={styles.postMeta}>\n                    <View style={styles.postCategoryTag}>\n                        <Text style={styles.postCategoryText}>{post.category}</Text>\n                    </View>\n                </View>\n            </View>\n            <View style={styles.messageSection}>\n                <TouchableOpacity style={styles.messageButton}>\n                    <MessageIcon />\n                </TouchableOpacity>\n            </View>\n        </TouchableOpacity>\n    );\n\n    return (\n        <SafeAreaView style={styles.container}>\n            <View style={styles.header}>\n                <View style={styles.searchContainer}>\n                    <View style={styles.searchInputWrapper}>\n                        <Ionicons name=\"search-outline\" size={20} color={THEME.icon} style={styles.searchIcon} />\n                        <TextInput\n                            style={styles.searchInput}\n                            placeholder=\"게시글 검색...\"\n                            value={searchText}\n                            onChangeText={setSearchText}\n                            placeholderTextColor={THEME.placeholder}\n                        />\n                        {searchText.length > 0 && (\n                            <TouchableOpacity\n                                onPress={() => setSearchText('')}\n                                style={styles.clearButton}\n                            >\n                                <Ionicons name=\"close-circle\" size={20} color={THEME.icon} />\n                            </TouchableOpacity>\n                        )}\n                    </View>\n                </View>\n            </View>\n\n            <View style={styles.categoryFilterContainer}>\n                <ScrollView\n                    horizontal\n                    showsHorizontalScrollIndicator={false}\n                    contentContainerStyle={styles.categoryScrollContent}\n                >\n                    {categories.map((category) => (\n                        <TouchableOpacity\n                            key={category}\n                            style={[\n                                styles.categoryFilterButton,\n                                selectedCategory === category && styles.selectedCategoryFilterButton,\n                            ]}\n                            onPress={() => setSelectedCategory(category)}\n                        >\n                            <Text\n                                style={[\n                                    styles.categoryFilterButtonText,\n                                    selectedCategory === category && styles.selectedCategoryFilterButtonText,\n                                ]}\n                            >\n                                {category}\n                            </Text>\n                        </TouchableOpacity>\n                    ))}\n                </ScrollView>\n            </View>\n\n            <ScrollView style={styles.postsScrollView} contentContainerStyle={{ paddingBottom: 170 }}>\n                {filteredPosts.map((post) => (\n                    <PostItem key={post.id} post={post} />\n                ))}\n                {filteredPosts.length === 0 && (\n                    <View style={styles.emptyBox}>\n                        <Text style={styles.emptyEmoji}>📝</Text>\n                        <Text style={styles.emptyText}>아직 게시글이 없어요</Text>\n                    </View>\n                )}\n            </ScrollView>\n\n            {/* 글쓰기 버튼 (오른쪽 아래) */}\n            <TouchableOpacity\n                style={styles.addButton}\n                onPress={() => router.push('/AgreementMakeBoard')}\n                activeOpacity={0.85}\n                accessibilityLabel=\"글쓰기\"\n            >\n                <Ionicons name=\"create-outline\" size={24} color=\"#fff\" />\n            </TouchableOpacity>\n        </SafeAreaView>\n    );\n};\n\nconst styles = StyleSheet.create({\n    container: {\n        flex: 1,\n        backgroundColor: THEME.background\n    },\n    header: {\n        paddingHorizontal: 16,\n        paddingTop: 12,\n        paddingBottom: 4,\n    },\n    headerTop: {\n        flexDirection: 'row',\n        justifyContent: 'space-between',\n        alignItems: 'center',\n        marginBottom: 15,\n    },\n    title: {\n        fontSize: 28,\n        fontWeight: 'bold',\n        color: THEME.text,\n        letterSpacing: -0.5,\n    },\n    addButton: {\n        position: 'absolute',\n        right: 20,\n        bottom: 110,\n        width: 56,\n        height: 56,\n        borderRadius: 28,\n        backgroundColor: THEME.primary,\n        justifyContent: 'center',\n        alignItems: 'center',\n        shadowColor: THEME.primary,\n        shadowOffset: {\n            width: 0,\n            height: 2,\n        },\n        shadowOpacity: 0.25,\n        shadowRadius: 3.84,\n        elevation: 5,\n    },\n    searchContainer: {\n        width: '100%',\n    },\n    searchInputWrapper: {\n        flexDirection: 'row',\n        alignItems: 'center',\n        backgroundColor: '#FFFFFF',\n        borderRadius: 16,\n        paddingHorizontal: 15,\n        height: 44,\n        borderWidth: 1,\n        borderColor: THEME.line,\n    },\n    searchIcon: {\n        marginRight: 10,\n    },\n    searchInput: {\n        flex: 1,\n        fontSize: 16,\n        color: THEME.text,\n        paddingVertical: 0,\n    },\n    clearButton: {\n        padding: 2,\n    },\n    categoryFilterContainer: {\n        paddingVertical: 10,\n    },\n    categoryScrollContent: {\n        paddingHorizontal: 16,\n        gap: 10,\n    },\n    categoryFilterButton: {\n        paddingHorizontal: 18,\n        paddingVertical: 8,\n        borderRadius: 20,\n        backgroundColor: '#FFFFFF',\n        borderWidth: 1,\n        borderColor: THEME.line,\n        minWidth: 60,\n        alignItems: 'center',\n    },\n    selectedCategoryFilterButton: {\n        backgroundColor: THEME.primary,\n        borderColor: THEME.primary,\n    },\n    categoryFilterButtonText: {\n        fontSize: 14,\n        color: THEME.subText,\n        fontWeight: '600',\n    },\n    selectedCategoryFilterButtonText: {\n        color: '#fff'\n    },\n    postsScrollView: {\n        flex: 1,\n        paddingHorizontal: 16,\n        paddingTop: 12,\n    },\n    emptyBox: {\n        alignItems: 'center',\n        paddingVertical: 60,\n    },\n    emptyEmoji: {\n        fontSize: 40,\n        marginBottom: 8,\n    },\n    emptyText: {\n        fontSize: 15,\n        color: THEME.subText,\n    },\n    postContainer: {\n        flexDirection: 'row',\n        backgroundColor: '#fff',\n        borderRadius: 18,\n        paddingVertical: 16,\n        paddingHorizontal: 4,\n        marginBottom: 12,\n        borderWidth: 1,\n        borderColor: THEME.line,\n        alignItems: 'center',\n        shadowColor: THEME.subText,\n        shadowOffset: {\n            width: 0,\n            height: 1,\n        },\n        shadowOpacity: 0.05,\n        shadowRadius: 2,\n        elevation: 1,\n    },\n    authorSection: {\n        width: 60,\n        alignItems: 'center',\n        paddingRight: 12\n    },\n    authorAvatar: {\n        width: 42,\n        height: 42,\n        borderRadius: 21,\n        justifyContent: 'center',\n        alignItems: 'center',\n        borderWidth: 1,\n        borderColor: THEME.line,\n        marginBottom: 6,\n        overflow: 'hidden'\n    },\n    avatarImage: {\n        width: '100%',\n        height: '100%',\n        borderRadius: 21,\n        resizeMode: 'cover'\n    },\n    defaultAvatar: {\n        width: 42,\n        height: 42,\n        borderRadius: 21,\n        justifyContent: 'center',\n        alignItems: 'center',\n        borderWidth: 1,\n        borderColor: THEME.line,\n        marginBottom: 6,\n        overflow: 'hidden',\n        backgroundColor: '#F4F6EC'\n    },\n    authorName: {\n        fontSize: 12,\n        color: THEME.subText,\n        fontWeight: '500',\n    },\n    postContent: {\n        flex: 1,\n        justifyContent: 'center',\n        paddingRight: 12\n    },\n    postTitle: {\n        fontSize: 16,\n        color: THEME.text,\n        lineHeight: 22,\n        fontWeight: '600',\n        marginBottom: 8\n    },\n    postMeta: {\n        flexDirection: 'row',\n        alignItems: 'center',\n        gap: 8\n    },\n    postCategoryTag: {\n        paddingHorizontal: 12,\n        paddingVertical: 6,\n        backgroundColor: '#F4F6EC',\n        borderRadius: 12,\n        borderWidth: 1,\n        borderColor: THEME.line\n    },\n    postCategoryText: {\n        fontSize: 12,\n        color: THEME.subText,\n        fontWeight: '500'\n    },\n    messageSection: {\n        width: 50,\n        alignItems: 'center',\n        justifyContent: 'center'\n    },\n    messageButton: {\n        width: 40,\n        height: 40,\n        borderRadius: 20,\n        backgroundColor: '#F4F6EC',\n        borderWidth: 1,\n        borderColor: THEME.line,\n        justifyContent: 'center',\n        alignItems: 'center'\n    },\n    messageIcon: {\n        justifyContent: 'center',\n        alignItems: 'center'\n    },\n    messageIconText: {\n        fontSize: 18\n    },\n});\n\nexport default BoardMain;",
    "components/Boards/MakeBoard.tsx": "// src/screens/MakeBoard.tsx\nimport React, { useState } from 'react';\nimport {\n    View,\n    Text,\n    StyleSheet,\n    SafeAreaView,\n    TouchableOpacity,\n    TextInput,\n    Alert,\n    ScrollView,\n    KeyboardAvoidingView,\n    Platform,\n    Image,\n} from 'react-native';\nimport { router, useLocalSearchParams } from 'expo-router';\nimport { toImageUrl } from '@/config';\nimport { Ionicons } from '@expo/vector-icons';\nimport { useAuth } from '@/components/contexts/AuthProvider';\nimport { useBoard } from '@/components/contexts/BoardContext';\nimport AppHeader from '@/components/AppHeader';\n\nconst MakeBoard = () => {\n    const { currentUser } = useAuth();\n    const { posts, addPost, updatePost } = useBoard();\n\n    // 내 게시판에서 '수정'을 누르면 ?id=글번호 로 들어와요 → 수정 모드\n    const params = useLocalSearchParams<{ id?: string }>();\n    const editingPost = params.id ? posts.find((p) => String(p.id) === String(params.id)) : undefined;\n    const isEdit = !!editingPost;\n\n    const [title, setTitle] = useState(editingPost?.title ?? '');\n    const [content, setContent] = useState(editingPost?.content ?? '');\n    const [selectedCategory, setSelectedCategory] = useState<'교육' | '운동' | '활동' | ''>(editingPost?.category ?? '');\n    const [isLoading, setIsLoading] = useState(false);\n\n    const categories: { key: '교육' | '운동' | '활동'; label: string }[] = [\n        { key: '교육', label: '교육' },\n        { key: '운동', label: '운동' },\n        { key: '활동', label: '활동' },\n    ];\n\n    const handleBack = () => {\n        if (title.trim() || content.trim()) {\n            Alert.alert(\n                '작성 취소',\n                '작성 중인 내용이 있습니다. 정말 나가시겠습니까?',\n                [\n                    { text: '계속 작성', style: 'cancel' },\n                    { text: '나가기', style: 'destructive', onPress: () => router.back() },\n                ]\n            );\n        } else {\n            router.back();\n        }\n    };\n\n    const validateForm = () => {\n        if (!title.trim()) {\n            Alert.alert('알림', '제목을 입력해주세요.');\n            return false;\n        }\n        if (!content.trim()) {\n            Alert.alert('알림', '내용을 입력해주세요.');\n            return false;\n        }\n        if (!selectedCategory) {\n            Alert.alert('알림', '카테고리를 선택해주세요.');\n            return false;\n        }\n        if (title.trim().length > 50) {\n            Alert.alert('알림', '제목은 50자 이내로 입력해주세요.');\n            return false;\n        }\n        if (content.trim().length > 500) {\n            Alert.alert('알림', '내용은 500자 이내로 입력해주세요.');\n            return false;\n        }\n        return true;\n    };\n\n    const handleSubmit = async () => {\n        if (!validateForm()) return;\n\n        setIsLoading(true);\n        try {\n            const fields = {\n                title: title.trim(),\n                content: content.trim(),\n                category: selectedCategory as '교육' | '운동' | '활동',\n            };\n\n            if (isEdit && editingPost) {\n                updatePost(editingPost.id, fields);\n            } else {\n                addPost({\n                    author: currentUser?.name || '익명',\n                    profileImage: currentUser?.profileImage || null,\n                    ...fields,\n                });\n            }\n\n            Alert.alert(\n                isEdit ? '게시글 수정 완료' : '게시글 등록 완료',\n                isEdit ? '게시글이 수정되었습니다.' : '게시글이 성공적으로 등록되었습니다.',\n                [\n                    {\n                        text: '확인',\n                        onPress: () => {\n                            router.back();\n                        },\n                    },\n                ]\n            );\n        } catch (error) {\n            console.error('게시글 등록 오류:', error);\n            Alert.alert('오류', '게시글 등록 중 문제가 발생했습니다.');\n        } finally {\n            setIsLoading(false);\n        }\n    };\n\n    const isSubmitDisabled = !title.trim() || !content.trim() || !selectedCategory || isLoading;\n\n    return (\n        <View style={styles.container}>\n            <KeyboardAvoidingView\n                behavior={Platform.OS === 'ios' ? 'padding' : 'height'}\n                style={styles.keyboardAvoidingView}\n            >\n                {/* 공통 헤더: < 게시글 작성 [등록] 🔔 */}\n                <AppHeader\n                    title={isEdit ? '게시글 수정' : '게시글 작성'}\n                    onBack={() => { if (!isLoading) handleBack(); }}\n                    right={[{ label: isEdit ? '저장' : '등록', onPress: handleSubmit, disabled: isSubmitDisabled, color: '#4E7D32' }]}\n                />\n\n                <ScrollView style={styles.content} showsVerticalScrollIndicator={false}>\n\n                    <View style={styles.sectionContainer}>\n                        <Text style={styles.sectionTitle}>작성자 정보</Text>\n                        <View style={styles.authorInfoContainer}>\n                            {currentUser?.profileImage ? (\n                                <Image source={{ uri: toImageUrl(currentUser.profileImage) }} style={styles.profileImage} />\n                            ) : (\n                                <View style={styles.defaultProfileImage}>\n                                    <Ionicons name=\"person\" size={24} color=\"#4E7D32\" />\n                                </View>\n                            )}\n                            <View>\n                                <Text style={styles.authorInfo}>\n                                    닉네임: {currentUser?.name || '익명'}\n                                </Text>\n                                <Text style={styles.authorInfo}>\n                                    전화번호: {currentUser?.phoneNumber\n                                    ? `${currentUser.phoneNumber.slice(0, 3)}-${currentUser.phoneNumber.slice(3, 7)}-${currentUser.phoneNumber.slice(7)}`\n                                    : '전화번호 없음'\n                                }\n                                </Text>\n                            </View>\n                        </View>\n                    </View>\n\n                    <View style={styles.sectionContainer}>\n                        <Text style={styles.sectionTitle}>카테고리 <Text style={styles.required}>*</Text></Text>\n                        <View style={styles.categoryContainer}>\n                            {categories.map((category) => (\n                                <TouchableOpacity\n                                    key={category.key}\n                                    style={[\n                                        styles.categoryButton,\n                                        selectedCategory === category.key && styles.selectedCategoryButton,\n                                    ]}\n                                    onPress={() => setSelectedCategory(category.key)}\n                                    disabled={isLoading}\n                                >\n                                    <Text\n                                        style={[\n                                            styles.categoryButtonText,\n                                            selectedCategory === category.key && styles.selectedCategoryButtonText,\n                                        ]}\n                                    >\n                                        {category.label}\n                                    </Text>\n                                </TouchableOpacity>\n                            ))}\n                        </View>\n                    </View>\n\n                    <View style={styles.sectionContainer}>\n                        <View style={styles.titleContainer}>\n                            <Text style={styles.sectionTitle}>제목 <Text style={styles.required}>*</Text></Text>\n                            <Text style={styles.charCount}>{title.length}/50</Text>\n                        </View>\n                        <TextInput\n                            style={styles.titleInput}\n                            placeholder=\"제목을 입력하세요\"\n                            value={title}\n                            onChangeText={setTitle}\n                            maxLength={50}\n                            editable={!isLoading}\n                            placeholderTextColor=\"#A3A794\"\n                        />\n                    </View>\n\n                    <View style={styles.sectionContainer}>\n                        <View style={styles.titleContainer}>\n                            <Text style={styles.sectionTitle}>내용 <Text style={styles.required}>*</Text></Text>\n                            <Text style={styles.charCount}>{content.length}/500</Text>\n                        </View>\n                        <TextInput\n                            style={styles.contentInput}\n                            placeholder=\"내용을 입력하세요\"\n                            value={content}\n                            onChangeText={setContent}\n                            maxLength={500}\n                            multiline\n                            textAlignVertical=\"top\"\n                            editable={!isLoading}\n                            placeholderTextColor=\"#A3A794\"\n                        />\n                    </View>\n                </ScrollView>\n            </KeyboardAvoidingView>\n        </View>\n    );\n};\n\nconst styles = StyleSheet.create({\n    container: { flex: 1, backgroundColor: '#fff' },\n    keyboardAvoidingView: { flex: 1 },\n    header: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', paddingHorizontal: 20, paddingVertical: 15, backgroundColor: '#fff', borderBottomWidth: 1, borderBottomColor: '#EEF0E4' },\n    headerTitle: { fontSize: 20, fontWeight: 'bold', color: '#2E3326' },\n    submitButton: { paddingHorizontal: 16, paddingVertical: 8, backgroundColor: '#000', borderRadius: 8 },\n    submitButtonDisabled: { backgroundColor: '#C9CCB8' },\n    submitButtonText: { color: '#fff', fontSize: 16, fontWeight: 'bold' },\n    submitButtonTextDisabled: { color: '#A3A794' },\n    content: { flex: 1, paddingHorizontal: 20, paddingTop: 20 },\n    sectionContainer: { marginBottom: 30 },\n    sectionTitle: { fontSize: 16, fontWeight: 'bold', color: '#2E3326', marginBottom: 12 },\n    required: { color: '#ff4444' },\n    titleContainer: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12 },\n    charCount: { fontSize: 12, color: '#A3A794' },\n    categoryContainer: { flexDirection: 'row', gap: 10 },\n    categoryButton: { paddingHorizontal: 16, paddingVertical: 10, borderRadius: 8, borderWidth: 1, borderColor: '#DADDCB', backgroundColor: '#fff' },\n    selectedCategoryButton: { backgroundColor: '#000', borderColor: '#000' },\n    categoryButtonText: { fontSize: 14, color: '#7C8070', fontWeight: '500' },\n    selectedCategoryButtonText: { color: '#fff' },\n    titleInput: { borderWidth: 1, borderColor: '#DADDCB', borderRadius: 8, paddingHorizontal: 15, paddingVertical: 12, fontSize: 16, backgroundColor: '#FBFAF4' },\n    contentInput: { borderWidth: 1, borderColor: '#DADDCB', borderRadius: 8, paddingHorizontal: 15, paddingVertical: 12, fontSize: 16, backgroundColor: '#FBFAF4', minHeight: 150 },\n    authorInfoContainer: { flexDirection: 'row', alignItems: 'center', backgroundColor: '#FBFAF4', padding: 15, borderRadius: 8, borderWidth: 1, borderColor: '#DADDCB' },\n    profileImage: { width: 40, height: 40, borderRadius: 20, marginRight: 10 },\n    defaultProfileImage: { width: 40, height: 40, borderRadius: 20, justifyContent: 'center', alignItems: 'center', backgroundColor: '#E6E8DA', marginRight: 10 },\n    authorInfo: { fontSize: 14, color: '#7C8070', marginBottom: 5 },\n});\n\nexport default MakeBoard;",
    "components/Boards/MyBoard.tsx": "import React, { useState } from 'react';\nimport {\n    View,\n    Text,\n    StyleSheet,\n    ScrollView,\n    TouchableOpacity,\n    TextInput,\n    SafeAreaView,\n    Image,\n    Alert,\n} from 'react-native';\nimport { router } from 'expo-router';\nimport { toImageUrl } from '@/config';\nimport { useBoard, BoardPost } from '@/components/contexts/BoardContext';\nimport { useAuth } from '@/components/contexts/AuthProvider';\nimport { useOnlineClass, ClassData } from '@/components/contexts/OnlineClassContext';\nimport { Ionicons } from '@expo/vector-icons';\nimport OnlineClassMyDetail from \"@/components/OnlineClass/OnlineClassMyDetail\";\nimport AppHeader from '@/components/AppHeader';\n\ninterface TabButtonProps {\n    title: string;\n    isActive: boolean;\n    onPress: () => void;\n}\n\nconst TabButton: React.FC<TabButtonProps> = ({ title, isActive, onPress }) => (\n    <TouchableOpacity\n        style={[styles.tabButton, isActive && styles.activeTabButton]}\n        onPress={onPress}\n        activeOpacity={0.7}\n    >\n        <Text style={[styles.tabButtonText, isActive && styles.activeTabButtonText]}>\n            {title}\n        </Text>\n    </TouchableOpacity>\n);\n\nconst MyBoard = () => {\n    const { posts, deletePost } = useBoard();\n    const { currentUser } = useAuth();\n    const { classes } = useOnlineClass();\n    const [activeTab, setActiveTab] = useState<'board' | 'onlineClass'>('board');\n    const [selectedCategory, setSelectedCategory] = useState<string>('전체');\n    const [searchText, setSearchText] = useState<string>('');\n\n    const categories = ['전체', '교육', '운동', '활동'];\n\n    // 현재 사용자가 작성한 게시글만 필터링\n    const myPosts = posts.filter(post => post.author === currentUser?.name);\n\n    // 현재 사용자가 생성한 온라인 수업만 필터링\n    const myClasses = classes.filter(classItem => classItem.createdBy === currentUser?.name);\n\n    const filteredPosts = myPosts.filter(post => {\n        const matchesCategory = selectedCategory === '전체' || post.category === selectedCategory;\n        const matchesSearch = post.title.toLowerCase().includes(searchText.toLowerCase());\n        return matchesCategory && matchesSearch;\n    });\n\n    const getHeaderTitle = () => {\n        switch (activeTab) {\n            case 'board':\n                return '내 게시글';\n            case 'onlineClass':\n                return '내 온라인 수업';\n            default:\n                return '내 게시글';\n        }\n    };\n\n    const getCreateButtonText = () => {\n        switch (activeTab) {\n            case 'board':\n                return '게시글 작성하기';\n            case 'onlineClass':\n                return '온라인 수업 만들기';\n            default:\n                return '게시글 작성하기';\n        }\n    };\n\n    const getEmptyStateText = () => {\n        switch (activeTab) {\n            case 'board':\n                return {\n                    title: '작성한 게시글이 없습니다',\n                    description: '첫 번째 게시글을 작성해보세요!'\n                };\n            case 'onlineClass':\n                return {\n                    title: '생성한 온라인 수업이 없습니다',\n                    description: '첫 번째 온라인 수업을 만들어보세요!'\n                };\n            default:\n                return {\n                    title: '작성한 게시글이 없습니다',\n                    description: '첫 번째 게시글을 작성해보세요!'\n                };\n        }\n    };\n\n    const handleCreatePress = () => {\n        if (activeTab === 'board') {\n            // 탭 안의 화면에서는 router.push 로 이동해요\n            router.push('/AgreementMakeBoard');\n        } else {\n            router.push('/MakeOnlineClass');\n        }\n    };\n\n    const handleEditPost = (post: BoardPost) => {\n        router.push({ pathname: '/MakeBoard', params: { id: String(post.id) } });\n    };\n\n    const handleDeletePost = (postId: number, postTitle: string) => {\n        const itemType = activeTab === 'board' ? '게시글' : '온라인 수업';\n        Alert.alert(\n            `${itemType} 삭제`,\n            `\"${postTitle}\" ${itemType}을(를) 삭제하시겠습니까?`,\n            [\n                { text: '취소', style: 'cancel' },\n                {\n                    text: '삭제',\n                    style: 'destructive',\n                    onPress: () => {\n                        if (deletePost) {\n                            deletePost(postId);\n                        }\n                    }\n                },\n            ]\n        );\n    };\n\n    const handleOnlineClassPress = (classItem: ClassData) => {\n        router.push({ pathname: '/OnlineClassMyDetail', params: {\n            id: String(classItem.id),\n            title: classItem.title,\n            instructor: classItem.instructor,\n            profileImage: classItem.profileImage,\n            introduction: classItem.introduction,\n            description: classItem.description,\n            rating: '0', // 기본값\n            reviewCount: '0', // 기본값\n        } });\n    };\n\n    const formatTimeAgo = (createdAt: Date) => {\n        const now = new Date();\n        const diffInMs = now.getTime() - createdAt.getTime();\n        const diffInMinutes = Math.floor(diffInMs / (1000 * 60));\n        const diffInHours = Math.floor(diffInMs / (1000 * 60 * 60));\n        const diffInDays = Math.floor(diffInMs / (1000 * 60 * 60 * 24));\n\n        if (diffInMinutes < 1) return '방금 전';\n        if (diffInMinutes < 60) return `${diffInMinutes}분 전`;\n        if (diffInHours < 24) return `${diffInHours}시간 전`;\n        return `${diffInDays}일 전`;\n    };\n\n    const PostItem = ({ post }: { post: BoardPost }) => (\n        <View style={styles.postContainer}>\n            <View style={styles.authorSection}>\n                <View style={styles.authorAvatar}>\n                    {post.profileImage ? (\n                        <Image source={{ uri: toImageUrl(post.profileImage) }} style={styles.avatarImage} />\n                    ) : (\n                        <View style={styles.defaultAvatar}>\n                            <Ionicons name=\"person-circle-outline\" size={40} color=\"#7C8070\" />\n                        </View>\n                    )}\n                </View>\n                <Text style={styles.authorName}>{post.author}</Text>\n            </View>\n            <View style={styles.postContent}>\n                <Text style={styles.postTitle}>{post.title}</Text>\n                <Text style={styles.postContentText} numberOfLines={2}>\n                    {post.content}\n                </Text>\n                <View style={styles.postMeta}>\n                    <View style={styles.postCategoryTag}>\n                        <Text style={styles.postCategoryText}>{post.category}</Text>\n                    </View>\n                    <Text style={styles.timeAgo}>{formatTimeAgo(post.createdAt)}</Text>\n                </View>\n            </View>\n            <View style={styles.actionSection}>\n                <TouchableOpacity\n                    style={styles.actionButton}\n                    onPress={() => handleEditPost(post)}\n                >\n                    <Ionicons name=\"create-outline\" size={20} color=\"#4E7D32\" />\n                </TouchableOpacity>\n                <TouchableOpacity\n                    style={[styles.actionButton, styles.deleteButton]}\n                    onPress={() => handleDeletePost(post.id, post.title)}\n                >\n                    <Ionicons name=\"trash-outline\" size={20} color=\"#ff4444\" />\n                </TouchableOpacity>\n            </View>\n        </View>\n    );\n\n    const OnlineClassItem = ({ classItem }: { classItem: ClassData }) => (\n        <TouchableOpacity\n            style={styles.onlineClassItemContainer}\n            onPress={() => handleOnlineClassPress(classItem)}\n            activeOpacity={0.7}\n        >\n            <View style={styles.classImageContainer}>\n                {classItem.certificationImage ? (\n                    <Image source={{ uri: classItem.certificationImage }} style={styles.classImage} />\n                ) : (\n                    <View style={styles.defaultClassImage}>\n                        <Ionicons name=\"videocam-outline\" size={40} color=\"#A3A794\" />\n                    </View>\n                )}\n            </View>\n            <View style={styles.classContent}>\n                <Text style={styles.classTitle}>{classItem.title}</Text>\n                <Text style={styles.classInstructor}>{classItem.instructor}</Text>\n                <Text style={styles.classDescription} numberOfLines={2}>{classItem.description}</Text>\n            </View>\n        </TouchableOpacity>\n    );\n\n    const EmptyState = () => {\n        const emptyStateText = getEmptyStateText();\n        return (\n            <View style={styles.emptyContainer}>\n                <Ionicons\n                    name={activeTab === 'board' ? \"document-outline\" : \"videocam-outline\"}\n                    size={80}\n                    color=\"#C9CCB8\"\n                />\n                <Text style={styles.emptyTitle}>{emptyStateText.title}</Text>\n                <Text style={styles.emptyDescription}>\n                    {emptyStateText.description}\n                </Text>\n                <TouchableOpacity\n                    style={styles.createPostButton}\n                    onPress={handleCreatePress}\n                >\n                    <Text style={styles.createPostButtonText}>{getCreateButtonText()}</Text>\n                </TouchableOpacity>\n            </View>\n        );\n    };\n\n    const renderTabContent = () => {\n        if (activeTab === 'onlineClass') {\n            // 온라인 수업 탭일 때 OnlineClassMyDetail 컴포넌트를 직접 렌더링\n            return (\n                <View style={styles.onlineClassDetailContainer}>\n                    <OnlineClassMyDetail embedded />\n                </View>\n            );\n        }\n\n        // 게시판 탭\n        if (myPosts.length === 0) {\n            return <EmptyState />;\n        }\n\n        return (\n            <ScrollView style={styles.postsScrollView} showsVerticalScrollIndicator={false}>\n                {filteredPosts.length === 0 ? (\n                    <View style={styles.noResultsContainer}>\n                        <Text style={styles.noResultsText}>검색 결과가 없습니다</Text>\n                    </View>\n                ) : (\n                    filteredPosts.map((post) => (\n                        <PostItem key={post.id} post={post} />\n                    ))\n                )}\n            </ScrollView>\n        );\n    };\n\n    return (\n        <View style={styles.container}>\n            {/* 공통 헤더 */}\n            <AppHeader title={getHeaderTitle()} />\n\n            <View style={styles.tabContainerWrapper}>\n                <View style={styles.tabContainer}>\n                    <TabButton\n                        title=\"게시판\"\n                        isActive={activeTab === 'board'}\n                        onPress={() => setActiveTab('board')}\n                    />\n                    <TabButton\n                        title=\"온라인 수업\"\n                        isActive={activeTab === 'onlineClass'}\n                        onPress={() => setActiveTab('onlineClass')}\n                    />\n                </View>\n            </View>\n\n            {activeTab === 'board' && myPosts.length > 0 && (\n                <>\n                    <View style={styles.statsContainer}>\n                        <View style={styles.statsItem}>\n                            <Text style={styles.statsNumber}>{myPosts.length}</Text>\n                            <Text style={styles.statsLabel}>총 게시글</Text>\n                        </View>\n                        <View style={styles.statsDivider} />\n                        <View style={styles.statsItem}>\n                            <Text style={styles.statsNumber}>\n                                {myPosts.filter(post => post.category === '교육').length}\n                            </Text>\n                            <Text style={styles.statsLabel}>교육</Text>\n                        </View>\n                        <View style={styles.statsDivider} />\n                        <View style={styles.statsItem}>\n                            <Text style={styles.statsNumber}>\n                                {myPosts.filter(post => post.category === '운동').length}\n                            </Text>\n                            <Text style={styles.statsLabel}>운동</Text>\n                        </View>\n                        <View style={styles.statsDivider} />\n                        <View style={styles.statsItem}>\n                            <Text style={styles.statsNumber}>\n                                {myPosts.filter(post => post.category === '활동').length}\n                            </Text>\n                            <Text style={styles.statsLabel}>활동</Text>\n                        </View>\n                    </View>\n\n                    <View style={styles.categoryFilterContainer}>\n                        {categories.map((category) => (\n                            <TouchableOpacity\n                                key={category}\n                                style={[\n                                    styles.categoryFilterButton,\n                                    selectedCategory === category && styles.selectedCategoryFilterButton,\n                                ]}\n                                onPress={() => setSelectedCategory(category)}\n                            >\n                                <Text\n                                    style={[\n                                        styles.categoryFilterButtonText,\n                                        selectedCategory === category && styles.selectedCategoryFilterButtonText,\n                                    ]}\n                                >\n                                    {category}\n                                </Text>\n                            </TouchableOpacity>\n                        ))}\n                    </View>\n                </>\n            )}\n\n            <View style={styles.contentContainer}>\n                {renderTabContent()}\n            </View>\n        </View>\n    );\n};\n\nconst styles = StyleSheet.create({\n    container: { flex: 1, backgroundColor: '#FBFAF4' },\n    header: {\n        flexDirection: 'row',\n        justifyContent: 'space-between',\n        alignItems: 'center',\n        paddingHorizontal: 20,\n        paddingTop: 15,\n        paddingBottom: 10,\n        borderBottomWidth: 1,\n        borderBottomColor: '#EEF0E4'\n    },\n    title: { fontSize: 20, fontWeight: 'bold', color: '#2E3326', flex: 1, textAlign: 'center', marginHorizontal: 20 },\n    headerRight: { flexDirection: 'row', alignItems: 'center', gap: 10 },\n    headerSearchInput: {\n        height: 36,\n        width: 80,\n        borderWidth: 1,\n        borderColor: '#DADDCB',\n        borderRadius: 8,\n        paddingHorizontal: 8,\n        fontSize: 14,\n        backgroundColor: '#FBFAF4'\n    },\n    addButton: {\n        width: 36,\n        height: 36,\n        borderRadius: 8,\n        borderWidth: 1,\n        borderColor: '#DADDCB',\n        justifyContent: 'center',\n        alignItems: 'center',\n        backgroundColor: '#FBFAF4'\n    },\n    addButtonText: { fontSize: 20, color: '#7C8070' },\n    tabContainerWrapper: {\n        backgroundColor: '#FBFAF4',\n        borderBottomWidth: 1,\n        borderBottomColor: '#E6E8DA',\n    },\n    tabContainer: {\n        flexDirection: 'row',\n    },\n    tabButton: {\n        flex: 1,\n        paddingVertical: 15,\n        paddingHorizontal: 20,\n        alignItems: 'center',\n        justifyContent: 'center',\n        borderBottomWidth: 2,\n        borderBottomColor: 'transparent',\n    },\n    activeTabButton: {\n        backgroundColor: '#ffffff',\n        borderBottomColor: '#4E7D32',\n    },\n    tabButtonText: {\n        fontSize: 16,\n        color: '#7C8070',\n        fontWeight: '500',\n    },\n    activeTabButtonText: {\n        color: '#4E7D32',\n        fontWeight: '600',\n    },\n    contentContainer: {\n        flex: 1,\n    },\n    onlineClassDetailContainer: {\n        flex: 1,\n        backgroundColor: '#fff',\n    },\n    statsContainer: {\n        flexDirection: 'row',\n        backgroundColor: '#FBFAF4',\n        paddingVertical: 20,\n        paddingHorizontal: 20,\n        justifyContent: 'space-around',\n        alignItems: 'center',\n        marginHorizontal: 20,\n        marginTop: 15,\n        borderRadius: 12,\n        borderWidth: 1,\n        borderColor: '#EEF0E4',\n    },\n    statsItem: { alignItems: 'center' },\n    statsNumber: { fontSize: 24, fontWeight: 'bold', color: '#2E3326' },\n    statsLabel: { fontSize: 12, color: '#7C8070', marginTop: 4 },\n    statsDivider: { width: 1, height: 30, backgroundColor: '#DADDCB' },\n    categoryFilterContainer: {\n        flexDirection: 'row',\n        paddingHorizontal: 20,\n        paddingVertical: 15,\n        gap: 8,\n        borderBottomWidth: 1,\n        borderBottomColor: '#EEF0E4'\n    },\n    categoryFilterButton: {\n        paddingHorizontal: 15,\n        paddingVertical: 8,\n        borderRadius: 8,\n        borderWidth: 1,\n        borderColor: '#DADDCB',\n        backgroundColor: '#fff'\n    },\n    selectedCategoryFilterButton: { backgroundColor: '#4E7D32', borderColor: '#4E7D32' },\n    categoryFilterButtonText: { fontSize: 14, color: '#7C8070', fontWeight: '500' },\n    selectedCategoryFilterButtonText: { color: '#fff' },\n    postsScrollView: { flex: 1, paddingHorizontal: 20, paddingTop: 10 },\n    postContainer: {\n        flexDirection: 'row',\n        backgroundColor: '#fff',\n        borderRadius: 12,\n        paddingVertical: 16,\n        paddingHorizontal: 16,\n        marginBottom: 12,\n        borderWidth: 1,\n        borderColor: '#EEF0E4',\n        alignItems: 'flex-start',\n        shadowColor: '#000',\n        shadowOffset: { width: 0, height: 1 },\n        shadowOpacity: 0.05,\n        shadowRadius: 2,\n        elevation: 1,\n    },\n    authorSection: { width: 60, alignItems: 'center', paddingRight: 12 },\n    authorAvatar: {\n        width: 40,\n        height: 40,\n        borderRadius: 20,\n        justifyContent: 'center',\n        alignItems: 'center',\n        borderWidth: 1,\n        borderColor: '#DADDCB',\n        marginBottom: 6,\n        overflow: 'hidden'\n    },\n    avatarImage: { width: '100%', height: '100%', borderRadius: 20 },\n    defaultAvatar: {\n        width: 40,\n        height: 40,\n        borderRadius: 20,\n        justifyContent: 'center',\n        alignItems: 'center',\n        backgroundColor: '#EEF0E4'\n    },\n    authorName: { fontSize: 11, color: '#7C8070', textAlign: 'center' },\n    postContent: { flex: 1, justifyContent: 'flex-start', paddingRight: 12 },\n    postTitle: {\n        fontSize: 16,\n        color: '#2E3326',\n        lineHeight: 22,\n        fontWeight: '600',\n        marginBottom: 8\n    },\n    postContentText: {\n        fontSize: 14,\n        color: '#7C8070',\n        lineHeight: 20,\n        marginBottom: 12,\n    },\n    postMeta: { flexDirection: 'row', alignItems: 'center', gap: 8 },\n    postCategoryTag: {\n        paddingHorizontal: 10,\n        paddingVertical: 4,\n        backgroundColor: '#EEF0E4',\n        borderRadius: 10,\n        borderWidth: 1,\n        borderColor: '#DADDCB'\n    },\n    postCategoryText: { fontSize: 11, color: '#7C8070', fontWeight: '500' },\n    timeAgo: { fontSize: 12, color: '#A3A794' },\n    actionSection: { alignItems: 'center', justifyContent: 'flex-start', paddingTop: 4, gap: 8 },\n    actionButton: {\n        width: 36,\n        height: 36,\n        borderRadius: 18,\n        backgroundColor: '#fff',\n        borderWidth: 1,\n        borderColor: '#4E7D32',\n        justifyContent: 'center',\n        alignItems: 'center'\n    },\n    deleteButton: {\n        borderColor: '#ff4444',\n    },\n    emptyContainer: {\n        flex: 1,\n        justifyContent: 'center',\n        alignItems: 'center',\n        paddingHorizontal: 40,\n    },\n    emptyTitle: {\n        fontSize: 20,\n        fontWeight: 'bold',\n        color: '#2E3326',\n        marginTop: 20,\n        marginBottom: 8,\n    },\n    emptyDescription: {\n        fontSize: 16,\n        color: '#7C8070',\n        textAlign: 'center',\n        lineHeight: 24,\n        marginBottom: 30,\n    },\n    createPostButton: {\n        paddingHorizontal: 24,\n        paddingVertical: 12,\n        backgroundColor: '#4E7D32',\n        borderRadius: 8,\n    },\n    createPostButtonText: {\n        color: '#fff',\n        fontSize: 16,\n        fontWeight: 'bold',\n    },\n    noResultsContainer: {\n        flex: 1,\n        justifyContent: 'center',\n        alignItems: 'center',\n        paddingVertical: 60,\n    },\n    noResultsText: {\n        fontSize: 16,\n        color: '#7C8070',\n    },\n    onlineClassItemContainer: {\n        flexDirection: 'row',\n        backgroundColor: '#fff',\n        borderRadius: 12,\n        padding: 16,\n        marginBottom: 12,\n        borderWidth: 1,\n        borderColor: '#EEF0E4',\n        alignItems: 'center',\n        shadowColor: '#000',\n        shadowOffset: { width: 0, height: 1 },\n        shadowOpacity: 0.05,\n        shadowRadius: 2,\n        elevation: 1,\n    },\n    classImageContainer: {\n        width: 80,\n        height: 60,\n        borderRadius: 8,\n        overflow: 'hidden',\n        marginRight: 16,\n        backgroundColor: '#EEF0E4',\n        justifyContent: 'center',\n        alignItems: 'center',\n    },\n    classImage: {\n        width: '100%',\n        height: '100%',\n        resizeMode: 'cover',\n    },\n    defaultClassImage: {\n        width: '100%',\n        height: '100%',\n        justifyContent: 'center',\n        alignItems: 'center',\n    },\n    classContent: {\n        flex: 1,\n    },\n    classTitle: {\n        fontSize: 16,\n        fontWeight: '600',\n        color: '#2E3326',\n        marginBottom: 4,\n    },\n    classInstructor: {\n        fontSize: 14,\n        color: '#4E7D32',\n        marginBottom: 4,\n    },\n    classDescription: {\n        fontSize: 12,\n        color: '#7C8070',\n        lineHeight: 18,\n    },\n});\n\nexport default MyBoard;",
    "components/OnlineClass/MakeOnlineClass.tsx": "import React, { useState } from 'react';\nimport {\n    View,\n    Text,\n    StyleSheet,\n    SafeAreaView,\n    TouchableOpacity,\n    TextInput,\n    ScrollView,\n    Alert,\n    Platform,\n    Image,\n} from 'react-native';\nimport { Ionicons } from '@expo/vector-icons';\nimport { router, useLocalSearchParams } from 'expo-router';\nimport { useAuth } from '@/components/contexts/AuthProvider';\nimport * as ImagePicker from 'expo-image-picker';\nimport { useOnlineClass } from '@/components/contexts/OnlineClassContext';\nimport AppHeader from '@/components/AppHeader';\nimport { toImageUrl } from '@/config';\n\nconst MakeOnlineClass = () => {\n    const { currentUser } = useAuth();\n    const { setClassData } = useOnlineClass();\n    const params = useLocalSearchParams();\n\n    // State initialization, pulling defaults from params for potential editing, or falling back to empty string\n    const [title, setTitle] = useState((params.title as string) || '');\n    const [description, setDescription] = useState((params.description as string) || '');\n    const [introduction, setIntroduction] = useState((params.introduction as string) || '');\n\n    const [isLoading, setIsLoading] = useState(false);\n    const [certificationImage, setCertificationImage] = useState<string | null>(null);\n\n    // Extract instructor info from params, falling back to currentUser\n    const instructorName = (params.instructorName as string) || currentUser?.name || '익명';\n    const instructorProfileImage = toImageUrl((params.instructorProfileImage as string) || currentUser?.profileImage);\n\n    const requestPermission = async () => {\n        if (Platform.OS !== 'web') {\n            const { status } = await ImagePicker.requestMediaLibraryPermissionsAsync();\n            if (status !== 'granted') {\n                Alert.alert('권한 필요', '자격증 이미지를 등록하려면 앨범 접근 권한이 필요합니다.');\n                return false;\n            }\n        }\n        return true;\n    };\n\n    const handleImagePick = async () => {\n        const hasPermission = await requestPermission();\n        if (!hasPermission) return;\n\n        let result = await ImagePicker.launchImageLibraryAsync({\n            mediaTypes: ImagePicker.MediaTypeOptions.Images,\n            allowsEditing: true,\n            aspect: [4, 3],\n            quality: 1,\n        });\n\n        if (!result.canceled) {\n            setCertificationImage(result.assets[0].uri);\n        }\n    };\n\n    const handleRegisterAndNavigate = async () => {\n        if (!title.trim()) {\n            Alert.alert('오류', '클래스 제목을 입력해주세요.');\n            return;\n        }\n        if (!description.trim()) {\n            Alert.alert('오류', '수업 설명을 입력해주세요.');\n            return;\n        }\n        if (!introduction.trim()) {\n            Alert.alert('오류', '자기소개를 입력해주세요.');\n            return;\n        }\n\n        setIsLoading(true);\n        try {\n            // **[수정] ID 처리 로직:** 수정 모드라면 기존 params.id를 사용하고,\n            // 새 등록이라면 Date.now().toString()으로 새 ID를 생성합니다.\n            const classId = params.id ? (params.id as string) : Date.now().toString();\n\n            const classData = {\n                id: classId,\n                title: title.trim(),\n                instructor: instructorName,\n                description: description.trim(),\n                introduction: introduction.trim(),\n                createdBy: currentUser?.name,\n                profileImage: instructorProfileImage,\n                phoneNumber: currentUser?.phoneNumber,\n                certificationImage: certificationImage,\n                price: 0,\n            };\n\n            // 1. Save the class data to context\n            // setClassData는 아마도 Context의 currentClassData를 설정하는 역할일 것입니다.\n            setClassData(classData);\n\n            // 2. Navigate to the main online class screen within the 'board' tab.\n            router.replace({\n                pathname: '/board',\n                params: { activeTab: 'onlineClass' }\n            });\n\n        } catch (error) {\n            console.error('클래스 등록 오류:', error);\n            Alert.alert('오류', '클래스 등록 중 문제가 발생했습니다.');\n        } finally {\n            setIsLoading(false);\n        }\n    };\n\n    const handleCancel = () => {\n        router.back();\n    };\n\n    const formatPhoneNumber = (phone: string | undefined) => {\n        if (!phone) return '';\n        const cleaned = phone.replace(/[^0-9]/g, '');\n        if (cleaned.length === 11) {\n            return cleaned.replace(/(\\d{3})(\\d{4})(\\d{4})/, '$1-$2-$3');\n        }\n        return phone;\n    };\n\n    return (\n        <View style={styles.container}>\n            {/* 공통 헤더: < 클래스 등록 [등록] 🔔 */}\n            <AppHeader\n                title=\"클래스 등록\"\n                onBack={() => { if (!isLoading) handleCancel(); }}\n                right={[{ label: isLoading ? '등록중' : '등록', onPress: handleRegisterAndNavigate, disabled: isLoading, color: '#4E7D32' }]}\n            />\n\n            <ScrollView style={styles.scrollContainer} showsVerticalScrollIndicator={false}>\n                <View style={styles.content}>\n                    <View style={styles.profileContainer}>\n                        <View style={styles.profileImageContainer}>\n                            {instructorProfileImage ? (\n                                <Image\n                                    source={{ uri: instructorProfileImage }}\n                                    style={styles.profileImage}\n                                />\n                            ) : (\n                                <View style={styles.defaultProfileImage}>\n                                    <Ionicons name=\"person\" size={30} color=\"#A3A794\" />\n                                </View>\n                            )}\n                        </View>\n                        <View style={styles.profileInfo}>\n                            <Text style={styles.profileNickname}>\n                                {instructorName}\n                            </Text>\n                            <Text style={styles.profilePhone}>\n                                {formatPhoneNumber(currentUser?.phoneNumber) || '전화번호 없음'}\n                            </Text>\n                        </View>\n                    </View>\n\n                    <View style={styles.inputGroup}>\n                        <Text style={styles.label}>클래스 제목 *</Text>\n                        <TextInput\n                            style={styles.textInput}\n                            value={title}\n                            onChangeText={setTitle}\n                            placeholder=\"클래스 제목을 입력해주세요\"\n                            placeholderTextColor=\"#A3A794\"\n                            maxLength={50}\n                        />\n                        <Text style={styles.charCount}>{title.length}/50</Text>\n                    </View>\n\n                    <View style={styles.inputGroup}>\n                        <Text style={styles.label}>강사</Text>\n                        <View style={styles.instructorContainer}>\n                            <Text style={styles.instructorName}>\n                                {instructorName}\n                            </Text>\n                        </View>\n                    </View>\n\n                    <View style={styles.inputGroup}>\n                        <Text style={styles.label}>수업 설명 *</Text>\n                        <TextInput\n                            style={[styles.textInput, styles.textArea]}\n                            value={description}\n                            onChangeText={setDescription}\n                            placeholder=\"수업 내용과 목표를 자세히 설명해주세요\"\n                            placeholderTextColor=\"#A3A794\"\n                            multiline\n                            numberOfLines={6}\n                            textAlignVertical=\"top\"\n                            maxLength={500}\n                        />\n                        <Text style={styles.charCount}>{description.length}/500</Text>\n                    </View>\n\n                    <View style={styles.inputGroup}>\n                        <Text style={styles.label}>강사 자기소개 *</Text>\n                        <TextInput\n                            style={[styles.textInput, styles.textArea]}\n                            value={introduction}\n                            onChangeText={setIntroduction}\n                            placeholder=\"자신의 경력, 전문 분야, 교육 철학 등을 소개해주세요\"\n                            placeholderTextColor=\"#A3A794\"\n                            multiline\n                            numberOfLines={4}\n                            textAlignVertical=\"top\"\n                            maxLength={300}\n                        />\n                        <Text style={styles.charCount}>{introduction.length}/300</Text>\n                    </View>\n\n                    <View style={styles.inputGroup}>\n                        <Text style={styles.label}>자격증 이미지 (선택)</Text>\n                        <TouchableOpacity style={styles.imagePicker} onPress={handleImagePick}>\n                            {certificationImage ? (\n                                <Image source={{ uri: certificationImage }} style={styles.uploadedImage} />\n                            ) : (\n                                <View style={styles.imagePlaceholder}>\n                                    <Ionicons name=\"camera-outline\" size={30} color=\"#A3A794\" />\n                                    <Text style={styles.imagePlaceholderText}>이미지 업로드</Text>\n                                </View>\n                            )}\n                        </TouchableOpacity>\n                    </View>\n\n                    <View style={styles.noteContainer}>\n                        <Ionicons name=\"information-circle-outline\" size={20} color=\"#7C8070\" />\n                        <Text style={styles.noteText}>\n                            자격증 이미지는 클래스 승인 심사에 참고되며, 필수 사항은 아닙니다.\n                        </Text>\n                    </View>\n                </View>\n            </ScrollView>\n        </View>\n    );\n};\n\nconst styles = StyleSheet.create({\n    container: {\n        flex: 1,\n        backgroundColor: '#fff',\n    },\n    header: {\n        flexDirection: 'row',\n        justifyContent: 'space-between',\n        alignItems: 'center',\n        paddingHorizontal: 20,\n        paddingVertical: 15,\n        backgroundColor: '#fff',\n        borderBottomWidth: 1,\n        borderBottomColor: '#EEF0E4',\n    },\n    headerTitle: {\n        fontSize: 18,\n        fontWeight: 'bold',\n        color: '#2E3326',\n    },\n    headerButtons: {\n        flexDirection: 'row',\n        gap: 8,\n    },\n    registerButton: {\n        paddingHorizontal: 12,\n        paddingVertical: 6,\n        backgroundColor: '#4E7D32',\n        borderRadius: 6,\n    },\n    registerButtonText: {\n        fontSize: 14,\n        fontWeight: 'bold',\n        color: '#fff',\n    },\n    scrollContainer: {\n        flex: 1,\n    },\n    content: {\n        padding: 20,\n    },\n    profileContainer: {\n        flexDirection: 'row',\n        alignItems: 'center',\n        backgroundColor: '#FBFAF4',\n        padding: 16,\n        borderRadius: 12,\n        marginBottom: 24,\n        borderWidth: 1,\n        borderColor: '#E6E8DA',\n    },\n    profileImageContainer: {\n        marginRight: 16,\n    },\n    profileImage: {\n        width: 60,\n        height: 60,\n        borderRadius: 30,\n        backgroundColor: '#EEF0E4',\n    },\n    defaultProfileImage: {\n        width: 60,\n        height: 60,\n        borderRadius: 30,\n        backgroundColor: '#EEF0E4',\n        justifyContent: 'center',\n        alignItems: 'center',\n        borderWidth: 1,\n        borderColor: '#E6E8DA',\n    },\n    profileInfo: {\n        flex: 1,\n    },\n    profileNickname: {\n        fontSize: 18,\n        fontWeight: 'bold',\n        color: '#2E3326',\n        marginBottom: 4,\n    },\n    profilePhone: {\n        fontSize: 14,\n        color: '#7C8070',\n    },\n    inputGroup: {\n        marginBottom: 24,\n    },\n    label: {\n        fontSize: 16,\n        fontWeight: '600',\n        color: '#2E3326',\n        marginBottom: 8,\n    },\n    textInput: {\n        borderWidth: 1,\n        borderColor: '#E6E8DA',\n        borderRadius: 8,\n        paddingHorizontal: 16,\n        paddingVertical: 12,\n        fontSize: 16,\n        backgroundColor: '#fff',\n        color: '#2E3326',\n    },\n    textArea: {\n        height: 120,\n        paddingTop: 12,\n    },\n    charCount: {\n        fontSize: 12,\n        color: '#A3A794',\n        textAlign: 'right',\n        marginTop: 4,\n    },\n    instructorContainer: {\n        borderWidth: 1,\n        borderColor: '#E6E8DA',\n        borderRadius: 8,\n        paddingHorizontal: 16,\n        paddingVertical: 12,\n        backgroundColor: '#FBFAF4',\n    },\n    instructorName: {\n        fontSize: 16,\n        color: '#2E3326',\n        fontWeight: '500',\n    },\n    imagePicker: {\n        width: '100%',\n        height: 200,\n        backgroundColor: '#FBFAF4',\n        borderRadius: 8,\n        borderWidth: 1,\n        borderColor: '#E6E8DA',\n        justifyContent: 'center',\n        alignItems: 'center',\n        overflow: 'hidden',\n    },\n    imagePlaceholder: {\n        justifyContent: 'center',\n        alignItems: 'center',\n    },\n    imagePlaceholderText: {\n        marginTop: 8,\n        fontSize: 14,\n        color: '#A3A794',\n    },\n    uploadedImage: {\n        width: '100%',\n        height: '100%',\n        resizeMode: 'cover',\n    },\n    noteContainer: {\n        flexDirection: 'row',\n        alignItems: 'center',\n        backgroundColor: '#FBFAF4',\n        padding: 16,\n        borderRadius: 8,\n        marginTop: 20,\n        gap: 8,\n    },\n    noteText: {\n        flex: 1,\n        fontSize: 14,\n        color: '#7C8070',\n        lineHeight: 20,\n    },\n});\n\nexport default MakeOnlineClass;",
    "components/OnlineClass/OnlineClass.tsx": "import React from 'react';\nimport {\n    View,\n    Text,\n    StyleSheet,\n    ScrollView,\n    TouchableOpacity,\n    Image,\n} from 'react-native';\nimport { Ionicons } from '@expo/vector-icons';\nimport { router } from 'expo-router';\nimport { useAuth } from '@/components/contexts/AuthProvider';\n// ❤️ [수정] likedClassIds, toggleLike 가져오기\nimport { useOnlineClass } from '@/components/contexts/OnlineClassContext';\n\n// ClassItem 인터페이스는 Context의 ClassData와 정적 데이터를 통합하기 위해 사용됩니다.\ninterface ClassItem {\n    id: string | number;\n    title: string;\n    instructor: string;\n    duration: string;\n    level: string;\n    thumbnail: string;\n    participants: number;\n    profileImage?: string;\n    rating: number;\n    reviewCount: number;\n    description?: string;\n    introduction?: string;\n}\n\nconst OnlineClass: React.FC = () => {\n    const { currentUser } = useAuth();\n    // ❤️ [수정] Context에서 좋아요 상태 및 토글 함수 가져오기\n    const { classes, videos, paymentInfo, likedClassIds, toggleLike } = useOnlineClass();\n\n    // 임시 하드코딩된 클래스 목록 (Context에 데이터가 없을 때 표시되거나, 기본 목록으로 사용)\n    const staticClassItems: ClassItem[] = [\n        // ID는 Context와 충돌하지 않도록 문자열로 유지합니다.\n        {\n            id: 'static-1',\n            title: 'React Native 기초부터 실전까지',\n            instructor: '김개발',\n            duration: '2시간 30분',\n            level: '초급',\n            thumbnail: 'https://via.placeholder.com/300x200?text=React+Native',\n            participants: 45,\n            profileImage: 'https://randomuser.me/api/portraits/men/32.jpg',\n            rating: 4.8,\n            reviewCount: 124,\n        },\n        {\n            id: 'static-2',\n            title: 'JavaScript ES6+ 완전정복',\n            instructor: '이코딩',\n            duration: '3시간 15분',\n            level: '중급',\n            thumbnail: 'https://via.placeholder.com/300x200?text=JavaScript',\n            participants: 128,\n            profileImage: 'https://randomuser.me/api/portraits/women/44.jpg',\n            rating: 4.9,\n            reviewCount: 89,\n        },\n        {\n            id: 'static-3',\n            title: 'UI/UX 디자인 실무',\n            instructor: '박디자인',\n            duration: '1시간 45분',\n            level: '초급',\n            thumbnail: 'https://via.placeholder.com/300x200?text=UI%2FUX',\n            participants: 32,\n            profileImage: 'https://randomuser.me/api/portraits/men/67.jpg',\n            rating: 4.6,\n            reviewCount: 56,\n        },\n    ];\n\n    // Context 클래스 데이터를 ClassItem 형식으로 매핑\n    const contextClassItems: ClassItem[] = classes.map((classData) => ({\n        // Context의 ID는 string | number 타입으로 일치시켜야 합니다.\n        id: classData.id || `temp-${Date.now().toString()}`,\n        title: classData.title,\n        instructor: classData.instructor,\n        duration: '미정',\n        level: '초급',\n        thumbnail: classData.profileImage || 'https://via.placeholder.com/300x200?text=Online+Class',\n        participants: 0,\n        profileImage: classData.profileImage,\n        rating: 0,\n        reviewCount: 0,\n        description: classData.description,\n        introduction: classData.introduction,\n    }));\n\n    // ID 기반 중복 제거를 위한 Map 사용 (동적 클래스가 정적 클래스보다 우선함)\n    const uniqueClassItemsMap = new Map<string | number, ClassItem>();\n\n    // 1. Context 클래스를 Map에 추가\n    contextClassItems.forEach(item => {\n        uniqueClassItemsMap.set(item.id, item);\n    });\n\n    // 2. 정적 클래스를 Map에 추가 (Context에 없는 ID만 추가)\n    staticClassItems.forEach(item => {\n        if (!uniqueClassItemsMap.has(item.id)) {\n            uniqueClassItemsMap.set(item.id, item);\n        }\n    });\n\n    // 최종적으로 렌더링할 중복 제거된 클래스 목록\n    const classItems: ClassItem[] = Array.from(uniqueClassItemsMap.values());\n\n    const handleRegister = () => {\n        router.push('/MakeOnlineClass');\n    };\n\n    const handleSendMessage = (instructorName: string) => {\n        console.log(`${instructorName} 강사에게 메시지 보내기`);\n        // 실제 앱에서는 메시지 화면으로 이동하는 로직 추가\n    };\n\n    // ❤️ [수정] Context의 toggleLike 함수를 호출하도록 변경\n    const handleLikeClass = (classId: string | number) => {\n        toggleLike(classId);\n    };\n\n    const handleJoinClass = (item: ClassItem) => {\n        // 상세 페이지로 이동하며 필요한 데이터를 params로 전달합니다.\n        router.push({\n            pathname: '/OnlineClassPersonDetail',\n            params: {\n                id: item.id.toString(),\n                title: item.title,\n                instructor: item.instructor,\n                profileImage: item.profileImage || '',\n                rating: item.rating.toString(),\n                reviewCount: item.reviewCount.toString(),\n                description: item.description || '',\n                introduction: item.introduction || '',\n                videos: JSON.stringify(videos),\n                paymentInfo: JSON.stringify(paymentInfo),\n            },\n        });\n    };\n\n    /**\n     * 별점을 렌더링하는 함수.\n     */\n    const renderStars = (rating: number, classId: string | number) => {\n        const stars = [];\n        const fullStars = Math.floor(rating);\n        const hasHalfStar = rating % 1 !== 0;\n\n        for (let i = 0; i < fullStars; i++) {\n            stars.push(<Ionicons key={`star-full-${classId}-${i}`} name=\"star\" size={12} color=\"#ffc107\" />);\n        }\n\n        if (hasHalfStar) {\n            stars.push(<Ionicons key={`star-half-${classId}`} name=\"star-half\" size={12} color=\"#ffc107\" />);\n        }\n\n        const remainingStars = 5 - Math.ceil(rating);\n        for (let i = 0; i < remainingStars; i++) {\n            stars.push(<Ionicons key={`star-empty-${classId}-${i}`} name=\"star-outline\" size={12} color=\"#ffc107\" />);\n        }\n\n        return stars;\n    };\n\n    const renderClassItem = (item: ClassItem) => {\n        // ❤️ [추가] 현재 클래스의 좋아요 상태 확인\n        const isLiked = likedClassIds.includes(item.id);\n\n        return (\n            <TouchableOpacity\n                key={item.id} // 고유한 key 사용\n                style={styles.classItem}\n                activeOpacity={0.7}\n                onPress={() => handleJoinClass(item)}\n            >\n                <View style={styles.profileContainer}>\n                    {item.profileImage ? (\n                        <Image source={{ uri: item.profileImage }} style={styles.profileImage} />\n                    ) : (\n                        <View style={styles.defaultProfileImage}>\n                            <Text style={styles.profileInitial}>{item.instructor.charAt(0)}</Text>\n                        </View>\n                    )}\n                </View>\n\n                <View style={styles.classInfo}>\n                    <Text style={styles.classTitle} numberOfLines={2}>\n                        {item.title}\n                    </Text>\n                    <Text style={styles.instructor}>강사: {item.instructor}</Text>\n\n                    <View style={styles.reviewContainer}>\n                        <View style={styles.starsContainer}>{renderStars(item.rating, item.id)}</View>\n                        <Text style={styles.ratingText}>{item.rating}</Text>\n                        <Text style={styles.reviewCount}>({item.reviewCount}개 리뷰)</Text>\n                    </View>\n\n                    <View style={styles.buttonRow}>\n                        <TouchableOpacity style={styles.joinButton} onPress={() => handleJoinClass(item)}>\n                            <Text style={styles.joinButtonText}>수강하기</Text>\n                        </TouchableOpacity>\n\n                        {/* 메시지 버튼 */}\n                        <TouchableOpacity\n                            style={styles.messageButton}\n                            onPress={() => handleSendMessage(item.instructor)}\n                        >\n                            <Ionicons name=\"chatbubble-ellipses-outline\" size={20} color=\"#4E7D32\" />\n                        </TouchableOpacity>\n\n                        {/* ❤️ [수정] 좋아요 하트 아이콘 (상태에 따라 아이콘 변경) */}\n                        <TouchableOpacity\n                            style={styles.likeButton}\n                            onPress={() => handleLikeClass(item.id)} // item.id 전달\n                        >\n                            <Ionicons\n                                name={isLiked ? \"heart\" : \"heart-outline\"} // 상태에 따른 아이콘\n                                size={20}\n                                color={isLiked ? \"#dc3545\" : \"#dc3545\"} // 좋아요 시 채워진 하트 색상\n                            />\n                        </TouchableOpacity>\n                    </View>\n                </View>\n            </TouchableOpacity>\n        );\n    };\n\n    return (\n        <View style={styles.container}>\n            <ScrollView style={styles.scrollContainer} contentContainerStyle={{ paddingBottom: 170 }} showsVerticalScrollIndicator={false}>\n                {classItems.length > 0 ? (\n                    // 중복 제거된 목록 렌더링\n                    classItems.map(renderClassItem)\n                ) : (\n                    <View style={styles.emptyContainer}>\n                        <Ionicons name=\"sad-outline\" size={50} color=\"#A3A794\" />\n                        <Text style={styles.emptyText}>등록된 온라인 클래스가 없습니다.</Text>\n                    </View>\n                )}\n            </ScrollView>\n\n            {/* Float 버튼: 사용자가 강사라면 클래스 등록을 쉽게 할 수 있도록 제공 */}\n            {currentUser && (\n                <TouchableOpacity style={styles.registerClassButton} onPress={handleRegister}>\n                    <Ionicons name=\"add-circle\" size={24} color=\"#fff\" />\n                    <Text style={styles.registerClassButtonText}>클래스 등록</Text>\n                </TouchableOpacity>\n            )}\n        </View>\n    );\n};\n\nconst styles = StyleSheet.create({\n    container: {\n        flex: 1,\n        backgroundColor: '#FBFAF4',\n    },\n    scrollContainer: {\n        flex: 1,\n    },\n    classItem: {\n        flexDirection: 'row',\n        padding: 20,\n        borderBottomWidth: 1,\n        borderBottomColor: '#EEF0E4',\n    },\n    profileContainer: {\n        marginRight: 15,\n    },\n    profileImage: {\n        width: 80,\n        height: 80,\n        borderRadius: 40,\n        borderWidth: 2,\n        borderColor: '#4E7D32',\n    },\n    defaultProfileImage: {\n        width: 80,\n        height: 80,\n        borderRadius: 40,\n        borderWidth: 2,\n        borderColor: '#4E7D32',\n        backgroundColor: '#EEF0E4',\n        justifyContent: 'center',\n        alignItems: 'center',\n    },\n    profileInitial: {\n        fontSize: 24,\n        fontWeight: 'bold',\n        color: '#4E7D32',\n    },\n    classInfo: {\n        flex: 1,\n    },\n    classTitle: {\n        fontSize: 16,\n        fontWeight: '600',\n        color: '#2E3326',\n        marginBottom: 5,\n    },\n    instructor: {\n        fontSize: 14,\n        color: '#4E7D32',\n        marginBottom: 8,\n    },\n    reviewContainer: {\n        flexDirection: 'row',\n        alignItems: 'center',\n        marginBottom: 12,\n    },\n    starsContainer: {\n        flexDirection: 'row',\n        marginRight: 5,\n    },\n    ratingText: {\n        fontSize: 12,\n        fontWeight: '600',\n        color: '#2E3326',\n        marginRight: 5,\n    },\n    reviewCount: {\n        fontSize: 12,\n        color: '#7C8070',\n    },\n    buttonRow: {\n        flexDirection: 'row',\n        alignItems: 'center',\n        justifyContent: 'flex-start',\n        marginTop: 5,\n    },\n    joinButton: {\n        paddingHorizontal: 16,\n        paddingVertical: 10,\n        borderRadius: 6,\n        backgroundColor: '#4E7D32',\n        flexShrink: 1,\n        marginRight: 10,\n    },\n    joinButtonText: {\n        color: '#ffffff',\n        fontSize: 14,\n        fontWeight: '600',\n    },\n    messageButton: {\n        padding: 8,\n        borderRadius: 5,\n        marginRight: 0,\n    },\n    likeButton: {\n        padding: 8,\n        borderRadius: 5,\n    },\n    emptyContainer: {\n        flex: 1,\n        justifyContent: 'center',\n        alignItems: 'center',\n        padding: 40,\n        minHeight: 200,\n    },\n    emptyText: {\n        fontSize: 16,\n        color: '#7C8070',\n        marginTop: 10,\n        textAlign: 'center',\n    },\n    registerClassButton: {\n        position: 'absolute',\n        bottom: 110, // 아래 탭 바 위로 올려요\n        right: 20,\n        flexDirection: 'row',\n        alignItems: 'center',\n        backgroundColor: '#4E7D32',\n        paddingVertical: 10,\n        paddingHorizontal: 15,\n        borderRadius: 25,\n        shadowColor: '#000',\n        shadowOffset: { width: 0, height: 4 },\n        shadowOpacity: 0.3,\n        shadowRadius: 5,\n        elevation: 8,\n    },\n    registerClassButtonText: {\n        color: '#fff',\n        fontSize: 16,\n        fontWeight: '600',\n        marginLeft: 5,\n    }\n});\n\nexport default OnlineClass;",
    "components/OnlineClass/OnlineClassMakeVideo.tsx": "import React, { useState, useEffect } from 'react';\nimport {\n    View,\n    Text,\n    StyleSheet,\n    SafeAreaView,\n    TouchableOpacity,\n    TextInput,\n    ScrollView,\n    Alert,\n    Platform,\n} from 'react-native';\nimport { Ionicons } from '@expo/vector-icons';\nimport { router, useLocalSearchParams } from 'expo-router';\nimport * as ImagePicker from 'expo-image-picker';\nimport { useOnlineClass, ClassData } from '@/components/contexts/OnlineClassContext';\nimport AppHeader from '@/components/AppHeader';\n\ninterface VideoData {\n    id: string;\n    videoTitle: string;\n    classTitle: string;\n    duration: string;\n    level: string;\n    type: 'free' | 'mvp';\n    price?: number;\n    uri?: string;\n    fileName?: string;\n}\n\ninterface Fees {\n    uploadFee: number;\n    additionalVideoFee: number;\n    total: number;\n}\n\nconst OnlineClassMakeVideo = () => {\n    const {\n        currentClassData,\n        setCurrentClassData,\n        videos: contextVideos,\n        addVideo: contextAddVideo,\n        updateVideo,\n        removeVideo,\n        setPaymentInfo,\n        calculateFees,\n        setFees, // Add setFees from context\n    } = useOnlineClass();\n\n    const params = useLocalSearchParams();\n    const initialClassDataFromParams = params.classData ? JSON.parse(params.classData as string) : null;\n\n    const [bankName, setBankName] = useState('');\n    const [accountNumber, setAccountNumber] = useState('');\n    const [accountHolder, setAccountHolder] = useState(\n        currentClassData?.instructor || initialClassDataFromParams?.instructor || ''\n    );\n    const [isLoading, setIsLoading] = useState(false);\n    const [localFees, setLocalFees] = useState<Fees>({ uploadFee: 0, additionalVideoFee: 0, total: 0 });\n\n    const levels = ['초급', '중급', '고급'];\n\n    useEffect(() => {\n        // Set currentClassData if provided in params\n        if (initialClassDataFromParams && !currentClassData) {\n            setCurrentClassData(initialClassDataFromParams);\n        }\n\n        // Request media library permissions\n        (async () => {\n            const { status } = await ImagePicker.requestMediaLibraryPermissionsAsync();\n            if (status !== 'granted') {\n                Alert.alert('권한 필요', '갤러리에서 영상을 선택하려면 미디어 라이브러리 접근 권한이 필요합니다.', [{ text: '확인' }]);\n            }\n        })();\n    }, [initialClassDataFromParams, currentClassData, setCurrentClassData]);\n\n    // Update fees when videos change\n    useEffect(() => {\n        const calculatedFees = calculateFees();\n        setLocalFees(calculatedFees);\n        setFees(calculatedFees); // Update context fees\n    }, [contextVideos.length, calculateFees, setFees]);\n\n    const handleAddVideo = (type: 'free' | 'mvp') => {\n        const newVideo: VideoData = {\n            id: Date.now().toString(),\n            videoTitle: '',\n            classTitle: '',\n            duration: '',\n            level: '초급',\n            type,\n            price: type === 'mvp' ? 0 : undefined,\n        };\n        contextAddVideo(newVideo);\n    };\n\n    const handleUpdateVideo = (id: string, field: keyof VideoData, value: any) => {\n        updateVideo(id, field, value);\n    };\n\n    const handleRemoveVideo = (id: string, videoType: 'free' | 'mvp') => {\n        Alert.alert(\n            '영상 삭제',\n            `${videoType === 'free' ? '무료' : 'MVP'} 영상을 삭제하시겠습니까?`,\n            [\n                { text: '취소', style: 'cancel' },\n                {\n                    text: '삭제',\n                    style: 'destructive',\n                    onPress: () => {\n                        removeVideo(id);\n                        Alert.alert('완료', '영상이 삭제되었습니다.');\n                    },\n                },\n            ]\n        );\n    };\n\n    const pickVideo = async (videoId: string) => {\n        Alert.alert(\n            '영상 선택',\n            '영상을 어떻게 가져오시겠습니까?',\n            [\n                { text: '갤러리에서 선택', onPress: () => pickFromGallery(videoId) },\n                { text: '파일에서 선택', onPress: () => pickFromFiles(videoId) },\n                { text: '취소', style: 'cancel' },\n            ]\n        );\n    };\n\n    const pickFromGallery = async (videoId: string) => {\n        try {\n            const result = await ImagePicker.launchImageLibraryAsync({\n                mediaTypes: ImagePicker.MediaTypeOptions.Videos,\n                allowsEditing: false,\n                quality: 1,\n                videoMaxDuration: 3600,\n            });\n\n            if (!result.canceled && result.assets && result.assets.length > 0) {\n                const asset = result.assets[0];\n                handleUpdateVideo(videoId, 'uri', asset.uri);\n                const fileName = asset.fileName || `video_${Date.now()}.mp4`;\n                handleUpdateVideo(videoId, 'fileName', fileName);\n                Alert.alert('완료', '갤러리에서 영상을 선택했습니다.');\n            } else {\n                Alert.alert('알림', '영상 선택이 취소되었습니다.');\n            }\n        } catch (error) {\n            console.error('갤러리 영상 선택 오류:', error);\n            Alert.alert('오류', '갤러리에서 영상을 선택하는 중 문제가 발생했습니다.');\n        }\n    };\n\n    const pickFromFiles = async (videoId: string) => {\n        try {\n            const DocumentPicker = require('expo-document-picker');\n            const result = await DocumentPicker.getDocumentAsync({\n                type: 'video/*',\n                copyToCacheDirectory: true,\n            });\n\n            if (!result.canceled && result.assets && result.assets.length > 0) {\n                const asset = result.assets[0];\n                handleUpdateVideo(videoId, 'uri', asset.uri);\n                handleUpdateVideo(videoId, 'fileName', asset.name);\n                Alert.alert('완료', '파일에서 영상을 선택했습니다.');\n            } else {\n                Alert.alert('알림', '영상 선택이 취소되었습니다.');\n            }\n        } catch (error) {\n            console.error('파일 영상 선택 오류:', error);\n            Alert.alert('오류', '파일에서 영상을 선택하는 중 문제가 발생했습니다.');\n        }\n    };\n\n    const handleSubmit = async () => {\n        if (!currentClassData) {\n            Alert.alert('오류', '클래스 기본 정보가 누락되었습니다.');\n            return;\n        }\n\n        if (contextVideos.length === 0) {\n            Alert.alert('오류', '최소 하나 이상의 영상을 등록해주세요.');\n            return;\n        }\n\n        const hasEmptyFields = contextVideos.some(\n            video =>\n                !video.videoTitle.trim() ||\n                !video.classTitle.trim() ||\n                !video.duration.trim() ||\n                !video.level.trim()\n        );\n        if (hasEmptyFields) {\n            Alert.alert('오류', '모든 영상의 필수 정보를 입력해주세요.');\n            return;\n        }\n\n        const hasEmptyVideo = contextVideos.some(video => !video.uri);\n        if (hasEmptyVideo) {\n            Alert.alert('오류', '모든 영상을 선택해주세요.');\n            return;\n        }\n\n        const mvpVideos = contextVideos.filter(video => video.type === 'mvp');\n        const hasInvalidPrice = mvpVideos.some(\n            video => video.price === undefined || video.price < 0\n        );\n        if (hasInvalidPrice) {\n            Alert.alert('오류', 'MVP 영상의 가격을 올바르게 입력해주세요.');\n            return;\n        }\n\n        if (!bankName.trim() || !accountNumber.trim() || !accountHolder.trim()) {\n            Alert.alert('오류', '계좌 정보를 모두 입력해주세요.');\n            return;\n        }\n\n        const paymentInfo = {\n            bankName: bankName.trim(),\n            accountNumber: accountNumber.trim(),\n            accountHolder: accountHolder.trim(),\n            fees: localFees,\n        };\n        setPaymentInfo(paymentInfo);\n\n        try {\n            router.push({\n                pathname: '/OnlineClassPayment',\n                params: {\n                    classData: JSON.stringify(currentClassData),\n                },\n            });\n        } catch (error) {\n            console.error('화면 이동 오류:', error);\n            Alert.alert('오류', '결제 화면으로 이동 중 문제가 발생했습니다.');\n        }\n    };\n\n    const renderLevelButton = (videoId: string, levelOption: string) => (\n        <TouchableOpacity\n            key={levelOption}\n            style={[\n                styles.levelButton,\n                contextVideos.find(v => v.id === videoId)?.level === levelOption && styles.activeLevelButton,\n            ]}\n            onPress={() => handleUpdateVideo(videoId, 'level', levelOption)}\n        >\n            <Text\n                style={[\n                    styles.levelButtonText,\n                    contextVideos.find(v => v.id === videoId)?.level === levelOption && styles.activeLevelButtonText,\n                ]}\n            >\n                {levelOption}\n            </Text>\n        </TouchableOpacity>\n    );\n\n    const renderVideo = (video: VideoData) => (\n        <View key={video.id} style={styles.videoContainer}>\n            <View style={styles.videoHeader}>\n                <View style={styles.videoTypeContainer}>\n                    <Text\n                        style={[\n                            styles.videoTypeLabel,\n                            video.type === 'free' ? styles.freeTypeLabel : styles.mvpTypeLabel,\n                        ]}\n                    >\n                        {video.type === 'free' ? '무료 영상' : 'MVP 영상'}\n                    </Text>\n                </View>\n                <TouchableOpacity\n                    onPress={() => handleRemoveVideo(video.id, video.type)}\n                    style={styles.removeButton}\n                >\n                    <Ionicons name=\"close-circle\" size={28} color=\"#ff4444\" />\n                </TouchableOpacity>\n            </View>\n\n            <View style={styles.inputGroup}>\n                <Text style={styles.label}>수업 제목 *</Text>\n                <TextInput\n                    style={styles.textInput}\n                    value={video.classTitle}\n                    onChangeText={text => handleUpdateVideo(video.id, 'classTitle', text)}\n                    placeholder=\"수업 제목을 입력하세요\"\n                    placeholderTextColor=\"#A3A794\"\n                    maxLength={50}\n                />\n            </View>\n\n            <View style={styles.inputGroup}>\n                <Text style={styles.label}>수업 시간 *</Text>\n                <TextInput\n                    style={styles.textInput}\n                    value={video.duration}\n                    onChangeText={text => handleUpdateVideo(video.id, 'duration', text)}\n                    placeholder=\"예: 2시간 30분\"\n                    placeholderTextColor=\"#A3A794\"\n                />\n            </View>\n\n            <View style={styles.inputGroup}>\n                <Text style={styles.label}>수업 레벨 *</Text>\n                <View style={styles.levelContainer}>{levels.map(level => renderLevelButton(video.id, level))}</View>\n            </View>\n\n            <View style={styles.inputGroup}>\n                <Text style={styles.label}>영상 제목 *</Text>\n                <TextInput\n                    style={styles.textInput}\n                    value={video.videoTitle}\n                    onChangeText={text => handleUpdateVideo(video.id, 'videoTitle', text)}\n                    placeholder=\"영상 제목을 입력하세요\"\n                    placeholderTextColor=\"#A3A794\"\n                    maxLength={50}\n                />\n            </View>\n\n            {video.type === 'mvp' && (\n                <View style={styles.inputGroup}>\n                    <Text style={styles.label}>가격 (원) *</Text>\n                    <TextInput\n                        style={styles.textInput}\n                        value={video.price?.toString() || ''}\n                        onChangeText={text => {\n                            const price = parseInt(text) || 0;\n                            handleUpdateVideo(video.id, 'price', price);\n                        }}\n                        placeholder=\"0\"\n                        placeholderTextColor=\"#A3A794\"\n                        keyboardType=\"numeric\"\n                    />\n                </View>\n            )}\n\n            <View style={styles.inputGroup}>\n                <Text style={styles.label}>영상 파일 *</Text>\n                <TouchableOpacity style={styles.videoPickerButton} onPress={() => pickVideo(video.id)}>\n                    <Ionicons\n                        name={video.uri ? 'checkmark-circle' : 'videocam-outline'}\n                        size={24}\n                        color={video.uri ? '#4E7D32' : '#4E7D32'}\n                    />\n                    <Text style={[styles.videoPickerText, video.uri && styles.videoPickerTextSelected]}>\n                        {video.fileName || '갤러리 또는 파일에서 영상 선택'}\n                    </Text>\n                </TouchableOpacity>\n            </View>\n\n            <View style={styles.videoFooter}>\n                <Text style={styles.removeHint}>우상단의 X 버튼을 눌러 영상을 삭제할 수 있습니다.</Text>\n            </View>\n        </View>\n    );\n\n    return (\n        <View style={styles.container}>\n            {/* 공통 헤더: < 영상 등록 [다음] 🔔 */}\n            <AppHeader\n                title=\"영상 등록\"\n                onBack={() => { if (!isLoading) router.back(); }}\n                right={[{ label: isLoading ? '처리중' : '다음', onPress: handleSubmit, disabled: isLoading, color: '#4E7D32', accessibilityLabel: '결제하러 가기' }]}\n            />\n\n            <ScrollView style={styles.scrollContainer} showsVerticalScrollIndicator={false}>\n                <View style={styles.content}>\n                    <View style={styles.addButtonContainer}>\n                        <TouchableOpacity\n                            style={[styles.addButton, styles.freeButton]}\n                            onPress={() => handleAddVideo('free')}\n                            disabled={isLoading}\n                        >\n                            <Ionicons name=\"add-circle-outline\" size={24} color=\"#4E7D32\" />\n                            <Text style={[styles.addButtonText, { color: '#4E7D32' }]}>무료 영상 추가</Text>\n                        </TouchableOpacity>\n                        <TouchableOpacity\n                            style={[styles.addButton, styles.mvpButton]}\n                            onPress={() => handleAddVideo('mvp')}\n                            disabled={isLoading}\n                        >\n                            <Ionicons name=\"add-circle-outline\" size={24} color=\"#4E7D32\" />\n                            <Text style={[styles.addButtonText, { color: '#4E7D32' }]}>MVP 영상 추가</Text>\n                        </TouchableOpacity>\n                    </View>\n\n                    {contextVideos.length === 0 && (\n                        <View style={styles.emptyContainer}>\n                            <Ionicons name=\"film-outline\" size={48} color=\"#C9CCB8\" />\n                            <Text style={styles.emptyText}>위의 버튼을 눌러 영상을 추가해보세요</Text>\n                        </View>\n                    )}\n\n                    <View style={styles.videoList}>{contextVideos.map(renderVideo)}</View>\n\n                    {contextVideos.length > 0 && (\n                        <View style={styles.accountContainer}>\n                            <Text style={styles.sectionTitle}>결제 정보</Text>\n                            <View style={styles.inputGroup}>\n                                <Text style={styles.label}>은행명 *</Text>\n                                <TextInput\n                                    style={styles.textInput}\n                                    value={bankName}\n                                    onChangeText={setBankName}\n                                    placeholder=\"예: 국민은행\"\n                                    placeholderTextColor=\"#A3A794\"\n                                />\n                            </View>\n                            <View style={styles.inputGroup}>\n                                <Text style={styles.label}>계좌번호 *</Text>\n                                <TextInput\n                                    style={styles.textInput}\n                                    value={accountNumber}\n                                    onChangeText={setAccountNumber}\n                                    placeholder=\"계좌번호를 입력하세요\"\n                                    placeholderTextColor=\"#A3A794\"\n                                    keyboardType=\"numeric\"\n                                />\n                            </View>\n                            <View style={styles.inputGroup}>\n                                <Text style={styles.label}>예금주 *</Text>\n                                <TextInput\n                                    style={styles.textInput}\n                                    value={accountHolder}\n                                    onChangeText={setAccountHolder}\n                                    placeholder=\"예금주명을 입력하세요\"\n                                    placeholderTextColor=\"#A3A794\"\n                                />\n                            </View>\n                            <View style={styles.feesContainer}>\n                                <Text style={styles.sectionTitle}>결제 요금</Text>\n                                <View style={styles.feeRow}>\n                                    <Text style={styles.feeLabel}>기본 업로드 요금</Text>\n                                    <Text style={styles.feeValue}>{localFees.uploadFee.toLocaleString()}원</Text>\n                                </View>\n                                <View style={styles.feeRow}>\n                                    <Text style={styles.feeLabel}>추가 영상 요금</Text>\n                                    <Text style={styles.feeValue}>{localFees.additionalVideoFee.toLocaleString()}원</Text>\n                                </View>\n                                <View style={styles.feeRow}>\n                                    <Text style={styles.feeLabel}>총 요금</Text>\n                                    <Text style={styles.feeValue}>{localFees.total.toLocaleString()}원</Text>\n                                </View>\n                            </View>\n                        </View>\n                    )}\n\n                    <View style={styles.noteContainer}>\n                        <Ionicons name=\"information-circle-outline\" size={20} color=\"#7C8070\" />\n                        <Text style={styles.noteText}>\n                            • 무료 영상은 모든 사용자가 볼 수 있습니다.{'\\n'}\n                            • MVP 영상은 결제 후 시청 가능합니다.{'\\n'}\n                            • 등록된 클래스는 관리자 승인 후 공개됩니다.{'\\n'}\n                            • 영상 삭제는 각 영상 카드의 X 버튼을 이용해주세요.{'\\n'}\n                            • 갤러리와 파일에서 영상을 선택할 수 있습니다.\n                        </Text>\n                    </View>\n                </View>\n            </ScrollView>\n        </View>\n    );\n};\n\nconst styles = StyleSheet.create({\n    container: { flex: 1, backgroundColor: '#fff' },\n    header: {\n        flexDirection: 'row',\n        justifyContent: 'space-between',\n        alignItems: 'center',\n        paddingHorizontal: 20,\n        paddingVertical: 15,\n        backgroundColor: '#fff',\n        borderBottomWidth: 1,\n        borderBottomColor: '#EEF0E4',\n    },\n    headerTitle: { fontSize: 18, fontWeight: 'bold', color: '#2E3326' },\n    submitButton: { paddingHorizontal: 12, paddingVertical: 6 },\n    submitButtonText: { fontSize: 16, fontWeight: 'bold', color: '#4E7D32' },\n    scrollContainer: { flex: 1 },\n    content: { padding: 20 },\n    addButtonContainer: { flexDirection: 'row', gap: 12, marginBottom: 24 },\n    addButton: {\n        flex: 1,\n        flexDirection: 'row',\n        alignItems: 'center',\n        justifyContent: 'center',\n        padding: 16,\n        borderRadius: 12,\n        borderWidth: 1,\n        gap: 8,\n    },\n    freeButton: { backgroundColor: '#F4F8EE', borderColor: '#4E7D32' },\n    mvpButton: { backgroundColor: '#F4F8EE', borderColor: '#4E7D32' },\n    addButtonText: { fontSize: 16, fontWeight: '600' },\n    emptyContainer: {\n        alignItems: 'center',\n        justifyContent: 'center',\n        paddingVertical: 40,\n        backgroundColor: '#FBFAF4',\n        borderRadius: 12,\n        marginBottom: 24,\n    },\n    emptyText: { fontSize: 16, color: '#A3A794', marginTop: 12, textAlign: 'center' },\n    videoList: { gap: 16, marginBottom: 32 },\n    videoContainer: {\n        backgroundColor: '#fff',\n        borderRadius: 12,\n        borderWidth: 1,\n        borderColor: '#E6E8DA',\n        padding: 16,\n        shadowColor: '#000',\n        shadowOffset: { width: 0, height: 2 },\n        shadowOpacity: 0.05,\n        shadowRadius: 4,\n        elevation: 2,\n    },\n    videoHeader: {\n        flexDirection: 'row',\n        justifyContent: 'space-between',\n        alignItems: 'center',\n        marginBottom: 16,\n    },\n    videoTypeContainer: { flex: 1 },\n    videoTypeLabel: {\n        fontSize: 16,\n        fontWeight: 'bold',\n        paddingHorizontal: 12,\n        paddingVertical: 6,\n        borderRadius: 16,\n        textAlign: 'center',\n        minWidth: 80,\n    },\n    freeTypeLabel: { backgroundColor: '#E8F2DE', color: '#4E7D32' },\n    mvpTypeLabel: { backgroundColor: '#E8F2DE', color: '#4E7D32' },\n    removeButton: { padding: 4, borderRadius: 20, backgroundColor: '#fff2f2' },\n    inputGroup: { marginBottom: 16 },\n    label: { fontSize: 14, fontWeight: '600', color: '#2E3326', marginBottom: 8 },\n    textInput: {\n        borderWidth: 1,\n        borderColor: '#E6E8DA',\n        borderRadius: 8,\n        paddingHorizontal: 12,\n        paddingVertical: 10,\n        fontSize: 16,\n        backgroundColor: '#fff',\n        color: '#2E3326',\n    },\n    videoPickerButton: {\n        flexDirection: 'row',\n        alignItems: 'center',\n        padding: 16,\n        borderWidth: 1,\n        borderColor: '#E6E8DA',\n        borderRadius: 8,\n        backgroundColor: '#FBFAF4',\n        gap: 12,\n    },\n    videoPickerText: { fontSize: 16, color: '#7C8070', flex: 1 },\n    videoPickerTextSelected: { color: '#4E7D32', fontWeight: '500' },\n    videoFooter: {\n        marginTop: 12,\n        paddingTop: 12,\n        borderTopWidth: 1,\n        borderTopColor: '#EEF0E4',\n    },\n    removeHint: { fontSize: 12, color: '#A3A794', textAlign: 'center', fontStyle: 'italic' },\n    accountContainer: {\n        backgroundColor: '#fff',\n        borderRadius: 12,\n        borderWidth: 1,\n        borderColor: '#E6E8DA',\n        padding: 20,\n        marginBottom: 24,\n        shadowColor: '#000',\n        shadowOffset: { width: 0, height: 2 },\n        shadowOpacity: 0.05,\n        shadowRadius: 4,\n        elevation: 2,\n    },\n    sectionTitle: { fontSize: 18, fontWeight: 'bold', color: '#2E3326', marginBottom: 16 },\n    feesContainer: { marginTop: 16 },\n    feeRow: {\n        flexDirection: 'row',\n        justifyContent: 'space-between',\n        paddingVertical: 8,\n        borderBottomWidth: 1,\n        borderBottomColor: '#EEF0E4',\n    },\n    feeLabel: { fontSize: 14, color: '#7C8070' },\n    feeValue: { fontSize: 14, fontWeight: '500', color: '#2E3326' },\n    noteContainer: {\n        flexDirection: 'row',\n        backgroundColor: '#FBFAF4',\n        padding: 16,\n        borderRadius: 8,\n        gap: 8,\n        borderLeftWidth: 4,\n        borderLeftColor: '#4E7D32',\n    },\n    noteText: { flex: 1, fontSize: 14, color: '#7C8070', lineHeight: 20 },\n    levelContainer: { flexDirection: 'row', gap: 10 },\n    levelButton: {\n        paddingHorizontal: 16,\n        paddingVertical: 8,\n        borderRadius: 20,\n        backgroundColor: '#FBFAF4',\n        borderWidth: 1,\n        borderColor: '#E6E8DA',\n    },\n    activeLevelButton: { backgroundColor: '#4E7D32', borderColor: '#4E7D32' },\n    levelButtonText: { fontSize: 14, color: '#7C8070', fontWeight: '500' },\n    activeLevelButtonText: { color: '#fff' },\n});\n\nexport default OnlineClassMakeVideo;",
    "components/OnlineClass/OnlineClassMyDetail.tsx": "import React, { useState, useEffect, useMemo } from 'react';\nimport {\n    View,\n    Text,\n    StyleSheet,\n    ScrollView,\n    Image,\n    TouchableOpacity,\n    Alert,\n    Platform,\n} from 'react-native';\nimport { Ionicons } from '@expo/vector-icons';\nimport { useLocalSearchParams, useRouter } from 'expo-router';\nimport { useOnlineClass } from '@/components/contexts/OnlineClassContext';\nimport { useAuth } from '@/components/contexts/AuthProvider';\nimport { useOnlineClassReviews } from '@/components/contexts/OnlineClassReviewContext';\nimport AppHeader from '@/components/AppHeader';\nimport { toImageUrl } from '@/config';\n\n// embedded: 다른 화면(내 게시판의 '온라인 수업' 탭) 안에 넣을 때 true → 자체 헤더를 숨겨요\nconst OnlineClassMyDetail = ({ embedded = false }: { embedded?: boolean }) => {\n    const router = useRouter();\n    const { classes, videos, paymentInfo, isPaymentComplete, deleteClass } = useOnlineClass();\n    const { currentUser } = useAuth();\n    const { reviews, fetchReviews } = useOnlineClassReviews();\n\n    const params = useLocalSearchParams();\n    const { id, title, instructor, profileImage, introduction: introFromParams, description: descFromParams } = params;\n\n    const [activeTab, setActiveTab] = useState<'intro' | 'free' | 'mvp' | 'review'>('intro');\n\n    const currentClass = useMemo(() => {\n        // id가 없으면(내 게시판 안) 내가 만든 수업을 먼저 보여줘요\n        return classes.find(cls => cls.id === id)\n            || classes.find(cls => cls.createdBy === currentUser?.name)\n            || classes[classes.length - 1];\n    }, [classes, id, currentUser?.name]);\n\n    const classId = id as string;\n\n    const defaultIntro = '안녕하세요! 저는 10년 경력의 개발자로, 실무에서 바로 활용할 수 있는 실전 위주의 강의를 제공합니다. 여러분의 성장을 위해 최선을 다하겠습니다.';\n    const defaultDesc = '실무 중심의 체계적인 프로그래밍 교육을 통해 여러분을 전문 개발자로 성장시켜드립니다.';\n    const defaultTitle = '강의명 정보 없음';\n\n    const [currentIntroduction, setCurrentIntroduction] = useState(\n        (introFromParams as string) || currentClass?.introduction || defaultIntro\n    );\n    const [currentDescription, setCurrentDescription] = useState(\n        (descFromParams as string) || currentClass?.description || defaultDesc\n    );\n    const [currentTitle, setCurrentTitle] = useState(\n        (title as string) || currentClass?.title || defaultTitle\n    );\n\n    useEffect(() => {\n        const updateState = (cls: any) => {\n            if (cls?.introduction) setCurrentIntroduction(cls.introduction);\n            else if (introFromParams) setCurrentIntroduction(introFromParams as string);\n            else setCurrentIntroduction(defaultIntro);\n\n            if (cls?.description) setCurrentDescription(cls.description);\n            else if (descFromParams) setCurrentDescription(descFromParams as string);\n            else setCurrentDescription(defaultDesc);\n\n            if (cls?.title) setCurrentTitle(cls.title);\n            else if (title) setCurrentTitle(title as string);\n            else setCurrentTitle(defaultTitle);\n        };\n\n        if (currentClass) {\n            updateState(currentClass);\n        } else {\n            updateState({ introduction: introFromParams, description: descFromParams, title });\n        }\n\n        if (classId) {\n            fetchReviews(classId);\n        }\n    }, [currentClass, introFromParams, descFromParams, title, classId, fetchReviews]);\n\n    const instructorInfo = {\n        // 로그인한 내 이름과 프로필 사진을 먼저 보여줘요\n        name: currentUser?.name || currentClass?.instructor || (instructor as string) || '강사 이름',\n        profileImage: toImageUrl(currentUser?.profileImage || currentClass?.profileImage || (profileImage as string)),\n        bio: currentIntroduction,\n        description: currentDescription,\n    };\n\n    const classReviews = reviews[classId] || [];\n    const reviewCount = classReviews.length;\n    const averageRating = reviewCount > 0\n        ? (classReviews.reduce((sum, review) => sum + review.rating, 0) / reviewCount).toFixed(1)\n        : '0.0';\n\n    const renderStars = (starRating: number) => {\n        const stars = [];\n        const fullStars = Math.floor(starRating);\n        const hasHalfStar = starRating % 1 !== 0;\n\n        for (let i = 0; i < fullStars; i++) {\n            stars.push(<Ionicons key={`star-${i}`} name=\"star\" size={16} color=\"#ffc107\" />);\n        }\n        if (hasHalfStar) {\n            stars.push(<Ionicons key=\"half-star\" name=\"star-half\" size={16} color=\"#ffc107\" />);\n        }\n        const remainingStars = 5 - Math.ceil(starRating);\n        for (let i = 0; i < remainingStars; i++) {\n            stars.push(<Ionicons key={`empty-star-${i}`} name=\"star-outline\" size={16} color=\"#ffc107\" />);\n        }\n        return stars;\n    };\n\n    const renderVideoThumbnail = () => (\n        <View style={styles.videoThumbnail}>\n            <View style={styles.thumbnailPlaceholder}>\n                <Ionicons name=\"play-circle\" size={40} color=\"#4E7D32\" />\n            </View>\n            <View style={styles.videoBadge}>\n                <Text style={styles.videoBadgeText}>HD</Text>\n            </View>\n        </View>\n    );\n\n    const handleSendMessage = () => {\n        console.log(`${instructorInfo.name} 강사에게 메시지 보내기`);\n        Alert.alert('기능 준비 중', '받은 메시지 확인 기능은 현재 개발 중입니다.');\n    };\n\n    const handleClassEdit = () => {\n        router.push({\n            pathname: '/MakeOnlineClass',\n            params: {\n                id: classId,\n                title: currentTitle,\n                introduction: currentIntroduction,\n                description: currentDescription,\n                instructorName: instructorInfo.name,\n                instructorProfileImage: instructorInfo.profileImage,\n                isEditing: 'true',\n            }\n        });\n    };\n\n    const handleClassDelete = () => {\n        Alert.alert(\n            '클래스 삭제',\n            '정말로 이 클래스를 삭제하시겠습니까? 모든 정보와 영상이 삭제됩니다.',\n            [\n                { text: '취소', style: 'cancel' },\n                {\n                    text: '삭제',\n                    style: 'destructive',\n                    onPress: () => {\n                        if (classId) {\n                            deleteClass(classId);\n                            router.back();\n                        }\n                    },\n                },\n            ]\n        );\n    };\n\n    const handleVideoDelete = (videoId: string, videoTitle: string) => {\n        Alert.alert(\n            '영상 삭제',\n            `'${videoTitle || '제목 없음'}' 영상을 삭제하시겠습니까?`,\n            [\n                { text: '취소', style: 'cancel' },\n                {\n                    text: '삭제',\n                    style: 'destructive',\n                    onPress: () => {\n                        console.log(`Deleting video: ${videoId}`);\n                        Alert.alert('영상 삭제', '영상 삭제 기능은 현재 개발 중입니다.');\n                    },\n                },\n            ]\n        );\n    };\n\n    const getBottomButtonText = () => {\n        switch (activeTab) {\n            case 'intro':\n                const hasClassRegistered = currentClass && currentClass.id;\n                return hasClassRegistered ? '클래스 수정하기' : '클래스 등록하기';\n            case 'free':\n            case 'mvp':\n                return '영상 등록하기';\n            case 'review':\n            default:\n                return '클래스 등록하기/수정하기';\n        }\n    };\n\n    const handleBottomButtonPress = () => {\n        const hasClassRegistered = currentClass && currentClass.id;\n\n        switch (activeTab) {\n            case 'intro':\n                if (hasClassRegistered) {\n                    handleClassEdit();\n                } else {\n                    router.push({\n                        pathname: '/MakeOnlineClass',\n                        params: {\n                            instructorName: instructorInfo.name,\n                            instructorProfileImage: instructorInfo.profileImage,\n                        }\n                    });\n                }\n                break;\n            case 'free':\n            case 'mvp':\n                if (hasClassRegistered) {\n                    router.push({\n                        pathname: '/OnlineClassMakeVideo',\n                        params: {\n                            classId: classId,\n                            videoType: activeTab,\n                            classData: JSON.stringify(currentClass),\n                        }\n                    });\n                } else {\n                    Alert.alert('클래스 미등록', '영상을 등록하기 전에 먼저 클래스 정보를 등록해 주세요.', [\n                        { text: '확인' },\n                        { text: '클래스 등록', onPress: () => setActiveTab('intro') },\n                    ]);\n                }\n                break;\n            case 'review':\n            default:\n                break;\n        }\n    };\n\n    const renderTabContent = () => {\n        const hasClassInfo =\n            currentIntroduction !== defaultIntro ||\n            currentDescription !== defaultDesc ||\n            currentTitle !== defaultTitle;\n\n        switch (activeTab) {\n            case 'intro':\n                return (\n                    <View style={styles.tabContent}>\n                        {hasClassInfo && currentClass ? (\n                            <>\n                                <View style={styles.actionButtonsContainer}>\n                                    <TouchableOpacity style={[styles.actionButton, styles.editButton]} onPress={handleClassEdit}>\n                                        <Ionicons name=\"create-outline\" size={18} color=\"#4E7D32\" />\n                                        <Text style={styles.editButtonText}>수정</Text>\n                                    </TouchableOpacity>\n                                    <TouchableOpacity style={[styles.actionButton, styles.deleteButton]} onPress={handleClassDelete}>\n                                        <Ionicons name=\"trash-outline\" size={18} color=\"#dc3545\" />\n                                        <Text style={styles.deleteButtonText}>삭제</Text>\n                                    </TouchableOpacity>\n                                </View>\n\n                                <View style={styles.introCard}>\n                                    <View style={styles.introHeader}>\n                                        <Ionicons name=\"person-circle\" size={24} color=\"#4E7D32\" />\n                                        <Text style={styles.cardTitle}>강사 소개</Text>\n                                    </View>\n                                    <Text style={styles.bioText}>{instructorInfo.bio}</Text>\n                                    <View style={styles.divider} />\n                                    <View style={styles.descriptionSection}>\n                                        <Text style={styles.descriptionLabel}>강의 설명</Text>\n                                        <Text style={styles.descriptionText}>{instructorInfo.description}</Text>\n                                    </View>\n                                </View>\n\n                                <View style={styles.infoCard}>\n                                    <View style={styles.introHeader}>\n                                        <Ionicons name=\"book\" size={24} color=\"#4E7D32\" />\n                                        <Text style={styles.cardTitle}>강의 정보</Text>\n                                    </View>\n                                    <View style={styles.infoRow}>\n                                        <Text style={styles.infoLabel}>강의명</Text>\n                                        <Text style={styles.infoValue}>{currentTitle}</Text>\n                                    </View>\n                                    <View style={styles.infoRow}>\n                                        <Text style={styles.infoLabel}>강사</Text>\n                                        <Text style={styles.infoValue}>{instructorInfo.name}</Text>\n                                    </View>\n                                    <View style={styles.infoRow}>\n                                        <Text style={styles.infoLabel}>등록된 영상 수</Text>\n                                        <Text style={styles.infoValue}>{videos.length}개</Text>\n                                    </View>\n                                    <View style={styles.infoRow}>\n                                        <Text style={styles.infoLabel}>무료 영상</Text>\n                                        <Text style={styles.infoValue}>{videos.filter(v => v.type === 'free').length}개</Text>\n                                    </View>\n                                    <View style={styles.infoRow}>\n                                        <Text style={styles.infoLabel}>MVP 영상</Text>\n                                        <Text style={styles.infoValue}>{videos.filter(v => v.type === 'mvp').length}개</Text>\n                                    </View>\n                                </View>\n\n                                {paymentInfo && (\n                                    <View style={styles.paymentCard}>\n                                        <View style={styles.introHeader}>\n                                            <Ionicons name=\"card\" size={24} color=\"#ffc107\" />\n                                            <Text style={styles.cardTitle}>결제 정보</Text>\n                                        </View>\n                                        <View style={styles.paymentInfo}>\n                                            <View style={styles.infoRow}>\n                                                <Text style={styles.infoLabel}>은행명</Text>\n                                                <Text style={styles.infoValue}>{paymentInfo.bankName}</Text>\n                                            </View>\n                                            <View style={styles.infoRow}>\n                                                <Text style={styles.infoLabel}>계좌번호</Text>\n                                                <Text style={styles.infoValue}>{paymentInfo.accountNumber}</Text>\n                                            </View>\n                                            <View style={styles.infoRow}>\n                                                <Text style={styles.infoLabel}>예금주</Text>\n                                                <Text style={styles.infoValue}>{paymentInfo.accountHolder}</Text>\n                                            </View>\n                                        </View>\n                                    </View>\n                                )}\n                            </>\n                        ) : (\n                            <View style={styles.noInfoCard}>\n                                <Ionicons name=\"information-circle-outline\" size={50} color=\"#C9CCB8\" />\n                                <Text style={styles.noInfoTitle}>아직 등록된 클래스 소개가 없습니다.</Text>\n                                <Text style={styles.noInfoSubtitle}>아래 '{getBottomButtonText()}' 버튼을 눌러 정보를 추가해 주세요.</Text>\n                            </View>\n                        )}\n                    </View>\n                );\n            case 'free':\n                const freeVideos = videos.filter(video => video.type === 'free');\n                return (\n                    <View style={styles.tabContent}>\n                        <View style={styles.videoSection}>\n                            <View style={styles.sectionHeader}>\n                                <Ionicons name=\"videocam\" size={24} color=\"#4E7D32\" />\n                                <Text style={styles.sectionTitle}>무료 영상</Text>\n                                <View style={styles.freeBadge}>\n                                    <Text style={styles.freeBadgeText}>FREE</Text>\n                                </View>\n                            </View>\n                            {freeVideos.length > 0 ? (\n                                freeVideos.map(video => (\n                                    <View key={video.id} style={styles.videoCard}>\n                                        <View style={styles.videoLeft}>\n                                            {renderVideoThumbnail()}\n                                        </View>\n                                        <View style={styles.videoRight}>\n                                            <View style={styles.videoTitleContainer}>\n                                                <Text style={styles.videoTitle}>{video.videoTitle || '제목 없음'}</Text>\n                                                <TouchableOpacity onPress={() => handleVideoDelete(video.id, video.videoTitle)}>\n                                                    <Ionicons name=\"trash-outline\" size={20} color=\"#dc3545\" />\n                                                </TouchableOpacity>\n                                            </View>\n                                            <View style={styles.videoMetadata}>\n                                                <View style={styles.metaItem}>\n                                                    <Ionicons name=\"time-outline\" size={16} color=\"#7C8070\" />\n                                                    <Text style={styles.metaText}>{video.duration || '시간 미정'}</Text>\n                                                </View>\n                                                <View style={styles.metaItem}>\n                                                    <Ionicons name=\"bar-chart-outline\" size={16} color=\"#7C8070\" />\n                                                    <Text style={styles.metaText}>{video.level || '난이도 미정'}</Text>\n                                                </View>\n                                            </View>\n                                            <TouchableOpacity style={styles.playButton}>\n                                                <Ionicons name=\"play\" size={16} color=\"#fff\" />\n                                                <Text style={styles.playButtonText}>재생</Text>\n                                            </TouchableOpacity>\n                                        </View>\n                                    </View>\n                                ))\n                            ) : (\n                                <View style={styles.videoPlaceholder}>\n                                    <Ionicons name=\"videocam-outline\" size={50} color=\"#C9CCB8\" />\n                                    <Text style={styles.placeholderTitle}>무료 영상 준비 중</Text>\n                                    <Text style={styles.placeholderSubtitle}>아래 '{getBottomButtonText()}' 버튼을 눌러 영상을 추가해 주세요.</Text>\n                                </View>\n                            )}\n                        </View>\n                    </View>\n                );\n            case 'mvp':\n                const mvpVideos = videos.filter(video => video.type === 'mvp');\n                return (\n                    <View style={styles.tabContent}>\n                        <View style={styles.videoSection}>\n                            <View style={styles.sectionHeader}>\n                                <Ionicons name=\"diamond\" size={24} color=\"#3B5A24\" />\n                                <Text style={styles.sectionTitle}>MVP 영상</Text>\n                                <View style={styles.mvpBadge}>\n                                    <Text style={styles.mvpBadgeText}>PREMIUM</Text>\n                                </View>\n                            </View>\n                            {mvpVideos.length > 0 ? (\n                                mvpVideos.map(video => (\n                                    <View key={video.id} style={styles.videoCard}>\n                                        <View style={styles.videoLeft}>\n                                            {renderVideoThumbnail()}\n                                            <View style={styles.premiumOverlay}>\n                                                <Ionicons name=\"lock-closed\" size={20} color=\"#fff\" />\n                                            </View>\n                                        </View>\n                                        <View style={styles.videoRight}>\n                                            <View style={styles.videoTitleContainer}>\n                                                <Text style={styles.videoTitle}>{video.videoTitle || '제목 없음'}</Text>\n                                                <TouchableOpacity onPress={() => handleVideoDelete(video.id, video.videoTitle)}>\n                                                    <Ionicons name=\"trash-outline\" size={20} color=\"#dc3545\" />\n                                                </TouchableOpacity>\n                                            </View>\n                                            <View style={styles.videoMetadata}>\n                                                <View style={styles.metaItem}>\n                                                    <Ionicons name=\"time-outline\" size={16} color=\"#7C8070\" />\n                                                    <Text style={styles.metaText}>{video.duration || '시간 미정'}</Text>\n                                                </View>\n                                                <View style={styles.metaItem}>\n                                                    <Ionicons name=\"bar-chart-outline\" size={16} color=\"#7C8070\" />\n                                                    <Text style={styles.metaText}>{video.level || '난이도 미정'}</Text>\n                                                </View>\n                                                <View style={styles.priceTag}>\n                                                    <Text style={styles.priceText}>{video.price || 0}원</Text>\n                                                </View>\n                                            </View>\n                                            <TouchableOpacity style={styles.purchaseButton}>\n                                                <Ionicons name=\"diamond\" size={16} color=\"#fff\" />\n                                                <Text style={styles.purchaseButtonText}>구매</Text>\n                                            </TouchableOpacity>\n                                        </View>\n                                    </View>\n                                ))\n                            ) : (\n                                <View style={styles.videoPlaceholder}>\n                                    <Ionicons name=\"diamond-outline\" size={50} color=\"#C9CCB8\" />\n                                    <Text style={styles.placeholderTitle}>MVP 영상 준비 중</Text>\n                                    <Text style={styles.placeholderSubtitle}>아래 '{getBottomButtonText()}' 버튼을 눌러 프리미엄 영상을 추가해 주세요.</Text>\n                                </View>\n                            )}\n                        </View>\n                    </View>\n                );\n            case 'review':\n                return (\n                    <View style={styles.tabContent}>\n                        <View style={styles.reviewSection}>\n                            <View style={styles.sectionHeader}>\n                                <Ionicons name=\"chatbubbles\" size={24} color=\"#ff6b6b\" />\n                                <Text style={styles.sectionTitle}>리뷰 ({reviewCount}개)</Text>\n                                <View style={styles.ratingBadge}>\n                                    <Ionicons name=\"star\" size={16} color=\"#ffc107\" />\n                                    <Text style={styles.ratingBadgeText}>{averageRating}</Text>\n                                </View>\n                            </View>\n                            {classReviews.length > 0 ? (\n                                classReviews.map((review, index) => (\n                                    <View key={index} style={styles.reviewItem}>\n                                        <View style={styles.reviewUserHeader}>\n                                            <View style={styles.reviewUserProfile}>\n                                                {review.userProfileImage ? (\n                                                    <Image source={{ uri: review.userProfileImage }} style={styles.reviewUserProfileImage} />\n                                                ) : (\n                                                    <View style={styles.reviewUserDefaultProfile}>\n                                                        <Text style={styles.reviewUserInitial}>{review.userNickname?.[0] || 'U'}</Text>\n                                                    </View>\n                                                )}\n                                                <Text style={styles.reviewUserNickname}>{review.userNickname}</Text>\n                                            </View>\n                                            <View style={styles.reviewRating}>\n                                                {renderStars(review.rating)}\n                                            </View>\n                                        </View>\n                                        <Text style={styles.reviewText}>{review.reviewText}</Text>\n                                    </View>\n                                ))\n                            ) : (\n                                <View style={styles.reviewPlaceholder}>\n                                    <Ionicons name=\"chatbubbles-outline\" size={50} color=\"#C9CCB8\" />\n                                    <Text style={styles.placeholderTitle}>아직 작성된 리뷰가 없어요!</Text>\n                                    <Text style={styles.placeholderSubtitle}>수강생의 첫 번째 리뷰를 기다립니다. ✨</Text>\n                                </View>\n                            )}\n                        </View>\n                    </View>\n                );\n            default:\n                return null;\n        }\n    };\n\n    return (\n        <View style={styles.container}>\n            {/* 공통 헤더 (다른 화면 안에 들어갈 때는 숨김 → 헤더 2개 방지) */}\n            {!embedded && <AppHeader title=\"내 클래스\" />}\n            <ScrollView showsVerticalScrollIndicator={false}>\n                <View style={styles.profileHeader}>\n                    <View style={styles.profileImageContainer}>\n                        {instructorInfo.profileImage ? (\n                            <Image source={{ uri: instructorInfo.profileImage }} style={styles.profileImage} />\n                        ) : (\n                            <View style={styles.defaultProfileImage}>\n                                <Text style={styles.profileInitial}>{instructorInfo.name[0] || '?'}</Text>\n                            </View>\n                        )}\n                    </View>\n                    <Text style={styles.profileName}>{instructorInfo.name}</Text>\n                    <TouchableOpacity style={styles.messageButton} onPress={handleSendMessage}>\n                        <Ionicons name=\"chatbubble-ellipses-outline\" size={20} color=\"#4E7D32\" />\n                        <Text style={styles.messageButtonText}>받은 메시지</Text>\n                    </TouchableOpacity>\n                </View>\n\n                <View style={styles.tabsContainer}>\n                    <TouchableOpacity onPress={() => setActiveTab('intro')} style={[styles.tab, activeTab === 'intro' && styles.activeTab]}>\n                        <Text style={[styles.tabText, activeTab === 'intro' && styles.activeTabText]}>클래스 소개</Text>\n                    </TouchableOpacity>\n                    <TouchableOpacity onPress={() => setActiveTab('free')} style={[styles.tab, activeTab === 'free' && styles.activeTab]}>\n                        <Text style={[styles.tabText, activeTab === 'free' && styles.activeTabText]}>무료 영상</Text>\n                    </TouchableOpacity>\n                    <TouchableOpacity onPress={() => setActiveTab('mvp')} style={[styles.tab, activeTab === 'mvp' && styles.activeTab]}>\n                        <Text style={[styles.tabText, activeTab === 'mvp' && styles.activeTabText]}>MVP 영상</Text>\n                    </TouchableOpacity>\n                    <TouchableOpacity onPress={() => setActiveTab('review')} style={[styles.tab, activeTab === 'review' && styles.activeTab]}>\n                        <Text style={[styles.tabText, activeTab === 'review' && styles.activeTabText]}>리뷰</Text>\n                    </TouchableOpacity>\n                </View>\n\n                {renderTabContent()}\n            </ScrollView>\n\n            <View style={styles.bottomBar}>\n                <TouchableOpacity style={styles.bottomJoinButton} onPress={handleBottomButtonPress}>\n                    <Text style={styles.bottomJoinButtonText}>{getBottomButtonText()}</Text>\n                </TouchableOpacity>\n            </View>\n        </View>\n    );\n};\n\nconst styles = StyleSheet.create({\n    container: { flex: 1, backgroundColor: '#FBFAF4' },\n    profileHeader: {\n        padding: 20,\n        alignItems: 'center',\n        backgroundColor: '#fff',\n        borderBottomWidth: 1,\n        borderBottomColor: '#EEF0E4',\n    },\n    profileImageContainer: { marginBottom: 10 },\n    profileImage: {\n        width: 100,\n        height: 100,\n        borderRadius: 50,\n        borderWidth: 3,\n        borderColor: '#4E7D32',\n    },\n    defaultProfileImage: {\n        width: 100,\n        height: 100,\n        borderRadius: 50,\n        backgroundColor: '#C9CCB8',\n        justifyContent: 'center',\n        alignItems: 'center',\n        borderWidth: 3,\n        borderColor: '#4E7D32',\n    },\n    profileInitial: { fontSize: 40, color: '#fff', fontWeight: 'bold' },\n    profileName: { fontSize: 22, fontWeight: 'bold', color: '#2E3326', marginBottom: 8 },\n    messageButton: {\n        flexDirection: 'row',\n        alignItems: 'center',\n        paddingVertical: 5,\n        paddingHorizontal: 15,\n        borderRadius: 20,\n        backgroundColor: '#E8F2DE',\n    },\n    messageButtonText: { marginLeft: 5, color: '#4E7D32', fontWeight: '600' },\n    tabsContainer: {\n        flexDirection: 'row',\n        justifyContent: 'space-around',\n        backgroundColor: '#fff',\n        borderBottomWidth: 1,\n        borderBottomColor: '#EEF0E4',\n        paddingTop: 10,\n    },\n    tab: { paddingBottom: 10, flex: 1, alignItems: 'center' },\n    activeTab: { borderBottomWidth: 3, borderBottomColor: '#4E7D32' },\n    tabText: { fontSize: 16, color: '#7C8070', fontWeight: '500' },\n    activeTabText: { color: '#4E7D32', fontWeight: 'bold' },\n    tabContent: { padding: 15 },\n    actionButtonsContainer: {\n        flexDirection: 'row',\n        justifyContent: 'flex-end',\n        marginBottom: 15,\n        paddingHorizontal: 5,\n    },\n    actionButton: {\n        flexDirection: 'row',\n        alignItems: 'center',\n        paddingHorizontal: 12,\n        paddingVertical: 6,\n        borderRadius: 20,\n        marginLeft: 10,\n        borderWidth: 1,\n    },\n    editButton: { borderColor: '#4E7D32', backgroundColor: '#fff' },\n    editButtonText: { marginLeft: 4, color: '#4E7D32', fontWeight: '600' },\n    deleteButton: { borderColor: '#dc3545', backgroundColor: '#fff' },\n    deleteButtonText: { marginLeft: 4, color: '#dc3545', fontWeight: '600' },\n    introCard: {\n        backgroundColor: '#fff',\n        borderRadius: 10,\n        padding: 15,\n        marginBottom: 15,\n        ...Platform.select({\n            ios: { shadowColor: '#000', shadowOffset: { width: 0, height: 1 }, shadowOpacity: 0.1, shadowRadius: 2 },\n            android: { elevation: 2 },\n        }),\n    },\n    infoCard: {\n        backgroundColor: '#fff',\n        borderRadius: 10,\n        padding: 15,\n        marginBottom: 15,\n        ...Platform.select({\n            ios: { shadowColor: '#000', shadowOffset: { width: 0, height: 1 }, shadowOpacity: 0.1, shadowRadius: 2 },\n            android: { elevation: 2 },\n        }),\n    },\n    paymentCard: {\n        backgroundColor: '#fff',\n        borderRadius: 10,\n        padding: 15,\n        marginBottom: 15,\n        ...Platform.select({\n            ios: { shadowColor: '#000', shadowOffset: { width: 0, height: 1 }, shadowOpacity: 0.1, shadowRadius: 2 },\n            android: { elevation: 2 },\n        }),\n    },\n    introHeader: { flexDirection: 'row', alignItems: 'center', marginBottom: 10 },\n    cardTitle: { fontSize: 18, fontWeight: 'bold', marginLeft: 8, color: '#2E3326' },\n    bioText: { fontSize: 14, color: '#5C604F', lineHeight: 20, marginBottom: 10, paddingHorizontal: 5 },\n    divider: { height: 1, backgroundColor: '#EEF0E4', marginVertical: 10 },\n    descriptionSection: { marginTop: 10 },\n    descriptionLabel: { fontSize: 15, fontWeight: 'bold', color: '#2E3326', marginBottom: 5 },\n    descriptionText: { fontSize: 14, color: '#5C604F', lineHeight: 20 },\n    infoRow: { flexDirection: 'row', justifyContent: 'space-between', paddingVertical: 8, borderBottomWidth: 1, borderBottomColor: '#F6F5EC' },\n    infoLabel: { fontSize: 14, color: '#7C8070' },\n    infoValue: { fontSize: 14, fontWeight: '500', color: '#2E3326' },\n    paymentInfo: { marginTop: 5 },\n    noInfoCard: {\n        backgroundColor: '#fff',\n        borderRadius: 10,\n        padding: 30,\n        alignItems: 'center',\n        justifyContent: 'center',\n        marginTop: 20,\n        borderStyle: 'dashed',\n        borderWidth: 1,\n        borderColor: '#C9CCB8',\n    },\n    noInfoTitle: { fontSize: 18, fontWeight: 'bold', color: '#8E9280', marginTop: 15 },\n    noInfoSubtitle: { fontSize: 14, color: '#A3A794', marginTop: 5, textAlign: 'center' },\n    videoSection: {\n        backgroundColor: '#fff',\n        borderRadius: 10,\n        padding: 15,\n        marginBottom: 15,\n        ...Platform.select({\n            ios: { shadowColor: '#000', shadowOffset: { width: 0, height: 1 }, shadowOpacity: 0.1, shadowRadius: 2 },\n            android: { elevation: 2 },\n        }),\n    },\n    sectionHeader: { flexDirection: 'row', alignItems: 'center', marginBottom: 15 },\n    sectionTitle: { fontSize: 18, fontWeight: 'bold', marginLeft: 8, color: '#2E3326' },\n    freeBadge: {\n        marginLeft: 10,\n        backgroundColor: '#4E7D32',\n        paddingHorizontal: 8,\n        paddingVertical: 3,\n        borderRadius: 15,\n    },\n    freeBadgeText: { color: '#fff', fontSize: 12, fontWeight: 'bold' },\n    mvpBadge: {\n        marginLeft: 10,\n        backgroundColor: '#3B5A24',\n        paddingHorizontal: 8,\n        paddingVertical: 3,\n        borderRadius: 15,\n    },\n    mvpBadgeText: { color: '#fff', fontSize: 12, fontWeight: 'bold' },\n    videoCard: { flexDirection: 'row', paddingVertical: 15, borderBottomWidth: 1, borderBottomColor: '#F6F5EC' },\n    videoLeft: { marginRight: 15 },\n    videoRight: { flex: 1, justifyContent: 'space-between' },\n    videoThumbnail: {\n        width: 100,\n        height: 60,\n        borderRadius: 8,\n        backgroundColor: '#EEF0E4',\n        justifyContent: 'center',\n        alignItems: 'center',\n        overflow: 'hidden',\n    },\n    thumbnailPlaceholder: { justifyContent: 'center', alignItems: 'center', width: '100%', height: '100%' },\n    videoBadge: {\n        position: 'absolute',\n        bottom: 3,\n        right: 3,\n        backgroundColor: 'rgba(0, 0, 0, 0.6)',\n        paddingHorizontal: 5,\n        paddingVertical: 1,\n        borderRadius: 5,\n    },\n    videoBadgeText: { color: '#fff', fontSize: 10, fontWeight: 'bold' },\n    videoTitleContainer: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 5 },\n    videoTitle: { fontSize: 15, fontWeight: '600', color: '#2E3326', flex: 1, marginRight: 10 },\n    videoMetadata: { flexDirection: 'row', alignItems: 'center', marginBottom: 8 },\n    metaItem: { flexDirection: 'row', alignItems: 'center', marginRight: 15 },\n    metaText: { marginLeft: 4, fontSize: 13, color: '#7C8070' },\n    playButton: {\n        flexDirection: 'row',\n        alignItems: 'center',\n        backgroundColor: '#4E7D32',\n        paddingHorizontal: 12,\n        paddingVertical: 6,\n        borderRadius: 20,\n        alignSelf: 'flex-start',\n    },\n    playButtonText: { color: '#fff', marginLeft: 5, fontWeight: '600', fontSize: 14 },\n    purchaseButton: {\n        flexDirection: 'row',\n        alignItems: 'center',\n        backgroundColor: '#3B5A24',\n        paddingHorizontal: 12,\n        paddingVertical: 6,\n        borderRadius: 20,\n        alignSelf: 'flex-start',\n    },\n    purchaseButtonText: { color: '#fff', marginLeft: 5, fontWeight: '600', fontSize: 14 },\n    premiumOverlay: {\n        position: 'absolute',\n        top: 0,\n        left: 0,\n        right: 0,\n        bottom: 0,\n        backgroundColor: 'rgba(0, 0, 0, 0.4)',\n        justifyContent: 'center',\n        alignItems: 'center',\n        borderRadius: 8,\n    },\n    priceTag: { backgroundColor: '#ffc107', paddingHorizontal: 8, paddingVertical: 2, borderRadius: 5, marginLeft: 'auto' },\n    priceText: { fontSize: 13, fontWeight: 'bold', color: '#2E3326' },\n    videoPlaceholder: {\n        alignItems: 'center',\n        padding: 30,\n        borderWidth: 1,\n        borderColor: '#EEF0E4',\n        borderStyle: 'dashed',\n        borderRadius: 10,\n        marginTop: 10,\n    },\n    placeholderTitle: { fontSize: 16, fontWeight: 'bold', color: '#8E9280', marginTop: 10 },\n    placeholderSubtitle: { fontSize: 13, color: '#A3A794', marginTop: 5, textAlign: 'center' },\n    reviewSection: {\n        backgroundColor: '#fff',\n        borderRadius: 10,\n        padding: 15,\n        marginBottom: 15,\n        ...Platform.select({\n            ios: { shadowColor: '#000', shadowOffset: { width: 0, height: 1 }, shadowOpacity: 0.1, shadowRadius: 2 },\n            android: { elevation: 2 },\n        }),\n    },\n    ratingBadge: {\n        flexDirection: 'row',\n        alignItems: 'center',\n        marginLeft: 10,\n        backgroundColor: '#fff3cd',\n        paddingHorizontal: 8,\n        paddingVertical: 3,\n        borderRadius: 15,\n        borderWidth: 1,\n        borderColor: '#ffc107',\n    },\n    ratingBadgeText: { color: '#2E3326', fontSize: 14, fontWeight: 'bold', marginLeft: 4 },\n    reviewItem: { paddingVertical: 15, borderBottomWidth: 1, borderBottomColor: '#F6F5EC' },\n    reviewUserHeader: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: 8 },\n    reviewUserProfile: { flexDirection: 'row', alignItems: 'center' },\n    reviewUserProfileImage: { width: 30, height: 30, borderRadius: 15, marginRight: 8 },\n    reviewUserDefaultProfile: {\n        width: 30,\n        height: 30,\n        borderRadius: 15,\n        backgroundColor: '#4E7D32',\n        justifyContent: 'center',\n        alignItems: 'center',\n        marginRight: 8,\n    },\n    reviewUserInitial: { color: '#fff', fontWeight: 'bold', fontSize: 16 },\n    reviewUserNickname: { fontSize: 14, fontWeight: 'bold', color: '#2E3326' },\n    reviewRating: { flexDirection: 'row' },\n    reviewText: { fontSize: 14, color: '#5C604F', lineHeight: 20 },\n    reviewPlaceholder: { alignItems: 'center', padding: 30, marginTop: 10 },\n    bottomBar: { padding: 15, borderTopWidth: 1, borderTopColor: '#EEF0E4', backgroundColor: '#fff' },\n    bottomJoinButton: { backgroundColor: '#4E7D32', padding: 15, borderRadius: 10, alignItems: 'center' },\n    bottomJoinButtonText: { color: '#fff', fontSize: 18, fontWeight: 'bold' },\n});\n\nexport default OnlineClassMyDetail;",
    "components/OnlineClass/OnlineClassPayment.tsx": "import React, { useState, useEffect } from 'react';\nimport {\n    View,\n    Text,\n    StyleSheet,\n    SafeAreaView,\n    TouchableOpacity,\n    ScrollView,\n    Alert,\n} from 'react-native';\nimport { Ionicons } from '@expo/vector-icons';\nimport { router, useLocalSearchParams } from 'expo-router';\nimport { useOnlineClass } from '@/components/contexts/OnlineClassContext';\nimport { useAuth } from '@/components/contexts/AuthProvider';\nimport AppHeader from '@/components/AppHeader';\n\ninterface PaymentMethod {\n    id: string;\n    name: string;\n    icon: string;\n    description: string;\n}\n\nconst OnlineClassPayment = () => {\n    const {\n        currentClassData,\n        setCurrentClassData, // Context 초기화를 위해 사용\n        videos,\n        paymentInfo,\n        fees,\n        setFees,\n        addClass,\n        setPaymentComplete,\n        calculateFees,\n    } = useOnlineClass();\n    const { currentUser } = useAuth();\n    const params = useLocalSearchParams();\n    const classDataFromParams = params.classData ? JSON.parse(params.classData as string) : null;\n\n    const [selectedPaymentMethod, setSelectedPaymentMethod] = useState<string>('');\n    const [isLoading, setIsLoading] = useState(false);\n\n    const paymentMethods: PaymentMethod[] = [\n        { id: 'card', name: '신용카드', icon: 'card-outline', description: '일반 신용카드 및 체크카드' },\n        { id: 'kakaopay', name: '카카오페이', icon: 'chatbubble-outline', description: '간편하고 빠른 결제' },\n        { id: 'naverpay', name: '네이버페이', icon: 'globe-outline', description: '네이버 간편결제' },\n        { id: 'tosspay', name: '토스페이', icon: 'phone-portrait-outline', description: '토스 간편결제' },\n        { id: 'bank', name: '무통장입금', icon: 'business-outline', description: '계좌이체 및 무통장입금' },\n    ];\n\n    useEffect(() => {\n        if (!currentClassData && classDataFromParams) {\n            setCurrentClassData(classDataFromParams);\n        }\n\n        if (!currentClassData && !classDataFromParams) {\n            Alert.alert('알림', '클래스 정보가 없습니다. 이전 화면으로 돌아갑니다.', [\n                { text: '확인', onPress: () => router.back() },\n            ]);\n            return;\n        }\n\n        const calculatedFees = calculateFees();\n        if (\n            calculatedFees.uploadFee !== fees.uploadFee ||\n            calculatedFees.additionalVideoFee !== fees.additionalVideoFee ||\n            calculatedFees.total !== fees.total\n        ) {\n            setFees(calculatedFees);\n        }\n    }, [videos.length, currentClassData, classDataFromParams, setCurrentClassData, calculateFees, fees, setFees]);\n\n    const handlePayment = async () => {\n        if (!selectedPaymentMethod) {\n            Alert.alert('알림', '결제 방법을 선택해주세요.');\n            return;\n        }\n\n        const classData = currentClassData || classDataFromParams;\n        if (!classData || !currentUser) {\n            Alert.alert('오류', '클래스 또는 사용자 정보가 누락되었습니다.');\n            return;\n        }\n\n        setIsLoading(true);\n        try {\n            await new Promise(resolve => setTimeout(resolve, 2000));\n\n            const classId = classData.id || Date.now().toString();\n            const finalClassData = {\n                ...classData,\n                id: classId,\n                createdBy: currentUser.name,\n                createdAt: new Date().toISOString(),\n                paymentStatus: 'paid',\n                paymentDetails: {\n                    method: selectedPaymentMethod,\n                    amount: fees.total,\n                    bankName: paymentInfo?.bankName || 'N/A',\n                    accountNumber: paymentInfo?.accountNumber || 'N/A',\n                    accountHolder: paymentInfo?.accountHolder || 'N/A',\n                },\n            };\n\n            addClass(finalClassData);\n            setPaymentComplete(true);\n\n            // ⭐ [핵심 수정] 결제 완료 후 현재 작업 중이던 클래스 데이터를 초기화합니다.\n            setCurrentClassData(null);\n\n            Alert.alert('클래스 등록 완료', '결제가 완료되었으며, 클래스는 관리자 승인 후 공개됩니다.', [\n                {\n                    text: '확인',\n                    onPress: () => {\n                        // 홈 화면으로 이동\n                        router.replace('/');\n                    },\n                },\n            ]);\n        } catch (error) {\n            console.error('결제 오류:', error);\n            Alert.alert('오류', '결제 처리 중 문제가 발생했습니다. 다시 시도해 주세요.');\n        } finally {\n            setIsLoading(false);\n        }\n    };\n\n    const renderPaymentMethod = (method: PaymentMethod) => (\n        <TouchableOpacity\n            key={method.id}\n            style={[\n                styles.paymentMethodContainer,\n                selectedPaymentMethod === method.id && styles.selectedPaymentMethod,\n            ]}\n            onPress={() => setSelectedPaymentMethod(method.id)}\n        >\n            <View style={styles.paymentMethodContent}>\n                <Ionicons\n                    name={method.icon as any}\n                    size={24}\n                    color={selectedPaymentMethod === method.id ? '#4E7D32' : '#7C8070'}\n                />\n                <View style={styles.paymentMethodInfo}>\n                    <Text\n                        style={[\n                            styles.paymentMethodName,\n                            selectedPaymentMethod === method.id && styles.selectedPaymentMethodText,\n                        ]}\n                    >\n                        {method.name}\n                    </Text>\n                    <Text style={styles.paymentMethodDescription}>{method.description}</Text>\n                </View>\n                <View style={styles.radioButton}>\n                    {selectedPaymentMethod === method.id && (\n                        <Ionicons name=\"checkmark-circle\" size={20} color=\"#4E7D32\" />\n                    )}\n                </View>\n            </View>\n        </TouchableOpacity>\n    );\n\n    const classData = currentClassData || classDataFromParams;\n    if (!classData) {\n        return (\n            <View style={styles.container}>\n                <AppHeader title=\"결제\" />\n                <View style={styles.loadingContainer}>\n                    <Text style={{ color: '#7C8070' }}>클래스 정보를 불러오는 중...</Text>\n                </View>\n            </View>\n        );\n    }\n\n    return (\n        <View style={styles.container}>\n            {/* 공통 헤더 */}\n            <AppHeader title=\"결제\" onBack={() => { if (!isLoading) router.back(); }} />\n\n            <ScrollView style={styles.scrollContainer} showsVerticalScrollIndicator={false}>\n                <View style={styles.content}>\n                    <View style={styles.classInfoContainer}>\n                        <Text style={styles.classTitle}>{classData.title || '클래스 제목'}</Text>\n                        <Text style={styles.classInstructor}>강사: {classData.instructor || '익명'}</Text>\n                        <Text style={styles.videoCount}>등록 영상: {videos.length || 0}개</Text>\n                    </View>\n\n                    <View style={styles.paymentSummaryContainer}>\n                        <Text style={styles.sectionTitle}>결제 내역</Text>\n                        <View style={styles.feeRow}>\n                            <Text style={styles.feeLabel}>기본 업로드 요금</Text>\n                            <Text style={styles.feeValue}>{fees.uploadFee.toLocaleString()}원</Text>\n                        </View>\n                        <View style={styles.feeRow}>\n                            <Text style={styles.feeLabel}>추가 영상 요금</Text>\n                            <Text style={styles.feeValue}>{fees.additionalVideoFee.toLocaleString()}원</Text>\n                        </View>\n                        <View style={styles.feeRow}>\n                            <Text style={styles.feeLabel}>총 요금</Text>\n                            <Text style={styles.feeValue}>{fees.total.toLocaleString()}원</Text>\n                        </View>\n                    </View>\n\n                    <View style={styles.paymentMethodSection}>\n                        <Text style={styles.sectionTitle}>결제 방법</Text>\n                        {paymentMethods.map(renderPaymentMethod)}\n                    </View>\n\n                    {paymentInfo && (\n                        <View style={styles.bankInfoContainer}>\n                            <Text style={styles.sectionTitle}>입금 계좌 정보</Text>\n                            <View style={styles.feeRow}>\n                                <Text style={styles.feeLabel}>은행명</Text>\n                                <Text style={styles.feeValue}>{paymentInfo.bankName}</Text>\n                            </View>\n                            <View style={styles.feeRow}>\n                                <Text style={styles.feeLabel}>계좌번호</Text>\n                                <Text style={styles.feeValue}>{paymentInfo.accountNumber}</Text>\n                            </View>\n                            <View style={styles.feeRow}>\n                                <Text style={styles.feeLabel}>예금주</Text>\n                                <Text style={styles.feeValue}>{paymentInfo.accountHolder}</Text>\n                            </View>\n                        </View>\n                    )}\n                </View>\n            </ScrollView>\n\n            <View style={styles.bottomBar}>\n                <TouchableOpacity\n                    style={[styles.payButton, isLoading && styles.disabledButton]}\n                    onPress={handlePayment}\n                    disabled={isLoading}\n                >\n                    <Text style={styles.payButtonText}>\n                        {isLoading ? '결제 처리 중...' : `${fees.total.toLocaleString()}원 결제하기`}\n                    </Text>\n                </TouchableOpacity>\n            </View>\n        </View>\n    );\n};\n\nconst styles = StyleSheet.create({\n    container: { flex: 1, backgroundColor: '#fff' },\n    header: {\n        flexDirection: 'row',\n        justifyContent: 'space-between',\n        alignItems: 'center',\n        paddingHorizontal: 20,\n        paddingVertical: 15,\n        backgroundColor: '#fff',\n        borderBottomWidth: 1,\n        borderBottomColor: '#EEF0E4',\n    },\n    headerTitle: { fontSize: 18, fontWeight: 'bold', color: '#2E3326' },\n    scrollContainer: { flex: 1 },\n    content: { padding: 20 },\n    classInfoContainer: {\n        backgroundColor: '#FBFAF4',\n        borderRadius: 12,\n        padding: 16,\n        marginBottom: 24,\n        borderWidth: 1,\n        borderColor: '#E6E8DA',\n    },\n    classTitle: { fontSize: 18, fontWeight: 'bold', color: '#2E3326', marginBottom: 8 },\n    classInstructor: { fontSize: 14, color: '#7C8070', marginBottom: 4 },\n    videoCount: { fontSize: 14, color: '#7C8070' },\n    paymentSummaryContainer: {\n        backgroundColor: '#fff',\n        borderRadius: 12,\n        padding: 16,\n        marginBottom: 24,\n        borderWidth: 1,\n        borderColor: '#E6E8DA',\n        shadowColor: '#000',\n        shadowOffset: { width: 0, height: 2 },\n        shadowOpacity: 0.05,\n        shadowRadius: 4,\n        elevation: 2,\n    },\n    sectionTitle: { fontSize: 18, fontWeight: 'bold', color: '#2E3326', marginBottom: 16 },\n    feeRow: {\n        flexDirection: 'row',\n        justifyContent: 'space-between',\n        paddingVertical: 8,\n        borderBottomWidth: 1,\n        borderBottomColor: '#EEF0E4',\n    },\n    feeLabel: { fontSize: 14, color: '#7C8070' },\n    feeValue: { fontSize: 14, fontWeight: '500', color: '#2E3326' },\n    paymentMethodSection: {\n        backgroundColor: '#fff',\n        borderRadius: 12,\n        padding: 16,\n        marginBottom: 24,\n        borderWidth: 1,\n        borderColor: '#E6E8DA',\n        shadowColor: '#000',\n        shadowOffset: { width: 0, height: 2 },\n        shadowOpacity: 0.05,\n        shadowRadius: 4,\n        elevation: 2,\n    },\n    paymentMethodContainer: {\n        paddingVertical: 12,\n        borderBottomWidth: 1,\n        borderBottomColor: '#EEF0E4',\n    },\n    selectedPaymentMethod: { backgroundColor: '#F4F8EE' },\n    paymentMethodContent: { flexDirection: 'row', alignItems: 'center', gap: 12 },\n    paymentMethodInfo: { flex: 1 },\n    paymentMethodName: { fontSize: 16, fontWeight: '500', color: '#2E3326' },\n    selectedPaymentMethodText: { color: '#4E7D32', fontWeight: 'bold' },\n    paymentMethodDescription: { fontSize: 12, color: '#A3A794', marginTop: 4 },\n    radioButton: { width: 24, height: 24, justifyContent: 'center', alignItems: 'center' },\n    bankInfoContainer: {\n        backgroundColor: '#fff',\n        borderRadius: 12,\n        padding: 16,\n        marginBottom: 24,\n        borderWidth: 1,\n        borderColor: '#E6E8DA',\n        shadowColor: '#000',\n        shadowOffset: { width: 0, height: 2 },\n        shadowOpacity: 0.05,\n        shadowRadius: 4,\n        elevation: 2,\n    },\n    bottomBar: {\n        padding: 20,\n        backgroundColor: '#fff',\n        borderTopWidth: 1,\n        borderTopColor: '#EEF0E4',\n    },\n    payButton: {\n        backgroundColor: '#4E7D32',\n        padding: 16,\n        borderRadius: 12,\n        alignItems: 'center',\n    },\n    disabledButton: { backgroundColor: '#C9CCB8' },\n    payButtonText: { fontSize: 18, fontWeight: 'bold', color: '#fff' },\n    loadingContainer: { flex: 1, justifyContent: 'center', alignItems: 'center' },\n});\n\nexport default OnlineClassPayment;",
    "components/OnlineClass/OnlineClassPersonDetail.tsx": "import React, { useState, useEffect } from 'react';\nimport {\n    View,\n    Text,\n    StyleSheet,\n    ScrollView,\n    Image,\n    TouchableOpacity,\n    Platform,\n    Alert,\n} from 'react-native';\nimport { Ionicons } from '@expo/vector-icons';\nimport { useLocalSearchParams, useRouter } from 'expo-router';\nimport { useOnlineClass } from '@/components/contexts/OnlineClassContext';\nimport { useOnlineClassReviews } from '@/components/contexts/OnlineClassReviewContext';\nimport { useAuth } from '@/components/contexts/AuthProvider';\nimport AppHeader from '@/components/AppHeader';\n\nconst OnlineClassPersonDetail = () => {\n    const router = useRouter();\n    const { classData, videos, paymentInfo } = useOnlineClass();\n    const { reviews, addReview, fetchReviews } = useOnlineClassReviews();\n    const { currentUser } = useAuth();\n    const params = useLocalSearchParams();\n    const { id, title, instructor, profileImage, introduction: introFromParams, description: descFromParams } = params;\n\n    const [activeTab, setActiveTab] = useState('intro');\n\n    // introduction과 description 상태를 추가하여 업데이트된 값을 관리\n    const [currentIntroduction, setCurrentIntroduction] = useState(\n        (introFromParams as string) || classData?.introduction || '안녕하세요! 저는 10년 경력의 개발자로, 실무에서 바로 활용할 수 있는 실전 위주의 강의를 제공합니다. 여러분의 성장을 위해 최선을 다하겠습니다.'\n    );\n\n    const [currentDescription, setCurrentDescription] = useState(\n        (descFromParams as string) || classData?.description || '실무 중심의 체계적인 프로그래밍 교육을 통해 여러분을 전문 개발자로 성장시켜드립니다.'\n    );\n\n    const classId = id as string;\n\n    useEffect(() => {\n        if (classData?.introduction) {\n            setCurrentIntroduction(classData.introduction);\n        } else if (introFromParams) {\n            setCurrentIntroduction(introFromParams as string);\n        }\n        if (classData?.description) {\n            setCurrentDescription(classData.description);\n        } else if (descFromParams) {\n            setCurrentDescription(descFromParams as string);\n        }\n    }, [classData, introFromParams, descFromParams]);\n\n    useEffect(() => {\n        if (classId) {\n            fetchReviews(classId);\n        }\n    }, [classId, fetchReviews]);\n\n    const instructorInfo = {\n        name: instructor as string || classData?.instructor || '김개발',\n        profileImage: profileImage as string || classData?.profileImage || '',\n        bio: currentIntroduction,\n        description: currentDescription,\n    };\n\n    const classReviews = reviews[classId] || [];\n    const reviewCount = classReviews.length;\n    const averageRating = reviewCount > 0\n        ? (classReviews.reduce((sum, review) => sum + review.rating, 0) / reviewCount).toFixed(1)\n        : '0.0';\n\n    const renderStars = (starRating) => {\n        const stars = [];\n        const fullStars = Math.floor(starRating);\n        const hasHalfStar = starRating % 1 !== 0;\n\n        for (let i = 0; i < fullStars; i++) {\n            stars.push(<Ionicons key={`star-${i}`} name=\"star\" size={16} color=\"#ffc107\" />);\n        }\n        if (hasHalfStar) {\n            stars.push(<Ionicons key=\"half-star\" name=\"star-half\" size={16} color=\"#ffc107\" />);\n        }\n        const remainingStars = 5 - Math.ceil(starRating);\n        for (let i = 0; i < remainingStars; i++) {\n            stars.push(<Ionicons key={`empty-star-${i}`} name=\"star-outline\" size={16} color=\"#ffc107\" />);\n        }\n        return stars;\n    };\n\n    const renderVideoThumbnail = () => (\n        <View style={styles.videoThumbnail}>\n            <View style={styles.thumbnailPlaceholder}>\n                <Ionicons name=\"play-circle\" size={40} color=\"#4E7D32\" />\n            </View>\n            <View style={styles.videoBadge}>\n                <Text style={styles.videoBadgeText}>HD</Text>\n            </View>\n        </View>\n    );\n\n    const handleWriteReview = () => {\n        if (!currentUser) {\n            Alert.alert(\"로그인 필요\", \"리뷰를 작성하려면 로그인이 필요합니다.\");\n            return;\n        }\n        // 이미 리뷰를 작성했는지 확인 (예: currentUser.id가 review.userId와 일치하는지)\n        const hasReviewed = classReviews.some(review => review.userId === currentUser.phoneNumber);\n        if (hasReviewed) {\n            Alert.alert(\"작성 불가\", \"이미 이 클래스에 대한 리뷰를 작성했습니다.\");\n            return;\n        }\n\n        router.push({\n            pathname: '/OnlineClassWriteReview',\n            params: {\n                classId: classId,\n                classTitle: title,\n                instructorName: instructorInfo.name,\n                instructorProfileImage: instructorInfo.profileImage,\n            }\n        });\n    };\n\n    const renderTabContent = () => {\n        switch (activeTab) {\n            case 'intro':\n                return (\n                    <View style={styles.tabContent}>\n                        <View style={styles.introCard}>\n                            <View style={styles.introHeader}>\n                                <Ionicons name=\"person-circle\" size={24} color=\"#4E7D32\" />\n                                <Text style={styles.cardTitle}>강사 소개</Text>\n                            </View>\n                            <Text style={styles.bioText}>{instructorInfo.bio}</Text>\n\n                            <View style={styles.divider} />\n\n                            <View style={styles.descriptionSection}>\n                                <Text style={styles.descriptionLabel}>강의 설명</Text>\n                                <Text style={styles.descriptionText}>{instructorInfo.description}</Text>\n                            </View>\n                        </View>\n\n                        <View style={styles.infoCard}>\n                            <View style={styles.introHeader}>\n                                <Ionicons name=\"book\" size={24} color=\"#4E7D32\" />\n                                <Text style={styles.cardTitle}>강의 정보</Text>\n                            </View>\n                            <View style={styles.infoRow}>\n                                <Text style={styles.infoLabel}>강의명</Text>\n                                <Text style={styles.infoValue}>{title || '강의명 정보 없음'}</Text>\n                            </View>\n                            <View style={styles.infoRow}>\n                                <Text style={styles.infoLabel}>강사</Text>\n                                <Text style={styles.infoValue}>{instructorInfo.name}</Text>\n                            </View>\n                        </View>\n                        {paymentInfo && (\n                            <View style={styles.paymentCard}>\n                                <View style={styles.introHeader}>\n                                    <Ionicons name=\"card\" size={24} color=\"#ffc107\" />\n                                    <Text style={styles.cardTitle}>결제 정보</Text>\n                                </View>\n                                <View style={styles.paymentInfo}>\n                                    <View style={styles.infoRow}>\n                                        <Text style={styles.infoLabel}>은행명</Text>\n                                        <Text style={styles.infoValue}>{paymentInfo.bankName}</Text>\n                                    </View>\n                                    <View style={styles.infoRow}>\n                                        <Text style={styles.infoLabel}>계좌번호</Text>\n                                        <Text style={styles.infoValue}>{paymentInfo.accountNumber}</Text>\n                                    </View>\n                                    <View style={styles.infoRow}>\n                                        <Text style={styles.infoLabel}>예금주</Text>\n                                        <Text style={styles.infoValue}>{paymentInfo.accountHolder}</Text>\n                                    </View>\n                                </View>\n                            </View>\n                        )}\n                    </View>\n                );\n            case 'free':\n                return (\n                    <View style={styles.tabContent}>\n                        <View style={styles.videoSection}>\n                            <View style={styles.sectionHeader}>\n                                <Ionicons name=\"videocam\" size={24} color=\"#4E7D32\" />\n                                <Text style={styles.sectionTitle}>무료 영상</Text>\n                                <View style={styles.freeBadge}>\n                                    <Text style={styles.freeBadgeText}>FREE</Text>\n                                </View>\n                            </View>\n                            {videos.length > 0 ? (\n                                videos\n                                    .filter(video => video.type === 'free')\n                                    .map(video => (\n                                        <View key={video.id} style={styles.videoCard}>\n                                            <View style={styles.videoLeft}>\n                                                {renderVideoThumbnail()}\n                                            </View>\n                                            <View style={styles.videoRight}>\n                                                <Text style={styles.videoTitle}>{video.videoTitle}</Text>\n                                                <View style={styles.videoMetadata}>\n                                                    <View style={styles.metaItem}>\n                                                        <Ionicons name=\"time-outline\" size={16} color=\"#7C8070\" />\n                                                        <Text style={styles.metaText}>{video.duration}</Text>\n                                                    </View>\n                                                    <View style={styles.metaItem}>\n                                                        <Ionicons name=\"bar-chart-outline\" size={16} color=\"#7C8070\" />\n                                                        <Text style={styles.metaText}>{video.level}</Text>\n                                                    </View>\n                                                </View>\n                                                <TouchableOpacity style={styles.playButton}>\n                                                    <Ionicons name=\"play\" size={16} color=\"#fff\" />\n                                                    <Text style={styles.playButtonText}>재생</Text>\n                                                </TouchableOpacity>\n                                            </View>\n                                        </View>\n                                    ))\n                            ) : (\n                                <View style={styles.videoPlaceholder}>\n                                    <Ionicons name=\"videocam-outline\" size={50} color=\"#C9CCB8\" />\n                                    <Text style={styles.placeholderTitle}>무료 영상 준비 중</Text>\n                                    <Text style={styles.placeholderSubtitle}>곧 흥미로운 콘텐츠가 업데이트됩니다!</Text>\n                                </View>\n                            )}\n                        </View>\n                    </View>\n                );\n            case 'mvp':\n                return (\n                    <View style={styles.tabContent}>\n                        <View style={styles.videoSection}>\n                            <View style={styles.sectionHeader}>\n                                <Ionicons name=\"diamond\" size={24} color=\"#3B5A24\" />\n                                <Text style={styles.sectionTitle}>MVP 영상</Text>\n                                <View style={styles.mvpBadge}>\n                                    <Text style={styles.mvpBadgeText}>PREMIUM</Text>\n                                </View>\n                            </View>\n                            {videos.length > 0 ? (\n                                videos\n                                    .filter(video => video.type === 'mvp')\n                                    .map(video => (\n                                        <View key={video.id} style={styles.videoCard}>\n                                            <View style={styles.videoLeft}>\n                                                {renderVideoThumbnail()}\n                                                <View style={styles.premiumOverlay}>\n                                                    <Ionicons name=\"lock-closed\" size={20} color=\"#fff\" />\n                                                </View>\n                                            </View>\n                                            <View style={styles.videoRight}>\n                                                <Text style={styles.videoTitle}>{video.videoTitle}</Text>\n                                                <View style={styles.videoMetadata}>\n                                                    <View style={styles.metaItem}>\n                                                        <Ionicons name=\"time-outline\" size={16} color=\"#7C8070\" />\n                                                        <Text style={styles.metaText}>{video.duration}</Text>\n                                                    </View>\n                                                    <View style={styles.metaItem}>\n                                                        <Ionicons name=\"bar-chart-outline\" size={16} color=\"#7C8070\" />\n                                                        <Text style={styles.metaText}>{video.level}</Text>\n                                                    </View>\n                                                    <View style={styles.priceTag}>\n                                                        <Text style={styles.priceText}>{video.price || 0}원</Text>\n                                                    </View>\n                                                </View>\n                                                <TouchableOpacity style={styles.purchaseButton}>\n                                                    <Ionicons name=\"diamond\" size={16} color=\"#fff\" />\n                                                    <Text style={styles.purchaseButtonText}>구매</Text>\n                                                </TouchableOpacity>\n                                            </View>\n                                        </View>\n                                    ))\n                            ) : (\n                                <View style={styles.videoPlaceholder}>\n                                    <Ionicons name=\"diamond-outline\" size={50} color=\"#C9CCB8\" />\n                                    <Text style={styles.placeholderTitle}>MVP 영상 준비 중</Text>\n                                    <Text style={styles.placeholderSubtitle}>프리미엄 콘텐츠가 곧 출시됩니다!</Text>\n                                </View>\n                            )}\n                        </View>\n                    </View>\n                );\n            case 'review':\n                return (\n                    <View style={styles.tabContent}>\n                        <View style={styles.reviewSection}>\n                            <View style={styles.sectionHeader}>\n                                <Ionicons name=\"chatbubbles\" size={24} color=\"#ff6b6b\" />\n                                <Text style={styles.sectionTitle}>리뷰 ({reviewCount}개)</Text>\n                                <View style={styles.ratingBadge}>\n                                    <Ionicons name=\"star\" size={16} color=\"#ffc107\" />\n                                    <Text style={styles.ratingBadgeText}>{averageRating}</Text>\n                                </View>\n                            </View>\n\n                            <TouchableOpacity style={styles.writeReviewButton} onPress={handleWriteReview}>\n                                <Ionicons name=\"create\" size={20} color=\"#fff\" />\n                                <Text style={styles.writeReviewButtonText}>리뷰 작성하기</Text>\n                            </TouchableOpacity>\n\n                            {classReviews.length > 0 ? (\n                                classReviews.map((review, index) => (\n                                    <View key={index} style={styles.reviewItem}>\n                                        <View style={styles.reviewUserHeader}>\n                                            <View style={styles.reviewUserProfile}>\n                                                {review.userProfileImage ? (\n                                                    <Image source={{ uri: review.userProfileImage }} style={styles.reviewUserProfileImage} />\n                                                ) : (\n                                                    <View style={styles.reviewUserDefaultProfile}>\n                                                        <Text style={styles.reviewUserInitial}>{review.userNickname?.[0] || 'U'}</Text>\n                                                    </View>\n                                                )}\n                                                <Text style={styles.reviewUserNickname}>{review.userNickname}</Text>\n                                            </View>\n                                            <View style={styles.reviewRating}>\n                                                {renderStars(review.rating)}\n                                            </View>\n                                        </View>\n                                        <Text style={styles.reviewText}>{review.reviewText}</Text>\n                                    </View>\n                                ))\n                            ) : (\n                                <View style={styles.reviewPlaceholder}>\n                                    <Ionicons name=\"chatbubbles-outline\" size={50} color=\"#C9CCB8\" />\n                                    <Text style={styles.placeholderTitle}>아직 작성된 리뷰가 없어요!</Text>\n                                    <Text style={styles.placeholderSubtitle}>첫 번째 리뷰를 남겨주세요</Text>\n                                </View>\n                            )}\n                        </View>\n                    </View>\n                );\n            default:\n                return null;\n        }\n    };\n\n    const handleSendMessage = () => {\n        Alert.alert(`${instructorInfo.name} 강사`, \"메시지 보내기 기능은 개발 예정입니다.\");\n    };\n\n    return (\n        <View style={styles.container}>\n            {/* 공통 헤더 */}\n            <AppHeader title=\"강사 정보\" />\n            <ScrollView showsVerticalScrollIndicator={false}>\n                <View style={styles.profileHeader}>\n                    <View style={styles.profileImageContainer}>\n                        {instructorInfo.profileImage ? (\n                            <Image source={{ uri: instructorInfo.profileImage }} style={styles.profileImage} />\n                        ) : (\n                            <View style={styles.defaultProfileImage}>\n                                <Text style={styles.profileInitial}>{instructorInfo.name[0]}</Text>\n                            </View>\n                        )}\n                    </View>\n                    <Text style={styles.profileName}>{instructorInfo.name}</Text>\n                    <TouchableOpacity style={styles.messageButton} onPress={handleSendMessage}>\n                        <Ionicons name=\"chatbubble-ellipses-outline\" size={20} color=\"#4E7D32\" />\n                        <Text style={styles.messageButtonText}>메시지 보내기</Text>\n                    </TouchableOpacity>\n                </View>\n\n                <View style={styles.tabsContainer}>\n                    <TouchableOpacity onPress={() => setActiveTab('intro')} style={[styles.tab, activeTab === 'intro' && styles.activeTab]}>\n                        <Text style={[styles.tabText, activeTab === 'intro' && styles.activeTabText]}>클래스 소개</Text>\n                    </TouchableOpacity>\n                    <TouchableOpacity onPress={() => setActiveTab('free')} style={[styles.tab, activeTab === 'free' && styles.activeTab]}>\n                        <Text style={[styles.tabText, activeTab === 'free' && styles.activeTabText]}>무료 영상</Text>\n                    </TouchableOpacity>\n                    <TouchableOpacity onPress={() => setActiveTab('mvp')} style={[styles.tab, activeTab === 'mvp' && styles.activeTab]}>\n                        <Text style={[styles.tabText, activeTab === 'mvp' && styles.activeTabText]}>MVP 영상</Text>\n                    </TouchableOpacity>\n                    <TouchableOpacity onPress={() => setActiveTab('review')} style={[styles.tab, activeTab === 'review' && styles.activeTab]}>\n                        <Text style={[styles.tabText, activeTab === 'review' && styles.activeTabText]}>리뷰</Text>\n                    </TouchableOpacity>\n                </View>\n\n                {renderTabContent()}\n            </ScrollView>\n        </View>\n    );\n};\n\nconst styles = StyleSheet.create({\n    container: {\n        flex: 1,\n        backgroundColor: '#FBFAF4',\n    },\n    profileHeader: {\n        paddingTop: 20,\n        alignItems: 'center',\n        backgroundColor: '#fff',\n        paddingVertical: 20,\n        borderBottomLeftRadius: 30,\n        borderBottomRightRadius: 30,\n        marginBottom: 10,\n        shadowColor: '#000',\n        shadowOffset: { width: 0, height: 2 },\n        shadowOpacity: 0.1,\n        shadowRadius: 5,\n        elevation: 5,\n    },\n    backButton: {\n        position: 'absolute',\n        top: 40,\n        left: 20,\n        zIndex: 10,\n    },\n    profileImageContainer: {\n        width: 100,\n        height: 100,\n        borderRadius: 50,\n        backgroundColor: '#EEF0E4',\n        justifyContent: 'center',\n        alignItems: 'center',\n        borderWidth: 2,\n        borderColor: '#fff',\n        marginBottom: 10,\n        shadowColor: '#000',\n        shadowOffset: { width: 0, height: 1 },\n        shadowOpacity: 0.2,\n        shadowRadius: 2,\n        elevation: 3,\n    },\n    profileImage: {\n        width: '100%',\n        height: '100%',\n        borderRadius: 50,\n    },\n    defaultProfileImage: {\n        width: '100%',\n        height: '100%',\n        borderRadius: 50,\n        justifyContent: 'center',\n        alignItems: 'center',\n        backgroundColor: '#4E7D32',\n    },\n    profileInitial: {\n        fontSize: 40,\n        fontWeight: 'bold',\n        color: '#fff',\n    },\n    profileName: {\n        fontSize: 22,\n        fontWeight: 'bold',\n        color: '#2E3326',\n        marginBottom: 5,\n    },\n    messageButton: {\n        flexDirection: 'row',\n        alignItems: 'center',\n        backgroundColor: '#E8F2DE',\n        paddingHorizontal: 15,\n        paddingVertical: 8,\n        borderRadius: 20,\n        gap: 5,\n        marginTop: 5,\n    },\n    messageButtonText: {\n        fontSize: 14,\n        fontWeight: '600',\n        color: '#4E7D32',\n    },\n    tabsContainer: {\n        flexDirection: 'row',\n        justifyContent: 'space-around',\n        backgroundColor: '#fff',\n        borderRadius: 25,\n        margin: 10,\n        padding: 5,\n        shadowColor: '#000',\n        shadowOffset: { width: 0, height: 1 },\n        shadowOpacity: 0.1,\n        shadowRadius: 2,\n        elevation: 2,\n    },\n    tab: {\n        flex: 1,\n        alignItems: 'center',\n        paddingVertical: 12,\n        borderRadius: 20,\n    },\n    activeTab: {\n        backgroundColor: '#4E7D32',\n    },\n    tabText: {\n        fontSize: 14,\n        fontWeight: '600',\n        color: '#7C8070',\n    },\n    activeTabText: {\n        color: '#fff',\n    },\n    tabContent: {\n        padding: 10,\n    },\n    introCard: {\n        backgroundColor: '#fff',\n        borderRadius: 15,\n        padding: 20,\n        marginBottom: 10,\n        shadowColor: '#000',\n        shadowOffset: { width: 0, height: 2 },\n        shadowOpacity: 0.1,\n        shadowRadius: 4,\n        elevation: 3,\n    },\n    infoCard: {\n        backgroundColor: '#fff',\n        borderRadius: 15,\n        padding: 20,\n        marginBottom: 10,\n        shadowColor: '#000',\n        shadowOffset: { width: 0, height: 2 },\n        shadowOpacity: 0.1,\n        shadowRadius: 4,\n        elevation: 3,\n    },\n    paymentCard: {\n        backgroundColor: '#fff',\n        borderRadius: 15,\n        padding: 20,\n        marginBottom: 10,\n        shadowColor: '#000',\n        shadowOffset: { width: 0, height: 2 },\n        shadowOpacity: 0.1,\n        shadowRadius: 4,\n        elevation: 3,\n    },\n    introHeader: {\n        flexDirection: 'row',\n        alignItems: 'center',\n        gap: 10,\n        marginBottom: 15,\n    },\n    cardTitle: {\n        fontSize: 18,\n        fontWeight: 'bold',\n        color: '#2E3326',\n    },\n    bioText: {\n        fontSize: 15,\n        lineHeight: 22,\n        color: '#5C604F',\n    },\n    divider: {\n        height: 1,\n        backgroundColor: '#EEF0E4',\n        marginVertical: 20,\n    },\n    descriptionSection: {\n        marginTop: 10,\n    },\n    descriptionLabel: {\n        fontSize: 16,\n        fontWeight: '600',\n        color: '#2E3326',\n        marginBottom: 8,\n    },\n    descriptionText: {\n        fontSize: 15,\n        lineHeight: 22,\n        color: '#7C8070',\n        fontStyle: 'italic',\n    },\n    infoRow: {\n        flexDirection: 'row',\n        justifyContent: 'space-between',\n        alignItems: 'center',\n        paddingVertical: 8,\n        borderBottomWidth: 1,\n        borderBottomColor: '#EEF0E4',\n    },\n    infoLabel: {\n        fontSize: 15,\n        fontWeight: '500',\n        color: '#7C8070',\n    },\n    infoValue: {\n        fontSize: 15,\n        color: '#2E3326',\n        flexShrink: 1,\n        marginLeft: 10,\n    },\n    paymentInfo: {\n        marginTop: 10,\n    },\n    videoSection: {\n        backgroundColor: '#fff',\n        borderRadius: 15,\n        padding: 20,\n        marginBottom: 10,\n        shadowColor: '#000',\n        shadowOffset: { width: 0, height: 2 },\n        shadowOpacity: 0.1,\n        shadowRadius: 4,\n        elevation: 3,\n    },\n    sectionHeader: {\n        flexDirection: 'row',\n        alignItems: 'center',\n        gap: 10,\n        marginBottom: 15,\n    },\n    sectionTitle: {\n        fontSize: 18,\n        fontWeight: 'bold',\n        color: '#2E3326',\n    },\n    freeBadge: {\n        backgroundColor: '#4E7D32',\n        paddingHorizontal: 8,\n        paddingVertical: 2,\n        borderRadius: 10,\n    },\n    freeBadgeText: {\n        fontSize: 12,\n        color: '#fff',\n        fontWeight: 'bold',\n    },\n    mvpBadge: {\n        backgroundColor: '#3B5A24',\n        paddingHorizontal: 8,\n        paddingVertical: 2,\n        borderRadius: 10,\n    },\n    mvpBadgeText: {\n        fontSize: 12,\n        color: '#fff',\n        fontWeight: 'bold',\n    },\n    videoCard: {\n        flexDirection: 'row',\n        backgroundColor: '#FBFAF4',\n        borderRadius: 10,\n        overflow: 'hidden',\n        marginBottom: 15,\n    },\n    videoLeft: {\n        width: '40%',\n        aspectRatio: 16 / 9,\n        position: 'relative',\n    },\n    videoThumbnail: {\n        width: '100%',\n        height: '100%',\n        justifyContent: 'center',\n        alignItems: 'center',\n        backgroundColor: '#EEF0E4',\n    },\n    thumbnailPlaceholder: {\n        position: 'absolute',\n    },\n    videoBadge: {\n        position: 'absolute',\n        bottom: 5,\n        right: 5,\n        backgroundColor: 'rgba(0,0,0,0.5)',\n        paddingHorizontal: 6,\n        paddingVertical: 2,\n        borderRadius: 5,\n    },\n    videoBadgeText: {\n        color: '#fff',\n        fontSize: 10,\n    },\n    videoRight: {\n        flex: 1,\n        padding: 10,\n        justifyContent: 'space-between',\n    },\n    videoTitle: {\n        fontSize: 16,\n        fontWeight: '600',\n        color: '#2E3326',\n        marginBottom: 5,\n    },\n    videoMetadata: {\n        flexDirection: 'row',\n        alignItems: 'center',\n        gap: 10,\n        marginBottom: 5,\n    },\n    metaItem: {\n        flexDirection: 'row',\n        alignItems: 'center',\n        gap: 4,\n    },\n    metaText: {\n        fontSize: 12,\n        color: '#7C8070',\n    },\n    playButton: {\n        flexDirection: 'row',\n        backgroundColor: '#4E7D32',\n        paddingHorizontal: 12,\n        paddingVertical: 6,\n        borderRadius: 20,\n        alignItems: 'center',\n        justifyContent: 'center',\n        gap: 5,\n    },\n    playButtonText: {\n        color: '#fff',\n        fontSize: 14,\n        fontWeight: 'bold',\n    },\n    premiumOverlay: {\n        ...StyleSheet.absoluteFill,\n        backgroundColor: 'rgba(0,0,0,0.6)',\n        justifyContent: 'center',\n        alignItems: 'center',\n    },\n    priceTag: {\n        marginLeft: 'auto',\n        backgroundColor: '#ffc107',\n        paddingHorizontal: 8,\n        paddingVertical: 4,\n        borderRadius: 10,\n    },\n    priceText: {\n        fontSize: 12,\n        fontWeight: 'bold',\n        color: '#fff',\n    },\n    purchaseButton: {\n        flexDirection: 'row',\n        backgroundColor: '#3B5A24',\n        paddingHorizontal: 12,\n        paddingVertical: 6,\n        borderRadius: 20,\n        alignItems: 'center',\n        justifyContent: 'center',\n        gap: 5,\n    },\n    purchaseButtonText: {\n        color: '#fff',\n        fontSize: 14,\n        fontWeight: 'bold',\n    },\n    videoPlaceholder: {\n        alignItems: 'center',\n        padding: 20,\n        backgroundColor: '#fff',\n        borderRadius: 15,\n    },\n    placeholderTitle: {\n        fontSize: 16,\n        fontWeight: 'bold',\n        color: '#A3A794',\n        marginTop: 10,\n    },\n    placeholderSubtitle: {\n        fontSize: 14,\n        color: '#7C8070',\n        marginTop: 5,\n        textAlign: 'center',\n    },\n    reviewSection: {\n        backgroundColor: '#fff',\n        borderRadius: 15,\n        padding: 20,\n        ...Platform.select({\n            ios: {\n                shadowColor: '#000',\n                shadowOffset: { width: 0, height: 1 },\n                shadowOpacity: 0.1,\n                shadowRadius: 2,\n            },\n            android: {\n                elevation: 3,\n            },\n        }),\n    },\n    ratingBadge: {\n        flexDirection: 'row',\n        alignItems: 'center',\n        backgroundColor: '#fff3cd',\n        paddingHorizontal: 8,\n        paddingVertical: 2,\n        borderRadius: 10,\n        marginLeft: 'auto',\n        borderWidth: 1,\n        borderColor: '#ffc107',\n    },\n    ratingBadgeText: {\n        fontSize: 12,\n        fontWeight: 'bold',\n        color: '#ffc107',\n        marginLeft: 4,\n    },\n    writeReviewButton: {\n        flexDirection: 'row',\n        alignItems: 'center',\n        justifyContent: 'center',\n        backgroundColor: '#4E7D32',\n        paddingVertical: 12,\n        borderRadius: 10,\n        marginBottom: 15,\n        gap: 5,\n    },\n    writeReviewButtonText: {\n        color: '#fff',\n        fontSize: 16,\n        fontWeight: 'bold',\n    },\n    reviewPlaceholder: {\n        alignItems: 'center',\n        paddingVertical: 30,\n    },\n    reviewItem: {\n        backgroundColor: '#FBFAF4',\n        padding: 15,\n        borderRadius: 10,\n        marginBottom: 10,\n    },\n    reviewUserHeader: {\n        flexDirection: 'row',\n        justifyContent: 'space-between',\n        alignItems: 'center',\n        marginBottom: 10,\n    },\n    reviewUserProfile: {\n        flexDirection: 'row',\n        alignItems: 'center',\n    },\n    reviewUserProfileImage: {\n        width: 32,\n        height: 32,\n        borderRadius: 16,\n        marginRight: 8,\n    },\n    reviewUserDefaultProfile: {\n        width: 32,\n        height: 32,\n        borderRadius: 16,\n        backgroundColor: '#A3A794',\n        justifyContent: 'center',\n        alignItems: 'center',\n        marginRight: 8,\n    },\n    reviewUserInitial: {\n        fontSize: 16,\n        fontWeight: 'bold',\n        color: '#fff',\n    },\n    reviewUserNickname: {\n        fontSize: 15,\n        fontWeight: '600',\n        color: '#2E3326',\n    },\n    reviewRating: {\n        flexDirection: 'row',\n    },\n    reviewText: {\n        fontSize: 15,\n        lineHeight: 22,\n        color: '#5C604F',\n    },\n});\n\nexport default OnlineClassPersonDetail;",
    "components/Reviews/OnlineClassWriteReview.tsx": "import React, { useState } from 'react';\nimport {\n    View,\n    Text,\n    StyleSheet,\n    TextInput,\n    TouchableOpacity,\n    ScrollView,\n    Alert,\n    Image,\n    Platform,\n    KeyboardAvoidingView,\n    ActivityIndicator,\n} from 'react-native';\nimport { Ionicons } from '@expo/vector-icons';\nimport { useRouter, useLocalSearchParams } from 'expo-router';\nimport { useAuth } from '@/components/contexts/AuthProvider';\nimport { useOnlineClassReviews } from '@/components/contexts/OnlineClassReviewContext';\nimport AppHeader from '@/components/AppHeader';\n\nconst OnlineClassWriteReview = () => {\n    const router = useRouter();\n    const params = useLocalSearchParams();\n    const { classId, classTitle, instructorName, instructorProfileImage } = params;\n\n    const { currentUser } = useAuth();\n    const { addReview } = useOnlineClassReviews();\n\n    const [rating, setRating] = useState(0);\n    const [reviewText, setReviewText] = useState('');\n    const [isSubmitting, setIsSubmitting] = useState(false);\n\n    const handleStarPress = (starRating) => {\n        setRating(starRating);\n    };\n\n    const renderStars = () => {\n        const stars = [];\n        for (let i = 1; i <= 5; i++) {\n            stars.push(\n                <TouchableOpacity\n                    key={i}\n                    onPress={() => handleStarPress(i)}\n                    style={styles.starButton}\n                >\n                    <Ionicons\n                        name={i <= rating ? \"star\" : \"star-outline\"}\n                        size={32}\n                        color={i <= rating ? \"#ffc107\" : \"#E6E8DA\"}\n                    />\n                </TouchableOpacity>\n            );\n        }\n        return stars;\n    };\n\n    const getRatingText = () => {\n        switch (rating) {\n            case 1: return \"별로예요\";\n            case 2: return \"아쉬워요\";\n            case 3: return \"보통이에요\";\n            case 4: return \"좋아요\";\n            case 5: return \"최고예요\";\n            default: return \"별점을 선택해주세요\";\n        }\n    };\n\n    const handleSubmit = async () => {\n        if (rating === 0) {\n            Alert.alert('알림', '별점을 선택해주세요.');\n            return;\n        }\n\n        if (reviewText.trim().length < 10) {\n            Alert.alert('알림', '리뷰는 최소 10자 이상 작성해주세요.');\n            return;\n        }\n\n        if (!currentUser) {\n            Alert.alert('알림', '로그인이 필요합니다.');\n            return;\n        }\n\n        setIsSubmitting(true);\n\n        try {\n            // 새 리뷰 객체 생성\n            const newReview = {\n                id: Date.now().toString(), // 고유 ID 생성 (임시)\n                userId: currentUser.phoneNumber,\n                userNickname: currentUser.nickname,\n                userProfileImage: currentUser.profileImage,\n                rating,\n                reviewText: reviewText.trim(),\n                date: new Date().toISOString(),\n            };\n\n            // `OnlineClassReviewContext`의 `addReview` 함수 호출\n            await addReview(classId, newReview);\n\n            setIsSubmitting(false);\n            Alert.alert(\n                '리뷰 작성 완료',\n                '소중한 리뷰를 남겨주셔서 감사합니다!',\n                [\n                    {\n                        text: '확인',\n                        onPress: () => {\n                            // 리뷰 작성 후 이전 화면으로 돌아가기\n                            router.back();\n                        },\n                    },\n                ]\n            );\n        } catch (error) {\n            setIsSubmitting(false);\n            console.error('리뷰 작성 중 오류 발생:', error);\n            Alert.alert('오류', '리뷰 작성 중 오류가 발생했습니다. 다시 시도해주세요.');\n        }\n    };\n\n    return (\n        <KeyboardAvoidingView\n            style={styles.container}\n            behavior={Platform.OS === 'ios' ? 'padding' : 'height'}\n        >\n            {/* 공통 헤더 */}\n            <AppHeader title=\"리뷰 작성\" />\n\n            <ScrollView showsVerticalScrollIndicator={false} contentContainerStyle={styles.scrollContent}>\n                {currentUser && (\n                    <View style={styles.userProfileCard}>\n                        <View style={styles.userProfileImageContainer}>\n                            {currentUser.profileImage ? (\n                                <Image source={{ uri: currentUser.profileImage }} style={styles.userProfileImage} />\n                            ) : (\n                                <View style={styles.defaultProfileImage}>\n                                    <Text style={styles.userInitial}>\n                                        {currentUser.nickname?.[0] || 'U'}\n                                    </Text>\n                                </View>\n                            )}\n                        </View>\n                        <View>\n                            <Text style={styles.userNickname}>{currentUser.nickname || '사용자'}</Text>\n                        </View>\n                    </View>\n                )}\n\n                <View style={styles.classInfoCard}>\n                    <View style={styles.classInfoHeader}>\n                        <View style={styles.instructorImageContainer}>\n                            {instructorProfileImage ? (\n                                <Image source={{ uri: instructorProfileImage }} style={styles.instructorImage} />\n                            ) : (\n                                <View style={styles.defaultInstructorImage}>\n                                    <Text style={styles.instructorInitial}>\n                                        {instructorName?.[0] || 'T'}\n                                    </Text>\n                                </View>\n                            )}\n                        </View>\n                        <View style={styles.classInfo}>\n                            <Text style={styles.className} numberOfLines={2}>\n                                {classTitle || '클래스명'}\n                            </Text>\n                            <Text style={styles.instructorNameText}>\n                                {instructorName || '강사명'}\n                            </Text>\n                        </View>\n                    </View>\n                </View>\n\n                <View style={styles.ratingSection}>\n                    <Text style={styles.sectionTitle}>이 클래스는 어떠셨나요?</Text>\n                    <View style={styles.starsContainer}>\n                        {renderStars()}\n                    </View>\n                    <Text style={[styles.ratingText, rating > 0 && styles.ratedText]}>{getRatingText()}</Text>\n                </View>\n\n                <View style={styles.reviewSection}>\n                    <Text style={styles.sectionTitle}>리뷰를 작성해주세요</Text>\n                    <TextInput\n                        style={styles.reviewTextInput}\n                        multiline\n                        placeholder=\"클래스에 대한 솔직한 후기를 남겨주세요.&#10;다른 학습자들에게 큰 도움이 됩니다.\"\n                        value={reviewText}\n                        onChangeText={setReviewText}\n                        maxLength={500}\n                        textAlignVertical=\"top\"\n                    />\n                    <Text style={styles.characterCount}>\n                        {reviewText.length}/500자\n                    </Text>\n                </View>\n\n                <View style={styles.guidelineSection}>\n                    <Text style={styles.guidelineTitle}>리뷰 작성 가이드라인</Text>\n                    <View style={styles.guidelineItem}>\n                        <Ionicons name=\"checkmark-circle\" size={16} color=\"#4E7D32\" />\n                        <Text style={styles.guidelineText}>클래스 내용과 품질에 대해 솔직하게 작성해주세요</Text>\n                    </View>\n                    <View style={styles.guidelineItem}>\n                        <Ionicons name=\"checkmark-circle\" size={16} color=\"#4E7D32\" />\n                        <Text style={styles.guidelineText}>구체적인 경험과 느낀 점을 공유해주세요</Text>\n                    </View>\n                    <View style={styles.guidelineItem}>\n                        <Ionicons name=\"close-circle\" size={16} color=\"#dc3545\" />\n                        <Text style={styles.guidelineText}>욕설이나 부적절한 내용은 삼가해주세요</Text>\n                    </View>\n                </View>\n            </ScrollView>\n\n            <View style={styles.submitContainer}>\n                <TouchableOpacity\n                    style={[\n                        styles.submitButton,\n                        (rating === 0 || reviewText.trim().length < 10 || isSubmitting) && styles.submitButtonDisabled\n                    ]}\n                    onPress={handleSubmit}\n                    disabled={rating === 0 || reviewText.trim().length < 10 || isSubmitting}\n                >\n                    {isSubmitting ? (\n                        <View style={styles.loadingContainer}>\n                            <ActivityIndicator size=\"small\" color=\"#fff\" />\n                            <Text style={styles.submitButtonText}>작성 중...</Text>\n                        </View>\n                    ) : (\n                        <>\n                            <Ionicons name=\"send\" size={20} color=\"#fff\" />\n                            <Text style={styles.submitButtonText}>리뷰 작성 완료</Text>\n                        </>\n                    )}\n                </TouchableOpacity>\n            </View>\n        </KeyboardAvoidingView>\n    );\n};\n\nconst styles = StyleSheet.create({\n    container: {\n        flex: 1,\n        backgroundColor: '#FBFAF4',\n    },\n    header: {\n        flexDirection: 'row',\n        alignItems: 'center',\n        justifyContent: 'space-between',\n        paddingTop: 60,\n        paddingHorizontal: 20,\n        paddingBottom: 20,\n        backgroundColor: '#fff',\n        borderBottomWidth: 1,\n        borderBottomColor: '#EEF0E4',\n    },\n    backButton: {\n        padding: 5,\n    },\n    headerTitle: {\n        fontSize: 18,\n        fontWeight: 'bold',\n        color: '#2E3326',\n    },\n    placeholder: {\n        width: 34,\n    },\n    scrollContent: {\n        padding: 20,\n        paddingBottom: 100,\n    },\n    userProfileCard: {\n        flexDirection: 'row',\n        alignItems: 'center',\n        backgroundColor: '#fff',\n        borderRadius: 15,\n        padding: 15,\n        marginBottom: 20,\n        shadowColor: '#000',\n        shadowOffset: { width: 0, height: 2 },\n        shadowOpacity: 0.1,\n        shadowRadius: 4,\n        elevation: 3,\n    },\n    userProfileImageContainer: {\n        width: 48,\n        height: 48,\n        borderRadius: 24,\n        marginRight: 15,\n        overflow: 'hidden',\n        borderWidth: 1,\n        borderColor: '#EEF0E4',\n    },\n    userProfileImage: {\n        width: '100%',\n        height: '100%',\n    },\n    defaultProfileImage: {\n        width: '100%',\n        height: '100%',\n        borderRadius: 24,\n        backgroundColor: '#A3A794',\n        justifyContent: 'center',\n        alignItems: 'center',\n    },\n    userInitial: {\n        fontSize: 20,\n        fontWeight: 'bold',\n        color: '#fff',\n    },\n    userNickname: {\n        fontSize: 16,\n        fontWeight: 'bold',\n        color: '#2E3326',\n    },\n    classInfoCard: {\n        backgroundColor: '#fff',\n        borderRadius: 15,\n        padding: 20,\n        marginBottom: 20,\n        shadowColor: '#000',\n        shadowOffset: { width: 0, height: 2 },\n        shadowOpacity: 0.1,\n        shadowRadius: 4,\n        elevation: 3,\n    },\n    classInfoHeader: {\n        flexDirection: 'row',\n        alignItems: 'center',\n    },\n    instructorImageContainer: {\n        width: 60,\n        height: 60,\n        borderRadius: 30,\n        marginRight: 15,\n    },\n    instructorImage: {\n        width: '100%',\n        height: '100%',\n        borderRadius: 30,\n    },\n    defaultInstructorImage: {\n        width: '100%',\n        height: '100%',\n        borderRadius: 30,\n        backgroundColor: '#4E7D32',\n        justifyContent: 'center',\n        alignItems: 'center',\n    },\n    instructorInitial: {\n        fontSize: 24,\n        fontWeight: 'bold',\n        color: '#fff',\n    },\n    classInfo: {\n        flex: 1,\n    },\n    className: {\n        fontSize: 16,\n        fontWeight: '600',\n        color: '#2E3326',\n        marginBottom: 5,\n    },\n    instructorNameText: {\n        fontSize: 14,\n        color: '#7C8070',\n    },\n    ratingSection: {\n        backgroundColor: '#fff',\n        borderRadius: 15,\n        padding: 25,\n        marginBottom: 20,\n        alignItems: 'center',\n        shadowColor: '#000',\n        shadowOffset: { width: 0, height: 2 },\n        shadowOpacity: 0.1,\n        shadowRadius: 4,\n        elevation: 3,\n    },\n    sectionTitle: {\n        fontSize: 18,\n        fontWeight: 'bold',\n        color: '#2E3326',\n        marginBottom: 20,\n        textAlign: 'center',\n    },\n    starsContainer: {\n        flexDirection: 'row',\n        gap: 10,\n        marginBottom: 15,\n    },\n    starButton: {\n        padding: 5,\n    },\n    ratingText: {\n        fontSize: 16,\n        fontWeight: '600',\n        color: '#A3A794',\n    },\n    ratedText: {\n        color: '#ffc107',\n    },\n    reviewSection: {\n        backgroundColor: '#fff',\n        borderRadius: 15,\n        padding: 20,\n        marginBottom: 20,\n        shadowColor: '#000',\n        shadowOffset: { width: 0, height: 2 },\n        shadowOpacity: 0.1,\n        shadowRadius: 4,\n        elevation: 3,\n    },\n    reviewTextInput: {\n        borderWidth: 1,\n        borderColor: '#EEF0E4',\n        borderRadius: 10,\n        padding: 15,\n        fontSize: 16,\n        minHeight: 120,\n        color: '#2E3326',\n        backgroundColor: '#FBFAF4',\n    },\n    characterCount: {\n        textAlign: 'right',\n        fontSize: 12,\n        color: '#7C8070',\n        marginTop: 8,\n    },\n    guidelineSection: {\n        backgroundColor: '#fff',\n        borderRadius: 15,\n        padding: 20,\n        shadowColor: '#000',\n        shadowOffset: { width: 0, height: 2 },\n        shadowOpacity: 0.1,\n        shadowRadius: 4,\n        elevation: 3,\n    },\n    guidelineItem: {\n        flexDirection: 'row',\n        alignItems: 'flex-start',\n        marginBottom: 10,\n        paddingRight: 10,\n    },\n    guidelineText: {\n        fontSize: 14,\n        color: '#7C8070',\n        marginLeft: 8,\n        flex: 1,\n        lineHeight: 20,\n    },\n    submitContainer: {\n        position: 'absolute',\n        bottom: 0,\n        left: 0,\n        right: 0,\n        backgroundColor: '#fff',\n        padding: 20,\n        borderTopWidth: 1,\n        borderTopColor: '#EEF0E4',\n        ...Platform.select({\n            ios: {\n                shadowColor: '#000',\n                shadowOffset: { width: 0, height: -2 },\n                shadowOpacity: 0.1,\n                shadowRadius: 4,\n            },\n            android: {\n                elevation: 5,\n            },\n        }),\n    },\n    submitButton: {\n        backgroundColor: '#4E7D32',\n        flexDirection: 'row',\n        alignItems: 'center',\n        justifyContent: 'center',\n        paddingVertical: 15,\n        borderRadius: 10,\n        gap: 8,\n    },\n    submitButtonDisabled: {\n        backgroundColor: '#C9CCB8',\n    },\n    submitButtonText: {\n        color: '#fff',\n        fontSize: 16,\n        fontWeight: '600',\n    },\n    loadingContainer: {\n        flexDirection: 'row',\n        alignItems: 'center',\n        gap: 8,\n    },\n});\n\nexport default OnlineClassWriteReview;",
    "components/contexts/BoardContext.tsx": "import React, { createContext, useState, useContext, ReactNode, useEffect, useRef, useCallback } from 'react';\nimport AsyncStorage from '@react-native-async-storage/async-storage';\nimport { useAuth } from '@/components/contexts/AuthProvider';\n\n/**\n * 게시판 글 저장소\n * - 글은 휴대폰(AsyncStorage)에 저장돼서 앱을 껐다 켜도 남아 있어요.\n * - 로그인한 사용자가 처음 들어오면, 그 사람 이름으로 예시 글 몇 개를 넣어 줘요.\n *   (내 게시판에서 바로 '내 글'이 보이도록)\n */\n\nexport interface BoardPost {\n    id: number;\n    author: string;\n    profileImage: string | null;\n    title: string;\n    content: string;\n    category: '교육' | '운동' | '활동';\n    timeAgo: string;\n    createdAt: Date;\n}\n\ntype NewPost = Omit<BoardPost, 'id' | 'createdAt' | 'timeAgo'>;\n\ninterface BoardContextType {\n    posts: BoardPost[];\n    addPost: (newPost: NewPost) => void;\n    updatePost: (postId: number, changes: Partial<NewPost>) => void;\n    deletePost: (postId: number) => void;\n}\n\nconst STORAGE_KEY = 'boardPosts';\nconst SEEDED_KEY = (phone: string) => `boardSeeded_${phone}`;\n\nconst DAY = 24 * 60 * 60 * 1000;\nconst HOUR = 60 * 60 * 1000;\n\n// 다른 사람들이 쓴 예시 글\nconst DEFAULT_POSTS: BoardPost[] = [\n    {\n        id: 1,\n        author: '로로',\n        profileImage: null,\n        title: '일본어 같이 공부할 사람 구함',\n        content: '일본어 능력시험 준비를 함께 할 스터디원을 모집합니다. 주 2회 저녁에 온라인으로 만나요.',\n        category: '교육',\n        timeAgo: '',\n        createdAt: new Date(Date.now() - 2 * DAY),\n    },\n    {\n        id: 2,\n        author: '지지',\n        profileImage: null,\n        title: '운동하고 싶은데 어떤 헬스장이 좋아?',\n        content: '이사 왔는데 동네 헬스장 추천해주세요! PT 없이 혼자 하기 좋은 곳이면 좋겠어요.',\n        category: '운동',\n        timeAgo: '',\n        createdAt: new Date(Date.now() - 1 * DAY),\n    },\n    {\n        id: 3,\n        author: '하루',\n        profileImage: null,\n        title: '주말에 한강 플로깅 하실 분',\n        content: '토요일 오전 10시 여의나루역에서 만나요. 장갑과 봉투는 제가 준비할게요 🌿',\n        category: '활동',\n        timeAgo: '',\n        createdAt: new Date(Date.now() - 5 * HOUR),\n    },\n];\n\n// 로그인한 사용자 이름으로 넣어 줄 예시 글\nfunction makeMyPosts(name: string, profileImage: string | null): BoardPost[] {\n    const now = Date.now();\n    return [\n        {\n            id: now + 1,\n            author: name,\n            profileImage,\n            title: '캡스톤 앱 테스트 도와주실 분 찾아요',\n            content: '일정·계획·가계부를 한 번에 관리하는 앱을 만들고 있어요. 써 보고 의견 주시면 커피 쏠게요 ☕',\n            category: '활동',\n            timeAgo: '',\n            createdAt: new Date(now - 3 * HOUR),\n        },\n        {\n            id: now + 2,\n            author: name,\n            profileImage,\n            title: '한국어 회화 스터디 같이 해요',\n            content: '매주 토요일 오전 10시, 학교 도서관 스터디룸에서 1시간씩 이야기 나눠요. 초급도 환영해요!',\n            category: '교육',\n            timeAgo: '',\n            createdAt: new Date(now - 1 * DAY - 2 * HOUR),\n        },\n        {\n            id: now + 3,\n            author: name,\n            profileImage,\n            title: '저녁 7시 헬스장 같이 다닐 분',\n            content: '월·수·금 저녁 7시에 학교 체육관에서 운동해요. 같이 다니면 꾸준히 할 수 있을 것 같아요 💪',\n            category: '운동',\n            timeAgo: '',\n            createdAt: new Date(now - 3 * DAY),\n        },\n    ];\n}\n\n// 저장된 글을 다시 읽을 때 날짜(문자열)를 Date 로 되돌려요\nfunction revive(list: any[]): BoardPost[] {\n    return list.map((p) => ({ ...p, createdAt: new Date(p.createdAt) }));\n}\n\nconst BoardContext = createContext<BoardContextType | undefined>(undefined);\n\nexport const BoardProvider = ({ children }: { children: ReactNode }) => {\n    const { isAuthenticated, currentUser } = useAuth();\n    const [posts, setPosts] = useState<BoardPost[]>(DEFAULT_POSTS);\n    const loaded = useRef(false);\n\n    // 1. 앱이 켜질 때 저장된 글 불러오기\n    useEffect(() => {\n        (async () => {\n            try {\n                const saved = await AsyncStorage.getItem(STORAGE_KEY);\n                if (saved) setPosts(revive(JSON.parse(saved)));\n            } catch (e) {\n                console.log('게시글 불러오기 실패:', e);\n            } finally {\n                loaded.current = true;\n            }\n        })();\n    }, []);\n\n    // 2. 로그인한 사용자가 처음이면 그 사람 이름으로 예시 글 넣기\n    useEffect(() => {\n        const phone = currentUser?.phoneNumber;\n        const name = currentUser?.name;\n        if (!isAuthenticated || !phone || !name) return;\n        (async () => {\n            try {\n                // 불러오기가 끝날 때까지 잠깐 기다려요\n                for (let i = 0; i < 20 && !loaded.current; i++) {\n                    await new Promise((r) => setTimeout(r, 50));\n                }\n                if (await AsyncStorage.getItem(SEEDED_KEY(phone))) return;\n                await AsyncStorage.setItem(SEEDED_KEY(phone), '1');\n                setPosts((cur) => [...makeMyPosts(name, currentUser?.profileImage ?? null), ...cur]);\n            } catch (e) {\n                console.log('예시 글 넣기 실패:', e);\n            }\n        })();\n    }, [isAuthenticated, currentUser?.phoneNumber, currentUser?.name]);\n\n    // 3. 글이 바뀔 때마다 저장\n    useEffect(() => {\n        if (!loaded.current) return;\n        AsyncStorage.setItem(STORAGE_KEY, JSON.stringify(posts)).catch(() => {});\n    }, [posts]);\n\n    const addPost = useCallback((postData: NewPost) => {\n        const newPost: BoardPost = {\n            ...postData,\n            id: Date.now(),\n            createdAt: new Date(),\n            timeAgo: '방금 전',\n        };\n        setPosts((cur) => [newPost, ...cur]);\n    }, []);\n\n    const updatePost = useCallback((postId: number, changes: Partial<NewPost>) => {\n        setPosts((cur) => cur.map((p) => (p.id === postId ? { ...p, ...changes } : p)));\n    }, []);\n\n    const deletePost = useCallback((postId: number) => {\n        setPosts((cur) => cur.filter((post) => post.id !== postId));\n    }, []);\n\n    return (\n        <BoardContext.Provider value={{ posts, addPost, updatePost, deletePost }}>\n            {children}\n        </BoardContext.Provider>\n    );\n};\n\nexport const useBoard = () => {\n    const context = useContext(BoardContext);\n    if (context === undefined) {\n        throw new Error('useBoard must be used within a BoardProvider');\n    }\n    return context;\n};\n",
    "components/contexts/OnlineClassContext.tsx": "import React, { createContext, useContext, useState, ReactNode, useCallback, useMemo, useEffect, useRef } from 'react';\nimport AsyncStorage from '@react-native-async-storage/async-storage';\nimport { useAuth } from '@/components/contexts/AuthProvider';\n\n// 저장 키 (앱을 껐다 켜도 내 수업이 남아 있게)\nconst CLASSES_KEY = 'onlineClasses';\nconst VIDEOS_KEY = 'onlineClassVideos';\nconst SEEDED_KEY = (phone: string) => `classSeeded_${phone}`;\n\n// 로그인한 사용자가 처음 들어오면 넣어 주는 '내 수업' 예시\nfunction makeMyClass(name: string, phone: string, profileImage: string | null) {\n    return {\n        id: `my-${phone}`,\n        title: '왕초보 한국어 회화 첫걸음',\n        instructor: name,\n        createdBy: name,\n        phoneNumber: phone,\n        profileImage: profileImage || undefined,\n        introduction: `안녕하세요, ${name}입니다! 외국인 친구들이 한국 생활에서 바로 쓸 수 있는 회화를 쉽고 재미있게 알려 드려요.`,\n        description: '인사, 주문하기, 길 묻기처럼 매일 쓰는 표현을 짧은 영상으로 배우는 수업이에요. 영상마다 따라 말하기 연습이 있어요.',\n    };\n}\n\nconst MY_VIDEOS: VideoData[] = [\n    { id: 'my-v1', videoTitle: '1강 · 처음 만났을 때 인사하기', classTitle: '왕초보 한국어 회화 첫걸음', duration: '8분', level: '초급', type: 'free' },\n    { id: 'my-v2', videoTitle: '2강 · 카페에서 주문하기', classTitle: '왕초보 한국어 회화 첫걸음', duration: '10분', level: '초급', type: 'free' },\n    { id: 'my-v3', videoTitle: '3강 · 길 묻고 대답하기 (MVP)', classTitle: '왕초보 한국어 회화 첫걸음', duration: '15분', level: '초급', type: 'mvp', price: 3000 },\n];\n\n// Context에서 사용할 ID 타입 정의\ntype ClassId = string | number;\n\ninterface VideoData {\n    id: string;\n    videoTitle: string;\n    classTitle: string;\n    duration: string;\n    level: string;\n    type: 'free' | 'mvp';\n    price?: number;\n    uri?: string;\n    fileName?: string;\n}\n\ninterface PaymentInfo {\n    bankName: string;\n    accountNumber: string;\n    accountHolder: string;\n    fees?: Fees;\n}\n\nexport interface ClassData {\n    id?: ClassId; // ID 타입을 ClassId로 변경\n    title: string;\n    instructor: string;\n    description: string;\n    introduction: string;\n    createdBy?: string;\n    profileImage?: string;\n    phoneNumber?: string;\n    certificationImage?: string;\n    paymentStatus?: string;\n    paymentDetails?: {\n        method: string;\n        amount: number;\n        bankName: string;\n        accountNumber: string;\n        accountHolder: string;\n    };\n    // 좋아요 상태를 Context의 likedClassIds로 관리할 것이므로, ClassData에는 추가하지 않습니다.\n}\n\ninterface Fees {\n    uploadFee: number;\n    additionalVideoFee: number;\n    total: number;\n}\n\ninterface OnlineClassContextType {\n    classes: ClassData[];\n    currentClassData: ClassData | null;\n    videos: VideoData[];\n    paymentInfo: PaymentInfo | null;\n    isPaymentComplete: boolean;\n    fees: Fees;\n    // ❤️ [추가] 좋아요 상태 및 토글 함수\n    likedClassIds: ClassId[];\n    toggleLike: (classId: ClassId) => void;\n    // ---\n    setClassData: (data: ClassData) => void;\n    setCurrentClassData: (data: ClassData | null) => void;\n    setVideos: (videos: VideoData[]) => void;\n    addVideo: (video: VideoData) => void;\n    updateVideo: (id: string, field: keyof VideoData, value: any) => void;\n    removeVideo: (id: string) => void;\n    setPaymentInfo: (info: PaymentInfo) => void;\n    calculateFees: () => Fees;\n    setFees: (fees: Fees) => void;\n    addClass: (classData: ClassData) => void;\n    deleteClass: (classId: string) => void;\n    resetContext: () => void;\n    setPaymentComplete: (isComplete: boolean) => void;\n}\n\nconst OnlineClassContext = createContext<OnlineClassContextType | undefined>(undefined);\n\nexport const OnlineClassProvider: React.FC<{ children: ReactNode }> = ({ children }) => {\n    const [classes, setClasses] = useState<ClassData[]>([]);\n    const [currentClassData, setCurrentClassData] = useState<ClassData | null>(null);\n    const [videos, setVideos] = useState<VideoData[]>([]);\n    const [paymentInfo, setPaymentInfo] = useState<PaymentInfo | null>(null);\n    const [fees, setFees] = useState<Fees>({ uploadFee: 0, additionalVideoFee: 0, total: 0 });\n    const [isPaymentComplete, setPaymentComplete] = useState(false);\n\n    // ❤️ [추가] 좋아요 상태 저장 (클래스 ID 배열)\n    const [likedClassIds, setLikedClassIds] = useState<ClassId[]>([]);\n\n    const { isAuthenticated, currentUser } = useAuth();\n    const loaded = useRef(false);\n\n    // 1. 저장된 수업·영상 불러오기\n    useEffect(() => {\n        (async () => {\n            try {\n                const [c, v] = await Promise.all([AsyncStorage.getItem(CLASSES_KEY), AsyncStorage.getItem(VIDEOS_KEY)]);\n                if (c) setClasses(JSON.parse(c));\n                if (v) setVideos(JSON.parse(v));\n            } catch (e) {\n                console.log('온라인 수업 불러오기 실패:', e);\n            } finally {\n                loaded.current = true;\n            }\n        })();\n    }, []);\n\n    // 2. 로그인한 사용자가 처음이면 그 사람 이름으로 '내 수업' 넣기\n    useEffect(() => {\n        const phone = currentUser?.phoneNumber;\n        const name = currentUser?.name;\n        if (!isAuthenticated || !phone || !name) return;\n        (async () => {\n            try {\n                for (let i = 0; i < 20 && !loaded.current; i++) {\n                    await new Promise((r) => setTimeout(r, 50));\n                }\n                if (await AsyncStorage.getItem(SEEDED_KEY(phone))) return;\n                await AsyncStorage.setItem(SEEDED_KEY(phone), '1');\n                setClasses((cur) => [...cur.filter((c) => c.id !== `my-${phone}`), makeMyClass(name, phone, currentUser?.profileImage ?? null)]);\n                setVideos((cur) => (cur.length ? cur : MY_VIDEOS));\n            } catch (e) {\n                console.log('예시 수업 넣기 실패:', e);\n            }\n        })();\n    }, [isAuthenticated, currentUser?.phoneNumber, currentUser?.name]);\n\n    // 3. 바뀔 때마다 저장\n    useEffect(() => {\n        if (!loaded.current) return;\n        AsyncStorage.setItem(CLASSES_KEY, JSON.stringify(classes)).catch(() => {});\n    }, [classes]);\n    useEffect(() => {\n        if (!loaded.current) return;\n        AsyncStorage.setItem(VIDEOS_KEY, JSON.stringify(videos)).catch(() => {});\n    }, [videos]);\n\n    // ❤️ [추가] 좋아요 상태 토글 함수\n    const toggleLike = useCallback((classId: ClassId) => {\n        setLikedClassIds(prevIds => {\n            if (prevIds.includes(classId)) {\n                // 이미 좋아요 상태면 제거\n                return prevIds.filter(id => id !== classId);\n            } else {\n                // 좋아요 상태가 아니면 추가\n                return [...prevIds, classId];\n            }\n        });\n    }, []);\n    // ---\n\n    const setClassData = useCallback((data: ClassData) => {\n        // ID가 없으면 Date.now()를 사용하여 고유 ID 생성\n        const classWithId = { ...data, id: data.id || Date.now().toString() };\n        setClasses((prevClasses) => [...prevClasses, classWithId]);\n        setCurrentClassData(classWithId);\n    }, []);\n\n    const addVideo = useCallback((video: VideoData) => {\n        setVideos((prevVideos) => [...prevVideos, video]);\n    }, []);\n\n    const addClass = useCallback((classData: ClassData) => {\n        setClasses((prevClasses) => [...prevClasses, classData]);\n    }, []);\n\n    const deleteClass = useCallback((classId: string) => {\n        setClasses((prevClasses) => prevClasses.filter(cls => cls.id !== classId));\n        if (currentClassData?.id === classId) {\n            setCurrentClassData(null);\n        }\n    }, [currentClassData]);\n\n    const updateVideo = useCallback((id: string, field: keyof VideoData, value: any) => {\n        setVideos((prevVideos) =>\n            prevVideos.map((video) => (video.id === id ? { ...video, [field]: value } : video))\n        );\n    }, []);\n\n    const removeVideo = useCallback((id: string) => {\n        setVideos((prevVideos) => prevVideos.filter((video) => video.id !== id));\n    }, []);\n\n    const calculateFees = useCallback((): Fees => {\n        const baseUploadFee = 10000;\n        const videoCount = videos.length;\n        const additionalVideoFee = Math.max(0, videoCount - 1) * 5000;\n        const totalFee = baseUploadFee + additionalVideoFee;\n\n        return {\n            uploadFee: baseUploadFee,\n            additionalVideoFee,\n            total: totalFee,\n        };\n    }, [videos.length]);\n\n    const resetContext = useCallback(() => {\n        setClasses([]);\n        setCurrentClassData(null);\n        setVideos([]);\n        setPaymentInfo(null);\n        setFees({ uploadFee: 0, additionalVideoFee: 0, total: 0 });\n        setPaymentComplete(false);\n        setLikedClassIds([]); // ❤️ [추가] 좋아요 상태 초기화\n    }, []);\n\n    const contextValue = useMemo(\n        () => ({\n            classes,\n            currentClassData,\n            videos,\n            paymentInfo,\n            isPaymentComplete,\n            fees,\n            likedClassIds, // ❤️ [추가]\n            toggleLike,     // ❤️ [추가]\n            setClassData,\n            setCurrentClassData,\n            setVideos,\n            addVideo,\n            updateVideo,\n            removeVideo,\n            setPaymentInfo,\n            calculateFees,\n            setFees,\n            addClass,\n            deleteClass,\n            resetContext,\n            setPaymentComplete,\n        }),\n        [\n            classes,\n            currentClassData,\n            videos,\n            paymentInfo,\n            isPaymentComplete,\n            fees,\n            likedClassIds, // ❤️ [추가]\n            toggleLike,     // ❤️ [추가]\n            setClassData,\n            setCurrentClassData,\n            setVideos,\n            addVideo,\n            updateVideo,\n            removeVideo,\n            setPaymentInfo,\n            calculateFees,\n            setFees,\n            addClass,\n            deleteClass,\n            resetContext,\n            setPaymentComplete,\n        ]\n    );\n\n    return (\n        <OnlineClassContext.Provider value={contextValue}>\n            {children}\n        </OnlineClassContext.Provider>\n    );\n};\n\nexport const useOnlineClass = () => {\n    const context = useContext(OnlineClassContext);\n    if (context === undefined) {\n        throw new Error('useOnlineClass must be used within an OnlineClassProvider');\n    }\n    return context;\n};"
};
const root = __dirname;
const backup = path.join(root, '.backup-board');
for (const [rel, content] of Object.entries(FILES)) {
    const target = path.join(root, rel);
    if (fs.existsSync(target)) {
        const b = path.join(backup, rel);
        fs.mkdirSync(path.dirname(b), { recursive: true });
        fs.copyFileSync(target, b);
    }
    fs.mkdirSync(path.dirname(target), { recursive: true });
    fs.writeFileSync(target, content, 'utf8');
    console.log('✅', rel);
}
